BEGIN;
UPDATE hotels SET description='Country Inn & Suites by Radisson, Des Moines West is a three-story, 104-unit hotel at 1350 NW 118th Street in Clive, near Interstate 80/35 at Exit 124 (University Avenue). Breakfast is included, parking is on-site, and there is an indoor heated pool with a hot tub, an exercise room, a business center and coin laundry. Rooms have a coffeemaker, microwave and refrigerator. Pets are accepted for an additional fee. Check-in is 3 PM and check-out is 11 AM.', short_description='104-unit Clive hotel off I-80/35 Exit 124 with included breakfast, an indoor heated pool and on-site parking.', seo_title='Country Inn & Suites Des Moines West | Hotels in Clive, IA', seo_description='Country Inn & Suites Des Moines West in Clive: 104 units off I-80/35 Exit 124, breakfast included, indoor heated pool, on-site parking, pets for a fee.', seo_h1='Country Inn & Suites by Radisson, Des Moines West (Clive, IA)', geo_summary='Country Inn & Suites by Radisson, Des Moines West is a 104-unit hotel in Clive, just off Interstate 80/35 at Exit 124. It suits drivers and families who want breakfast included, an indoor pool and rooms with a microwave and refrigerator on the west side of the metro.', geo_key_facts=ARRAY['1350 NW 118th Street, Clive, IA','104 units on three stories','Near I-80/35 Exit 124 (University Ave)','Breakfast included; indoor heated pool and hot tub','Check-in 3 PM, check-out 11 AM','Pets accepted for an additional fee']::text[], geo_faq='[{"question":"Is breakfast included at Country Inn & Suites Des Moines West?","answer":"Yes. AAA lists breakfast as included."},{"question":"Does the hotel allow pets?","answer":"Yes, pets are accepted for an additional fee. Confirm the current fee with the hotel."},{"question":"What are check-in and check-out times?","answer":"Check-in is 3 PM and check-out is 11 AM."}]'::jsonb, updated_at=now() WHERE id='392cecf8-73a2-46ac-b9b3-3be3a928719c';
UPDATE hotels SET description='Courtyard by Marriott Ames is a four-floor, 119-room hotel at 311 S 17th Street in Ames, built in 2020 and close to Iowa State University and Reiman Gardens. The on-site restaurant, The Bistro, serves breakfast, dinner and cocktails. There is an indoor pool, a fitness center and a business center, and Wi-Fi and on-site parking are free. Pets are not allowed, though service animals are welcome without a fee. Check-in is 3 PM and check-out is 11 AM.', short_description='119-room Ames hotel built in 2020 near Iowa State University, with The Bistro, an indoor pool and free parking.', seo_title='Courtyard by Marriott Ames | Hotels in Ames, IA', seo_description='Courtyard Ames: 119 rooms near Iowa State University and Reiman Gardens, with The Bistro restaurant, an indoor pool, free Wi-Fi and free on-site parking.', seo_h1='Courtyard by Marriott Ames', geo_summary='Courtyard by Marriott Ames is a 119-room hotel on S 17th Street in Ames, opened in 2020 near Iowa State University and Reiman Gardens. It fits ISU visitors, parents and business travellers who want an on-site restaurant, an indoor pool and free parking.', geo_key_facts=ARRAY['311 S 17th St, Ames, IA','119 rooms on four floors, built 2020','The Bistro serves breakfast, dinner and cocktails','Indoor pool, fitness center, free parking and Wi-Fi','Check-in 3 PM, check-out 11 AM','No pets; service animals welcome']::text[], geo_faq='[{"question":"Is Courtyard Ames near Iowa State University?","answer":"Yes. It is listed as near Iowa State University and Reiman Gardens."},{"question":"Does Courtyard Ames allow pets?","answer":"No. Pets are not allowed, but service animals are welcome without a fee."},{"question":"Is parking free at Courtyard Ames?","answer":"Yes, on-site parking is complimentary."}]'::jsonb, updated_at=now() WHERE id='09a2908f-8786-4379-a7d9-a1592f43f690';
UPDATE hotels SET description='Courtyard by Marriott Des Moines Ankeny is a four-story, 119-room hotel at 2405 SE Creekview Drive in Ankeny, off Interstate 35 at Exit 90. It has a restaurant with a full-bar lounge, an indoor heated pool, a fitness center, a business center and coin laundry, and parking is on-site. Rooms include a coffeemaker, microwave and refrigerator. Check-in is 3 PM and check-out is 11 AM, which makes it a practical base for trips north of Des Moines along I-35.', short_description='119-room Ankeny hotel off I-35 Exit 90 with a restaurant and bar, indoor heated pool and on-site parking.', seo_title='Courtyard Des Moines Ankeny | Hotels in Ankeny, IA', seo_description='Courtyard by Marriott Des Moines Ankeny: 119 rooms off I-35 Exit 90 with a restaurant and lounge, indoor heated pool, fitness center and on-site parking.', seo_h1='Courtyard by Marriott Des Moines Ankeny', geo_summary='Courtyard by Marriott Des Moines Ankeny is a 119-room hotel on SE Creekview Drive in Ankeny, just off I-35 at Exit 90. It suits business travellers and road-trippers on the north side of the metro who want a restaurant, bar and indoor pool on site.', geo_key_facts=ARRAY['2405 SE Creekview Dr, Ankeny, IA','119 rooms on four stories','Off I-35 at Exit 90','Restaurant and full-bar lounge; indoor heated pool','Check-in 3 PM, check-out 11 AM']::text[], geo_faq='[{"question":"Which I-35 exit is Courtyard Des Moines Ankeny near?","answer":"It is off Interstate 35 at Exit 90."},{"question":"Does the hotel have a pool?","answer":"Yes, an indoor heated pool."},{"question":"What are check-in and check-out times?","answer":"Check-in is 3 PM and check-out is 11 AM."}]'::jsonb, updated_at=now() WHERE id='0c42469a-0edf-45cb-95ba-938522a2f7eb';
UPDATE hotels SET description='Courtyard by Marriott Des Moines West/Clive is a three-level hotel with 108 rooms at 1520 NW 114th Street in Clive, on the west side of the Des Moines metro. The on-site Bistro serves breakfast and dinner with an evening bar, and the hotel has an indoor pool, a fitness center with cardio equipment and free weights, a 24-hour business center and a 24-hour Market for snacks and drinks. Rooms have a microwave, refrigerator and coffeemaker. It is a smoke-free property.', short_description='108-room Clive hotel on NW 114th Street with The Bistro, an indoor pool, a fitness center and a 24-hour Market.', seo_title='Courtyard Des Moines West/Clive | Hotels in Clive, IA', seo_description='Courtyard Des Moines West/Clive: 108 rooms on NW 114th Street with The Bistro for breakfast and dinner, an indoor pool, fitness center and 24-hour Market.', seo_h1='Courtyard by Marriott Des Moines West/Clive', geo_summary='Courtyard by Marriott Des Moines West/Clive is a 108-room hotel on NW 114th Street in Clive. It works for business travellers and visitors to the western suburbs who want an on-site restaurant and bar, an indoor pool and a fitness center.', geo_key_facts=ARRAY['1520 NW 114th St, Clive, IA','108 rooms on three levels','The Bistro: breakfast, dinner and evening bar','Indoor pool and fitness center','24-hour business center and Market','Smoke-free property']::text[], geo_faq='[{"question":"Does Courtyard Des Moines West/Clive have a restaurant?","answer":"Yes. The Bistro serves breakfast and dinner and has an evening bar."},{"question":"Is there a pool?","answer":"Yes, the hotel has an indoor pool."},{"question":"Can I smoke at the hotel?","answer":"No, it is a smoke-free property."}]'::jsonb, updated_at=now() WHERE id='553b6d13-8013-4592-84b5-31c566c54e66';
UPDATE hotels SET description='Courtyard by Marriott West Des Moines Jordan Creek has 102 rooms, including 4 suites, over four floors at 410 S 68th Street, at the junction of Stagecoach Drive and 68th Street in West Des Moines. It has an on-site restaurant, a pool, a fitness center, a business center and free parking. Check-in is 3 PM and check-out is noon, and Marriott sets the minimum check-in age at 21. Arbor Lodging Partners acquired the hotel in 2017.', short_description='102-room West Des Moines hotel at Stagecoach Dr and 68th St with an on-site restaurant, pool and free parking.', seo_title='Courtyard Jordan Creek | Hotels in West Des Moines, IA', seo_description='Courtyard West Des Moines Jordan Creek: 102 rooms and 4 suites at Stagecoach Dr and 68th St, with an on-site restaurant, pool, fitness center and free parking.', seo_h1='Courtyard by Marriott West Des Moines Jordan Creek', geo_summary='Courtyard by Marriott West Des Moines Jordan Creek is a 102-room hotel on S 68th Street in West Des Moines, at the corner of Stagecoach Drive. It suits travellers staying on the west side who want a restaurant, pool and free parking at the hotel.', geo_key_facts=ARRAY['410 S 68th St, West Des Moines, IA','102 rooms including 4 suites, four floors','Pool, fitness center, on-site restaurant','Free parking','Check-in 3 PM, check-out 12 PM; minimum check-in age 21']::text[], geo_faq='[{"question":"Is parking free at Courtyard Jordan Creek?","answer":"Yes, parking is free."},{"question":"What is the minimum age to check in?","answer":"Marriott lists a minimum check-in age of 21."},{"question":"What time is check-out?","answer":"Check-out is at 12 PM; check-in starts at 3 PM."}]'::jsonb, updated_at=now() WHERE id='232c70ef-7dd1-4867-9aad-bd22ba7831ee';
UPDATE hotels SET description='Days Inn & Suites by Wyndham Des Moines Airport sits at 1901 Hackley Avenue, across from Des Moines International Airport on the south side of the city. It runs a free 24/7 shuttle to DSM, serves a free expanded hot breakfast, and has a heated indoor pool, an exercise room and free parking, with long-term parking available (fees may apply). Some suites have jetted tubs, and a 735-square-foot meeting room holds up to 35. Blank Park Zoo and the Iowa State Fairgrounds are among the nearby sights the hotel lists.', short_description='Airport hotel across from DSM with a free 24/7 shuttle, free hot breakfast, indoor pool and free parking.', seo_title='Days Inn & Suites Des Moines Airport | Hotels in Des Moines', seo_description='Days Inn & Suites Des Moines Airport, across from DSM: free 24/7 airport shuttle, free hot breakfast, heated indoor pool and free parking on Hackley Ave.', seo_h1='Days Inn & Suites by Wyndham Des Moines Airport', geo_summary='Days Inn & Suites by Wyndham Des Moines Airport is a budget-chain hotel on Hackley Avenue directly across from Des Moines International Airport. It is aimed at travellers with early flights or long-term parking needs, with a free round-the-clock airport shuttle and free hot breakfast.', geo_key_facts=ARRAY['1901 Hackley Ave, Des Moines, IA','Across from Des Moines International Airport','Free 24/7 airport shuttle','Free expanded hot breakfast','Heated indoor pool and exercise room','Free parking; long-term parking available (fees may apply)']::text[], geo_faq='[{"question":"Does the Days Inn Des Moines Airport have an airport shuttle?","answer":"Yes, a free shuttle to Des Moines International Airport runs 24/7."},{"question":"Is breakfast included?","answer":"Yes, a free expanded hot breakfast is served."},{"question":"Can I leave my car while I travel?","answer":"Long-term parking is available; the hotel notes fees may apply."}]'::jsonb, updated_at=now() WHERE id='195d39bd-21e7-4f8c-beeb-07c88e6727e2';
UPDATE hotels SET description='Days Inn by Wyndham Ankeny - Des Moines is a pet-friendly motel at 105 NE Delaware Avenue in Ankeny, a short drive north of downtown Des Moines and minutes from Ankeny Regional Airport. Parking and a light breakfast with coffee, tea and juice are free, and there is a 24-hour front desk and guest laundry. Some rooms and suites have a microwave, refrigerator or hot tub. Prairie Meadows Racetrack and Casino, Adventureland and the Prairie Ridge Sports Complex are among the attractions the hotel lists nearby.', short_description='Pet-friendly Ankeny motel on NE Delaware Ave with free parking, free light breakfast and a 24-hour front desk.', seo_title='Days Inn Ankeny - Des Moines | Hotels in Ankeny, IA', seo_description='Days Inn by Wyndham Ankeny on NE Delaware Ave: pet-friendly, free parking, free light breakfast, guest laundry and a 24-hour desk north of Des Moines.', seo_h1='Days Inn by Wyndham Ankeny - Des Moines', geo_summary='Days Inn by Wyndham Ankeny - Des Moines is a pet-friendly economy motel on NE Delaware Avenue in Ankeny. It suits budget travellers, people with pets and sports families heading to Prairie Ridge who want free parking and breakfast.', geo_key_facts=ARRAY['105 NE Delaware Ave, Ankeny, IA','Pet-friendly','Free parking and free light breakfast','24-hour front desk and guest laundry','Minutes from Ankeny Regional Airport']::text[], geo_faq='[{"question":"Is the Days Inn Ankeny pet-friendly?","answer":"Yes, Wyndham describes it as pet-friendly. Check the hotel''s pet policy for fees and limits."},{"question":"Does it serve breakfast?","answer":"Yes, a free light breakfast with coffee, tea and juice."},{"question":"Is parking free?","answer":"Yes, parking is free."}]'::jsonb, updated_at=now() WHERE id='67cc2d5d-b924-4761-9d87-7c6b2f7f7d02';
UPDATE hotels SET description='Days Inn by Wyndham West Des Moines / Clive is at 1600 NW 114th Street in Clive, right off I-80 and less than 10 miles from downtown Des Moines, according to the hotel. It serves a free light breakfast with coffee, tea and juice, offers free Wi-Fi to Wyndham Rewards members, and rooms have a microwave and refrigerator. The hotel is dog-friendly and has accessible rooms. Adventureland, Adventure Bay, Living History Farms and Prairie Meadows are among the attractions it lists in the area.', short_description='Dog-friendly Clive hotel right off I-80 with free light breakfast and in-room microwaves and refrigerators.', seo_title='Days Inn West Des Moines / Clive | Hotels in Clive, IA', seo_description='Days Inn by Wyndham West Des Moines / Clive: dog-friendly, right off I-80 on NW 114th St, free light breakfast, microwave and fridge in every room.', seo_h1='Days Inn by Wyndham West Des Moines / Clive', geo_summary='Days Inn by Wyndham West Des Moines / Clive is an economy hotel on NW 114th Street in Clive, right off Interstate 80. It suits budget travellers and dog owners who want free breakfast and a microwave and refrigerator in the room.', geo_key_facts=ARRAY['1600 NW 114th St, Clive, IA','Right off I-80','Less than 10 miles from downtown Des Moines (per hotel)','Free light breakfast','Dog-friendly; accessible rooms','In-room microwave and refrigerator']::text[], geo_faq='[{"question":"How far is the Days Inn Clive from downtown Des Moines?","answer":"The hotel says it is less than 10 miles from downtown Des Moines."},{"question":"Does it allow dogs?","answer":"Yes, Wyndham describes it as dog-friendly. Check the pet policy for fees."},{"question":"Is breakfast free?","answer":"Yes, a free light breakfast with coffee, tea and juice."}]'::jsonb, updated_at=now() WHERE id='f2ef96da-09f5-47ea-ba00-84a4c80c328b';
UPDATE hotels SET description='Des Lux Hotel is a 51-room independent boutique hotel at 800 Locust Street in downtown Des Moines, in the building completed in 1913 as the Des Moines Club. It first opened as a hotel in 2001 as Suites of 800 Locust and is now operated by Rebound Hospitality, whose sister property is The Celeste St. Paul Hotel + Bar. Guests have the Des Lux Bar, breakfast, a fitness and wellness offering, ADA-accessible features and event space. It is a pet-free hotel (service animals only). Check-in is 3 PM, check-out 11 AM.', short_description='51-room downtown Des Moines boutique hotel in the 1913 Des Moines Club building, with the Des Lux Bar.', seo_title='Des Lux Hotel | Boutique Hotel in Downtown Des Moines, IA', seo_description='Des Lux Hotel: 51 rooms at 800 Locust St in downtown Des Moines, in the 1913 Des Moines Club building, with the Des Lux Bar, breakfast and event space.', seo_h1='Des Lux Hotel, Des Moines', geo_summary='Des Lux Hotel is a 51-room boutique hotel at 800 Locust Street in downtown Des Moines, set in the former Des Moines Club building from 1913. It is for travellers who want a small independent hotel with a bar downtown rather than a large chain property.', geo_key_facts=ARRAY['800 Locust St, downtown Des Moines','51 rooms, independent boutique hotel','Building completed 1913 as the Des Moines Club','Operated by Rebound Hospitality','Check-in 3 PM, check-out 11 AM','Pet-free; service animals only']::text[], geo_faq='[{"question":"Does Des Lux Hotel allow pets?","answer":"No. It is a pet-free hotel; service animals are allowed."},{"question":"What are check-in and check-out times?","answer":"Check-in is 3 PM and check-out is 11 AM."},{"question":"Is there a bar at Des Lux Hotel?","answer":"Yes, the Des Lux Bar is on site."}]'::jsonb, updated_at=now() WHERE id='3910485b-376f-477f-8c55-220e28f6b197';
UPDATE hotels SET description='Des Moines Marriott Downtown is a 417-room hotel at 700 Grand Avenue, in a 33-story tower completed in 1981 and connected to the downtown Des Moines skywalk system. It has a pool, a fitness center, an on-site restaurant, a bar and lounge, a business center and suites. SRE Bulldog Hotel Owner bought it in January 2017 and planned a full guestroom and public-area renovation. Check-in is 4 PM and check-out noon; the minimum check-in age is 21, and only service animals are allowed.', short_description='417-room downtown tower on Grand Avenue, linked to the Des Moines skywalk, with a pool, restaurant and bar.', seo_title='Des Moines Marriott Downtown | Hotels in Des Moines, IA', seo_description='Des Moines Marriott Downtown: 417 rooms in a 33-story tower at 700 Grand Ave, connected to the skywalk, with a pool, restaurant, bar and fitness center.', seo_h1='Des Moines Marriott Downtown', geo_summary='Des Moines Marriott Downtown is a 417-room full-service hotel in a 33-story tower on Grand Avenue, connected to the downtown skywalk. It suits conference-goers and business travellers who want to reach downtown offices and venues indoors.', geo_key_facts=ARRAY['700 Grand Ave, downtown Des Moines','417 rooms in a 33-story tower (1981)','Connected to the downtown skywalk system','Pool, fitness center, restaurant, bar/lounge','Check-in 4 PM, check-out 12 PM; minimum age 21','No pets; service animals only']::text[], geo_faq='[{"question":"Is the Des Moines Marriott Downtown on the skywalk?","answer":"Yes, it is connected to the downtown Des Moines skywalk system."},{"question":"What time is check-in?","answer":"Check-in is 4 PM and check-out is 12 PM. The minimum check-in age is 21."},{"question":"Are pets allowed?","answer":"No. Only service animals are allowed."}]'::jsonb, updated_at=now() WHERE id='343759c6-18ea-474e-b354-14e24a020a49';
UPDATE hotels SET description='Drury Inn & Suites West Des Moines is a 180-room hotel at 5505 Mills Civic Parkway, next to West Glen Town Center and, per Drury, 2 miles from Jordan Creek Town Center and 11 miles from Des Moines International Airport. Hot breakfast, the 5:30 Kickback (hot food and drinks, 5:30-7 p.m.), lobby soda and popcorn from 4-8 p.m., Wi-Fi and parking are all free. There is an indoor/outdoor pool and whirlpool, a 24-hour fitness center and two meeting rooms. Dogs and cats are accepted for a fee.', short_description='180-room hotel next to West Glen Town Center with free hot breakfast, the free 5:30 Kickback and free parking.', seo_title='Drury Inn & Suites West Des Moines | West Des Moines Hotels', seo_description='Drury Inn & Suites West Des Moines: 180 rooms by West Glen Town Center, free hot breakfast and 5:30 Kickback, indoor/outdoor pool, free parking.', seo_h1='Drury Inn & Suites West Des Moines', geo_summary='Drury Inn & Suites West Des Moines is a 180-room hotel on Mills Civic Parkway, next to West Glen Town Center and 2 miles from Jordan Creek Town Center. It suits families and longer-stay travellers who want free hot breakfast, a free evening meal and free parking.', geo_key_facts=ARRAY['5505 Mills Civic Pkwy, West Des Moines, IA','180 rooms; smoke-free','2 miles from Jordan Creek Town Center; 11 miles from DSM airport','Free hot breakfast and free 5:30 Kickback','Indoor/outdoor pool and whirlpool','Check-in 3 PM, check-out 11 AM']::text[], geo_faq='[{"question":"How far is Drury Inn & Suites West Des Moines from Jordan Creek Town Center?","answer":"Drury says it is 2 miles from Jordan Creek Town Center and adjacent to West Glen Town Center."},{"question":"Does Drury West Des Moines allow pets?","answer":"Yes. Dogs and cats are accepted for $50 per room per day plus tax, up to two pets with a combined weight of 80 lbs. Service animals stay free."},{"question":"What is the 5:30 Kickback?","answer":"A free nightly serving of hot food and drinks from 5:30 to 7 p.m."}]'::jsonb, updated_at=now() WHERE id='f90ad6e2-70b4-44c8-8804-293f1a6b82d6';
UPDATE hotels SET description='Econo Lodge Ankeny - Des Moines is a two-floor, 56-room motel at 2602 SE Creekview Drive in Ankeny, about 0.2 miles from Exit 90 on I-35. All rooms are non-smoking, and three are accessible. A free hot breakfast runs 6 to 9 a.m., the indoor pool is open 9 a.m. to 10 p.m., and Wi-Fi and parking are free. Dogs are allowed for a nightly fee (no cats); service animals are accepted. Check-in is 3 PM and check-out is 11 AM. The listing puts Des Moines International Airport about 20 miles away.', short_description='56-room Ankeny motel near I-35 Exit 90 with free hot breakfast, an indoor pool and free parking.', seo_title='Econo Lodge Ankeny - Des Moines | Hotels in Ankeny, IA', seo_description='Econo Lodge Ankeny: 56 non-smoking rooms near I-35 Exit 90, free hot breakfast 6-9 a.m., indoor pool, free Wi-Fi and parking; dogs allowed for a fee.', seo_h1='Econo Lodge Ankeny - Des Moines', geo_summary='Econo Lodge Ankeny - Des Moines is a 56-room economy motel on SE Creekview Drive, just off I-35 at Exit 90 in Ankeny. It suits budget travellers and drivers on I-35 who want free hot breakfast, an indoor pool and free parking.', geo_key_facts=ARRAY['2602 SE Creekview Dr, Ankeny, IA','56 non-smoking rooms on two floors','About 0.2 miles from I-35 Exit 90','Free hot breakfast 6-9 a.m.; indoor pool','Check-in 3 PM, check-out 11 AM','Dogs allowed for a fee; no cats']::text[], geo_faq='[{"question":"Does Econo Lodge Ankeny serve breakfast?","answer":"Yes, a free hot breakfast from 6 to 9 a.m. with eggs, sausage, biscuits and gravy, and waffles."},{"question":"Are pets allowed?","answer":"Dogs are allowed for a nightly fee that depends on weight; cats are not. Service animals are accepted. Confirm the fee with the hotel."},{"question":"How far is it from Des Moines International Airport?","answer":"The listing puts the airport about 20 miles away."}]'::jsonb, updated_at=now() WHERE id='4b86f1cf-f8a2-44c8-96f0-84c2e1bd7bfb';
UPDATE hotels SET description='Econo Lodge Inn & Suites Des Moines Fairgrounds Area is at 410 E 30th Street on the east side of Des Moines, about 0.5 miles from the Iowa State Fairgrounds and 1.6 miles from Sleepy Hollow Sports Park. It serves a free continental breakfast and has an indoor pool with a pool hoist, free self-parking, free Wi-Fi, an elevator and a 24-hour front desk. Accessible rooms and parking spaces are available. Parking is limited, which is worth knowing before driving in during the Iowa State Fair.', short_description='East-side Des Moines motel about 0.5 miles from the Iowa State Fairgrounds, with free breakfast and an indoor pool.', seo_title='Econo Lodge Fairgrounds Area | Hotels in Des Moines, IA', seo_description='Econo Lodge Inn & Suites Fairgrounds Area: about 0.5 miles from the Iowa State Fairgrounds, free continental breakfast, indoor pool, free self-parking.', seo_h1='Econo Lodge Inn & Suites Des Moines Fairgrounds Area', geo_summary='Econo Lodge Inn & Suites Des Moines Fairgrounds Area is an economy motel on E 30th Street, about half a mile from the Iowa State Fairgrounds. It suits State Fair visitors and east-side event-goers who want a short trip to the grounds, free breakfast and an indoor pool.', geo_key_facts=ARRAY['410 E 30th St, Des Moines, IA','About 0.5 miles from the Iowa State Fairgrounds','1.6 miles from Sleepy Hollow Sports Park','Free continental breakfast','Indoor pool; free self-parking (limited spaces)','24-hour front desk']::text[], geo_faq='[{"question":"How close is Econo Lodge Fairgrounds to the Iowa State Fairgrounds?","answer":"The listing puts it about 0.5 miles from the Iowa State Fairgrounds."},{"question":"Is breakfast included?","answer":"Yes, a free continental breakfast."},{"question":"Is parking free?","answer":"Self-parking is free, but spaces are limited."}]'::jsonb, updated_at=now() WHERE id='99a8c02e-74e1-4f36-9fef-f2cdfad61794';
UPDATE hotels SET description='Element West Des Moines is a 110-room extended-stay hotel at 575 South Prairie View Drive, about one mile from Jordan Creek Town Center and about 11 miles from Des Moines International Airport, per Marriott. Every room has a kitchenette with a microwave, coffee maker and mini-refrigerator, and the Rise breakfast buffet is free. There is an indoor pool, a whirlpool, a 24-hour fitness center, EV charging and free on-site parking. Three event rooms hold up to 55 in the largest. Pets are welcome, up to two per room.', short_description='110-room extended-stay hotel near Jordan Creek Town Center with kitchenettes, free breakfast and EV charging.', seo_title='Element West Des Moines | Hotels in West Des Moines, IA', seo_description='Element West Des Moines: 110 extended-stay rooms with kitchenettes about a mile from Jordan Creek Town Center, free breakfast, indoor pool, pets welcome.', seo_h1='Element West Des Moines', geo_summary='Element West Des Moines is a 110-room extended-stay hotel on South Prairie View Drive, about a mile from Jordan Creek Town Center. It suits longer stays, relocations and travellers with pets or electric cars who want a kitchenette and free breakfast.', geo_key_facts=ARRAY['575 S Prairie View Dr, West Des Moines, IA','110 rooms, all with kitchenettes; built 2017','About 1 mile from Jordan Creek Town Center','Free Rise breakfast buffet; indoor pool','EV charging and free on-site parking','Check-in 3 PM, check-out 12 PM']::text[], geo_faq='[{"question":"How far is Element West Des Moines from Jordan Creek Town Center?","answer":"Marriott puts it about one mile from Jordan Creek Town Center."},{"question":"Does Element West Des Moines allow pets?","answer":"Yes, up to two pets per room with a 100 lb limit per pet. Marriott''s pages list different fees, so confirm with the hotel."},{"question":"Is breakfast free?","answer":"Yes, the Rise breakfast buffet is complimentary."}]'::jsonb, updated_at=now() WHERE id='bcad45ed-1962-432d-a689-209c4d1be12c';
UPDATE hotels SET description='Holiday Inn Express Ames is a 75-room hotel at 2600 E 13th St, on the east side of Ames off I-35 exit 113 at 13th Street. It keeps things simple: free breakfast from 6:00 to 9:30 AM, an indoor pool, a fitness center, free Wi-Fi and free parking. There is no on-site restaurant, so plan to eat breakfast here and dinner elsewhere in town. Check-in is at 3:00 PM and check-out at 11:00 AM. Pets are not allowed, though service animals are welcome.', short_description='75-room Holiday Inn Express off I-35 exit 113 in Ames, with free breakfast, an indoor pool and free parking.', seo_title='Holiday Inn Express Ames | Hotels in Ames, IA', seo_description='Holiday Inn Express Ames sits off I-35 exit 113 at 13th Street, with 75 rooms, free breakfast, an indoor pool, free Wi-Fi and free parking.', seo_h1='Holiday Inn Express Ames', geo_summary='Holiday Inn Express Ames is a 75-room hotel off I-35 exit 113 on the east side of Ames, Iowa. It suits drivers who want an easy interstate stop with free breakfast, an indoor pool and free parking.', geo_key_facts=ARRAY['75 rooms at 2600 E 13th St, Ames','Off I-35 exit 113 at 13th Street','Free breakfast 6:00-9:30 AM','Indoor pool, fitness center, free parking','No on-site restaurant','Check-in 3:00 PM, check-out 11:00 AM']::text[], geo_faq='[{"question":"Does Holiday Inn Express Ames serve breakfast?","answer":"Yes. Breakfast is free and runs from 6:00 to 9:30 AM."},{"question":"Are pets allowed at Holiday Inn Express Ames?","answer":"No. Pets are not allowed, but service animals are."},{"question":"What are check-in and check-out times?","answer":"Check-in is at 3:00 PM and check-out is at 11:00 AM."}]'::jsonb, updated_at=now() WHERE id='08611d95-0961-4acc-b5a0-73436a09df28';
UPDATE hotels SET description='Home2 Suites by Hilton Altoona Des Moines is a 90-suite extended-stay hotel at 255 Adventureland Drive NW in Altoona. The hotel puts itself two miles from Prairie Meadows Casino and Racetrack and Adventureland Park. Stays include a free hot breakfast, an indoor pool, a fitness center, free parking and free WiFi, plus on-site EV charging and Hilton''s Digital Key. Two meeting rooms add up to 834 sq ft. Dogs and cats are allowed (two max, 50 lb limit) for a non-refundable fee. Check-in 3:00 PM, check-out 11:00 AM.', short_description='90-suite extended-stay Home2 in Altoona, two miles from Adventureland and Prairie Meadows, with free breakfast and EV charging.', seo_title='Home2 Suites Altoona Des Moines | Hotels in Altoona, IA', seo_description='Home2 Suites by Hilton Altoona is a 90-suite extended-stay hotel two miles from Adventureland and Prairie Meadows, with free hot breakfast and a pool.', seo_h1='Home2 Suites by Hilton Altoona Des Moines', geo_summary='Home2 Suites by Hilton Altoona Des Moines is a 90-suite extended-stay hotel on Adventureland Drive in Altoona, Iowa. It fits families visiting Adventureland, Prairie Meadows guests and pet owners on longer stays.', geo_key_facts=ARRAY['90 suites at 255 Adventureland Drive NW, Altoona','Two miles from Prairie Meadows and Adventureland Park, per the hotel','Free hot breakfast, indoor pool, free parking','On-site EV charging','Two meeting rooms, 834 sq ft total','Dogs and cats allowed, max two, 50 lb limit']::text[], geo_faq='[{"question":"How far is Home2 Suites Altoona from Adventureland?","answer":"The hotel says it is two miles from Adventureland Park and from Prairie Meadows Casino and Racetrack."},{"question":"Is Home2 Suites Altoona pet friendly?","answer":"Yes, for up to two dogs or cats of 50 lb or less. The non-refundable fee is $75 for 1-4 nights or $125 for 5 or more nights, plus taxes."},{"question":"Does the hotel have EV charging?","answer":"Yes, EV charging is on site."}]'::jsonb, updated_at=now() WHERE id='dce1ac31-eec7-488b-b4bd-d3c436c4d0d4';
UPDATE hotels SET description='Home2 Suites by Hilton Ames is a four-story, 90-suite hotel at 2125 Isaac Newton Dr, near where I-35 meets US 30. It is about three miles from Iowa State University and the ISU Research Park, and within four miles of 3M, USDA, Barilla and the National Animal Disease Center, which makes it a practical base for work trips. Every suite has a microwave, refrigerator and coffeemaker. There is a free hot breakfast buffet, an indoor heated pool, a fitness center, coin laundry and on-site parking. Check-in 3:00 PM, check-out 11:00 AM.', short_description='90-suite Home2 near I-35 and US 30, about three miles from Iowa State University, with free hot breakfast and a heated pool.', seo_title='Home2 Suites by Hilton Ames | Hotels in Ames, IA', seo_description='Home2 Suites by Hilton Ames is a 90-suite hotel near I-35 and US 30, about three miles from Iowa State University, with free hot breakfast.', seo_h1='Home2 Suites by Hilton Ames', geo_summary='Home2 Suites by Hilton Ames is an all-suites, extended-stay hotel near the I-35 and US 30 interchange, about three miles from Iowa State University. It suits ISU visitors and business travelers headed to the ISU Research Park, 3M, USDA or Barilla.', geo_key_facts=ARRAY['Four-story, 90-suite hotel at 2125 Isaac Newton Dr','Near I-35 and US 30','About three miles from Iowa State University and ISU Research Park','Free hot breakfast buffet and indoor heated pool','Suites have microwave, refrigerator and coffeemaker','Pet-friendly for an added fee']::text[], geo_faq='[{"question":"How far is Home2 Suites Ames from Iowa State University?","answer":"About three miles from Iowa State University and the ISU Research Park."},{"question":"Is breakfast included?","answer":"Yes, a complimentary hot breakfast buffet is served."},{"question":"Does Home2 Suites Ames allow pets?","answer":"Yes, pets are allowed for an additional fee, according to AAA."}]'::jsonb, updated_at=now() WHERE id='9245af9a-f336-4a5f-aa5e-c9fb3a277c33';
UPDATE hotels SET description='Home2 Suites by Hilton Ankeny is an extended-stay hotel at 1230 SW District Dr in Ankeny''s District at Prairie Trail, about 170 meters from the Ankeny Kirkendall Public Library and steps from restaurants like Toast. It opened in 2024. A free breakfast buffet runs from 6:00 to 10:00 AM daily, and there is a heated indoor pool with a pool lift and ramp. The DMACC Ankeny campus is just over a mile away, according to the property listing. Check-in starts at 3:00 PM.', short_description='Extended-stay Home2 Suites in Ankeny''s District at Prairie Trail, opened 2024, with free breakfast and a heated indoor pool.', seo_title='Home2 Suites by Hilton Ankeny | Hotels in Ankeny, IA', seo_description='Home2 Suites by Hilton Ankeny opened in 2024 on SW District Dr near the Kirkendall Public Library, with free breakfast and a heated indoor pool.', seo_h1='Home2 Suites by Hilton Ankeny', geo_summary='Home2 Suites by Hilton Ankeny is an extended-stay hotel that opened in 2024 in the District at Prairie Trail in Ankeny, Iowa. It suits longer stays and visitors to DMACC''s Ankeny campus who want breakfast included and restaurants within walking distance.', geo_key_facts=ARRAY['Extended-stay hotel at 1230 SW District Dr, Ankeny','Opened in 2024','Free breakfast buffet 6:00-10:00 AM','Heated indoor pool with lift and ramp','About 170 m from the Ankeny Kirkendall Public Library','DMACC Ankeny campus just over a mile away']::text[], geo_faq='[{"question":"Does Home2 Suites Ankeny include breakfast?","answer":"Yes. A free breakfast buffet is served daily from 6:00 to 10:00 AM."},{"question":"Does the hotel have a pool?","answer":"Yes, a heated indoor pool, with a pool lift and ramp for accessibility."},{"question":"How far is it from DMACC in Ankeny?","answer":"The property listing puts the DMACC Ankeny campus just over a mile away."}]'::jsonb, updated_at=now() WHERE id='1da61b21-0c75-42c5-aa34-6b65f6608d8f';
UPDATE hotels SET description='Home2 Suites Des Moines at Drake University is a five-story, 124-room all-suite hotel at 2650 University Ave, on the Drake University campus. First Hospitality opened it in November 2020, with queen and king suites that each have a full kitchenette. Street-level retail and restaurant space sits in the same building. Guests get an indoor saline pool and an outdoor patio with a firepit, and two meeting spaces total just over 1,000 sq ft. The opening release describes it as a short drive from downtown Des Moines and the airport.', short_description='124-room all-suite Home2 on the Drake University campus, with kitchenettes, an indoor saline pool and a firepit patio.', seo_title='Home2 Suites at Drake University | Hotels in Des Moines', seo_description='Home2 Suites Des Moines at Drake University has 124 suites with kitchenettes on University Ave, plus an indoor saline pool and an outdoor firepit patio.', seo_h1='Home2 Suites Des Moines at Drake University', geo_summary='Home2 Suites Des Moines at Drake University is a 124-room, all-suite extended-stay hotel on the Drake campus at 2650 University Ave. It suits visiting Drake families, campus guests and longer stays that need a kitchenette.', geo_key_facts=ARRAY['124 rooms at 2650 University Ave, on the Drake campus','Opened November 2020, operated by First Hospitality','Five-story, all-suite building with street-level retail','Full kitchenettes in every room','Indoor saline pool and outdoor firepit patio','Two meeting spaces, just over 1,000 sq ft']::text[], geo_faq='[{"question":"Is Home2 Suites on the Drake University campus?","answer":"Yes. It is at 2650 University Ave, on the Drake University campus."},{"question":"Do rooms have kitchens?","answer":"Every room has a full kitchenette."},{"question":"Does the hotel have a pool?","answer":"Yes, an indoor saline pool, plus an outdoor patio with a firepit."}]'::jsonb, updated_at=now() WHERE id='e89f55e9-e2d2-4fc5-8913-afdee59d83e8';
UPDATE hotels SET description='Homewood Suites by Hilton Ankeny is a 92-suite extended-stay hotel at 2455 SE Creekview Dr, on the north side of the Des Moines metro a few minutes from I-35 and I-80. Kinseth Hospitality developed it and held the grand opening in June 2015. Each suite has a fully equipped kitchen. The developer''s plans listed a free full hot breakfast, a complimentary dinner with wine and beer Monday through Thursday, laundry, on-site meeting space, a 24-hour convenience store and an outdoor grill and patio.', short_description='92-suite extended-stay Homewood off I-35 in Ankeny, with full kitchens in every suite and free hot breakfast.', seo_title='Homewood Suites by Hilton Ankeny | Hotels in Ankeny, IA', seo_description='Homewood Suites by Hilton Ankeny has 92 suites with full kitchens on SE Creekview Dr, minutes from I-35 and I-80, with free hot breakfast.', seo_h1='Homewood Suites by Hilton Ankeny', geo_summary='Homewood Suites by Hilton Ankeny is a 92-suite extended-stay hotel on SE Creekview Drive, minutes from I-35 and I-80. It suits work trips and longer stays where a full kitchen matters.', geo_key_facts=ARRAY['92 suites at 2455 SE Creekview Dr, Ankeny','All-suite extended stay, grand opening June 2015','Developed by Kinseth Hospitality','Fully equipped kitchen in every suite','Minutes from I-35 and I-80']::text[], geo_faq='[{"question":"Do suites at Homewood Suites Ankeny have kitchens?","answer":"Yes. Suites come with a fully equipped kitchen."},{"question":"Is breakfast included?","answer":"The developer''s announcement lists a free full hot breakfast."},{"question":"How many suites does the hotel have?","answer":"92 suites, per the 2015 opening announcement."}]'::jsonb, updated_at=now() WHERE id='6f741018-3118-4958-aea4-342490a0343e';
UPDATE hotels SET description='Homewood Suites by Hilton Des Moines Airport is an all-suite hotel at 7201 SW 22nd St, about a mile from Des Moines International Airport by the hotel''s own directions. Every suite has a fully equipped kitchen. The hotel runs a complimentary airport shuttle and serves a free hot breakfast, and it has an indoor pool, fitness center, business center and meeting rooms. Parking is free, but there is no room for semis, trailers or other large vehicles. Up to two dogs or cats are allowed for a fee. Check-in 3:00 PM, check-out 11:00 AM.', short_description='All-suite Homewood about a mile from Des Moines International Airport, with full kitchens, a free shuttle and hot breakfast.', seo_title='Homewood Suites Des Moines Airport | Hotels in Des Moines', seo_description='Homewood Suites Des Moines Airport is about a mile from DSM, with full-kitchen suites, a free airport shuttle, free hot breakfast and an indoor pool.', seo_h1='Homewood Suites by Hilton Des Moines Airport', geo_summary='Homewood Suites by Hilton Des Moines Airport is an all-suite extended-stay hotel about a mile from Des Moines International Airport. It suits early flights, layovers and longer stays that need a kitchen.', geo_key_facts=ARRAY['All-suite hotel at 7201 SW 22nd St, Des Moines','About a mile from Des Moines International Airport','Complimentary airport shuttle','Fully equipped kitchens in suites','Free hot breakfast and free parking','No parking for semis, trailers or large vehicles']::text[], geo_faq='[{"question":"Does Homewood Suites Des Moines Airport have an airport shuttle?","answer":"Yes, a complimentary airport shuttle. The hotel is about a mile from the airport."},{"question":"Can I park a trailer or large truck there?","answer":"No. The hotel has no parking for large vehicles, semis or trailers."},{"question":"Are pets allowed?","answer":"Yes, up to two dogs or cats. The non-refundable fee is $75 for 1-4 nights and $125 for 5 or more nights."}]'::jsonb, updated_at=now() WHERE id='e3378ecb-4c6b-4c25-9f04-47daacf03d91';
UPDATE hotels SET description='Homewood Suites by Hilton Urbandale is a four-story, 107-suite hotel at 8901 Plum Dr in Urbandale. It is all suites, and every one has a fully equipped kitchen. Choose between studios and one-bedroom suites; the one-bedrooms add a washer and dryer, which helps on stays of a week or more. Breakfast is free, and there is an indoor pool and a fitness center. Pets are accepted for an extra fee. The minimum check-in age is 21. Check-in is 3:00 PM and check-out 11:00 AM.', short_description='107-suite Homewood in Urbandale with full kitchens, washer/dryer in one-bedroom suites, free breakfast and an indoor pool.', seo_title='Homewood Suites Urbandale | Hotels in Urbandale, IA', seo_description='Homewood Suites by Hilton Urbandale has 107 suites with full kitchens on Plum Dr, plus free breakfast, an indoor pool and washer/dryer in 1-bedrooms.', seo_h1='Homewood Suites by Hilton Urbandale', geo_summary='Homewood Suites by Hilton Urbandale is a 107-suite extended-stay hotel on Plum Drive in Urbandale, Iowa. It suits week-plus stays, with full kitchens in every suite and in-suite laundry in the one-bedrooms.', geo_key_facts=ARRAY['107 suites over four stories at 8901 Plum Dr, Urbandale','Fully equipped kitchen in every suite','One-bedroom suites include washer/dryer','Free breakfast, indoor pool, fitness center','Minimum check-in age 21','Check-in 3:00 PM, check-out 11:00 AM']::text[], geo_faq='[{"question":"Do suites at Homewood Suites Urbandale have a washer and dryer?","answer":"The one-bedroom suites do."},{"question":"What is the minimum age to check in?","answer":"21."},{"question":"Does the hotel allow pets?","answer":"Yes, pets are accepted for an additional fee, according to AAA."}]'::jsonb, updated_at=now() WHERE id='eab1f133-1c1a-42a4-8030-28c2f28e38e1';
UPDATE hotels SET description='Homewood Suites by Hilton West Des Moines is a 100-suite extended-stay hotel at 6220 Stagecoach Drive, about half a mile from Jordan Creek Town Center according to Hilton. Every suite has a full kitchen. A free hot breakfast, free Wi-Fi, an indoor pool, a fitness center and free self-parking are included. The hotel opened in August 2015 and is run by Kinseth Hospitality; its opening release described an evening social reception Monday through Thursday. Pets are welcome up to 100 lb. Check-in is 3:00 PM and check-out is noon.', short_description='100-suite Homewood about half a mile from Jordan Creek Town Center, with full kitchens, free hot breakfast and free parking.', seo_title='Homewood Suites West Des Moines | Hotels in WDM, IA', seo_description='Homewood Suites West Des Moines is about half a mile from Jordan Creek Town Center, with 100 full-kitchen suites, free hot breakfast and an indoor pool.', seo_h1='Homewood Suites by Hilton West Des Moines', geo_summary='Homewood Suites by Hilton West Des Moines is a 100-suite extended-stay hotel about half a mile from Jordan Creek Town Center. It suits shoppers, families and longer work stays that want a full kitchen and a noon check-out.', geo_key_facts=ARRAY['100 suites at 6220 Stagecoach Drive, West Des Moines','About half a mile from Jordan Creek Town Center, per Hilton','Full kitchen in every suite','Free hot breakfast and free self-parking','Opened August 27, 2015; managed by Kinseth Hospitality','Check-in 3:00 PM, check-out noon']::text[], geo_faq='[{"question":"How far is Homewood Suites West Des Moines from Jordan Creek Town Center?","answer":"About half a mile, according to Hilton."},{"question":"Is the hotel pet friendly?","answer":"Yes. Pets up to 100 lb are allowed for a $75 non-refundable fee."},{"question":"What time is check-out?","answer":"Check-out is at 12:00 PM; check-in is at 3:00 PM."}]'::jsonb, updated_at=now() WHERE id='2689c422-2143-43bc-8dcd-6a293c9d1213';
UPDATE hotels SET description='Hotel Fort Des Moines is a 287-room historic hotel at 1000 Walnut St in downtown Des Moines. It opened in 1919, was designed by local firm Proudfoot, Bird & Rawson, and was listed on the National Register of Historic Places in 1982. After closing in November 2015 for a major renovation, it reopened in Hilton''s Curio Collection. Dining is in-house: Proudfoot & Bird, the Hobnob cafe and wine bar, and the In Confidence bar. The 1919 Grand Ballroom seats up to 500. Parking is valet ($42), and pets are not allowed.', short_description='Historic 1919 downtown hotel on Walnut St, 287 rooms, with Proudfoot & Bird, Hobnob and In Confidence on site.', seo_title='Hotel Fort Des Moines | Hotels in Downtown Des Moines', seo_description='Hotel Fort Des Moines is a 287-room 1919 hotel on Walnut St downtown, on the National Register, with Proudfoot & Bird and a 500-seat ballroom.', seo_h1='Hotel Fort Des Moines, Curio Collection by Hilton', geo_summary='Hotel Fort Des Moines is a 287-room downtown hotel that opened in 1919 and is listed on the National Register of Historic Places, now part of Hilton''s Curio Collection. It suits visitors who want a historic building with restaurants and bars on site, and event planners needing a 500-seat ballroom.', geo_key_facts=ARRAY['287 rooms at 1000 Walnut St, downtown Des Moines','Opened 1919; National Register of Historic Places (1982)','Designed by Proudfoot, Bird & Rawson','Proudfoot & Bird, Hobnob and In Confidence on site','1919 Grand Ballroom seats 500; 7,000 sq ft of meeting space','Valet parking $42; pets not allowed']::text[], geo_faq='[{"question":"Does Hotel Fort Des Moines have parking?","answer":"Valet parking is available for $42."},{"question":"Are pets allowed at Hotel Fort Des Moines?","answer":"No, pets are not allowed."},{"question":"What time is check-in?","answer":"Check-in is at 4:00 PM and check-out is at 11:00 AM."}]'::jsonb, updated_at=now() WHERE id='44a0c468-f544-41a0-8ea9-33405374965c';
UPDATE hotels SET description='Hotel Renovo is a two-story, 102-room boutique hotel at 11167 Hickman Rd in Urbandale, part of Hilton''s Tapestry Collection. The lobby has a fireplace and a bar and bistro, and the hotel also has an indoor pool, a fitness center, breakfast and dry cleaning. A free airport shuttle runs with 24 hours'' notice. Don''t mix it up with the Revel Hotel, a separate Tapestry property next door at 11211 Hickman Rd. Check-in is 4:00 PM and check-out is noon.', short_description='102-room Tapestry Collection hotel on Hickman Rd in Urbandale, with a lobby bar and bistro, indoor pool and airport shuttle.', seo_title='Hotel Renovo Urbandale | Hotels in Urbandale, IA', seo_description='Hotel Renovo is a 102-room Tapestry Collection hotel on Hickman Rd in Urbandale, with a lobby bar and bistro, indoor pool and airport shuttle on request.', seo_h1='Hotel Renovo, Tapestry Collection by Hilton, Urbandale', geo_summary='Hotel Renovo is a 102-room, two-story boutique hotel in Hilton''s Tapestry Collection on Hickman Road in Urbandale, Iowa. It suits travelers who want a bar and bistro in the lobby and a free airport shuttle booked a day ahead.', geo_key_facts=ARRAY['102 rooms, two stories, at 11167 Hickman Rd, Urbandale','Part of Hilton''s Tapestry Collection','Lobby bar and bistro with fireplace','Indoor pool and fitness center','Free airport shuttle with 24-hour notice','Separate from the Revel Hotel next door at 11211 Hickman Rd']::text[], geo_faq='[{"question":"Does Hotel Renovo have an airport shuttle?","answer":"Yes. It is free with 24 hours'' notice, per Priceline."},{"question":"Is Hotel Renovo the same as the Revel Hotel?","answer":"No. The Revel Hotel is a separate Tapestry property next door at 11211 Hickman Rd."},{"question":"What are check-in and check-out times?","answer":"Check-in is at 4:00 PM and check-out is at 12:00 PM."}]'::jsonb, updated_at=now() WHERE id='785d8e1d-47d2-4a35-9666-49c0f3f16b5c';
UPDATE hotels SET description='Hyatt Place Altoona Des Moines is a 112-room hotel at 480 Bass Pro Drive NW in Altoona, which Hyatt puts eight miles from Des Moines and 0.95 miles from Adventureland. Every room has a Cozy Corner with a sleeper sofa. Breakfast and parking are free, and The Market sells grab-and-go food. The heated indoor pool is open 6 a.m. to 10 p.m. and is five feet at its deepest. Up to two dogs are allowed for a fee. There is 1,188 sq ft of event space. Check-in 3:00 PM, check-out noon.', short_description='112-room Hyatt Place in Altoona, 0.95 miles from Adventureland, with free breakfast, an indoor pool and sleeper sofas in every room.', seo_title='Hyatt Place Altoona Des Moines | Hotels in Altoona, IA', seo_description='Hyatt Place Altoona is 0.95 miles from Adventureland, with 112 rooms that each have a sleeper sofa, free breakfast, free parking and an indoor pool.', seo_h1='Hyatt Place Altoona Des Moines', geo_summary='Hyatt Place Altoona Des Moines is a 112-room hotel on Bass Pro Drive in Altoona, 0.95 miles from Adventureland. It suits families, with a sleeper sofa in every room, free breakfast and a pool that tops out at five feet.', geo_key_facts=ARRAY['112 rooms at 480 Bass Pro Drive NW, Altoona','0.95 miles from Adventureland; eight miles from Des Moines','Sleeper sofa in every room','Free breakfast and free parking','Heated indoor pool, 6 a.m.-10 p.m., max depth five feet','Up to two dogs allowed for a fee']::text[], geo_faq='[{"question":"How far is Hyatt Place Altoona from Adventureland?","answer":"0.95 miles, according to Hyatt."},{"question":"Is Hyatt Place Altoona dog friendly?","answer":"Yes, up to two dogs: $75 per stay for 1-6 nights or $100 for 7-30 nights, 50 lb per dog and 75 lb combined."},{"question":"When is the pool open?","answer":"The heated indoor pool is open 6 a.m. to 10 p.m. and is five feet at its deepest."}]'::jsonb, updated_at=now() WHERE id='d9ea24ee-7be2-4618-8f2b-a03a0d6b00f7';
UPDATE hotels SET description='Hyatt Place Des Moines Downtown is a 93-room hotel at 418 6th Ave, on the upper floors of the historic Liberty Building. From the second floor you can step onto the downtown skywalk, about four miles of climate-controlled walkways. The Historic Court District and the Des Moines Civic Center are within walking distance. Breakfast is free, the Starbucks espresso bar and fitness center are open 24/7, and there is an indoor pool. Self-parking costs extra, and only dogs are allowed. Check-in 3:00 PM, check-out noon.', short_description='93-room Hyatt Place in the Liberty Building downtown, with skywalk access, free breakfast and a walk to the Civic Center.', seo_title='Hyatt Place Des Moines Downtown | Hotels in Des Moines', seo_description='Hyatt Place Des Moines Downtown fills the upper floors of the Liberty Building, with skywalk access, free breakfast and an indoor pool near the Civic Center.', seo_h1='Hyatt Place Des Moines Downtown', geo_summary='Hyatt Place Des Moines Downtown is a 93-room hotel on the upper floors of the historic Liberty Building at 418 6th Ave. It suits visitors to the Civic Center and the Historic Court District who want skywalk access and free breakfast.', geo_key_facts=ARRAY['93 rooms at 418 6th Ave, in the historic Liberty Building','Second-floor access to downtown''s 4-mile skywalk','Walking distance to the Civic Center and Historic Court District','Free breakfast; 24/7 Starbucks espresso bar','Indoor pool and 24/7 fitness center','Self-parking for a fee; dogs only']::text[], geo_faq='[{"question":"Is Hyatt Place Des Moines Downtown connected to the skywalk?","answer":"Yes, from the hotel''s second floor."},{"question":"Is parking free?","answer":"No, self-parking is available for a fee."},{"question":"Are pets allowed?","answer":"Dogs only."}]'::jsonb, updated_at=now() WHERE id='ea4f93d8-3da5-4fb0-8141-c999239121ee';
UPDATE hotels SET description='Hyatt Place West Des Moines Jordan Creek is a four-story, 123-room hotel at 295 S 64th St in West Des Moines, built in 2016. Breakfast is free every day at The Breakfast Bar, and self-parking is free too. There is an indoor pool and a fitness center. The hotel takes pets: up to two, 50 lb each and 75 lb combined, with a per-stay fee plus a cleaning fee. Check-in is at 4:00 PM and check-out is at noon, so plan an afternoon around a late arrival.', short_description='123-room Hyatt Place on S 64th St in West Des Moines, built 2016, with free breakfast, free parking and an indoor pool.', seo_title='Hyatt Place WDM Jordan Creek | Hotels in West Des Moines', seo_description='Hyatt Place West Des Moines Jordan Creek has 123 rooms on S 64th St, with free breakfast at The Breakfast Bar, free self-parking and an indoor pool.', seo_h1='Hyatt Place West Des Moines Jordan Creek', geo_summary='Hyatt Place West Des Moines Jordan Creek is a 123-room, four-story hotel built in 2016 on S 64th Street in West Des Moines. It suits travelers who want free breakfast, free parking and room for a dog or two.', geo_key_facts=ARRAY['123 rooms at 295 S 64th St, West Des Moines','Four stories, built in 2016','Free breakfast daily at The Breakfast Bar','Indoor pool, fitness center, free self-parking','Pet friendly: max two pets, 75 lb combined','Check-in 4:00 PM, check-out noon']::text[], geo_faq='[{"question":"Does Hyatt Place West Des Moines Jordan Creek have free breakfast?","answer":"Yes, served daily at The Breakfast Bar."},{"question":"Is the hotel pet friendly?","answer":"Yes. Up to two pets, 50 lb each and 75 lb combined, for $100 per stay (1-6 nights) or $200 (7-30 nights) plus a cleaning fee."},{"question":"What time is check-in?","answer":"Check-in is at 4:00 PM and check-out is at 12:00 PM."}]'::jsonb, updated_at=now() WHERE id='92a38823-dc74-493c-82d8-4a4e415c0abc';
UPDATE hotels SET description='Embassy Suites by Hilton Des Moines Downtown is an all-suite hotel at 101 East Locust Street, on the riverfront between 1st and 2nd Streets near the Historic East Village. Its 234 rooms are two-room suites, and a stay includes a free made-to-order breakfast and a complimentary evening reception. There''s an indoor pool, a fitness center and an on-site restaurant, Liberty''s - An Iowa Grill. The skylit atrium doubles as event space. Check-in is 4 PM and check-out is noon. Dogs and cats are allowed, two per room, for a non-refundable fee.', short_description='All-suite riverfront hotel on East Locust Street with free made-to-order breakfast, an evening reception and an indoor pool.', seo_title='Embassy Suites Des Moines Downtown | Downtown Hotels', seo_description='Embassy Suites Des Moines Downtown: 234 two-room suites on the riverfront near the East Village, with free made-to-order breakfast and an indoor pool.', seo_h1='Embassy Suites by Hilton Des Moines Downtown', geo_summary='Embassy Suites by Hilton Des Moines Downtown is a 234-suite hotel on the Des Moines riverfront at 101 East Locust Street, near the Historic East Village. It suits travelers who want a separate living area, a cooked breakfast included and a walkable downtown base.', geo_key_facts=ARRAY['234 two-room suites','101 East Locust Street, on the riverfront between 1st and 2nd Streets near the Historic East Village','Free made-to-order breakfast and complimentary evening reception','Indoor pool, fitness center, on-site restaurant Liberty''s - An Iowa Grill','Check-in 4 PM, check-out 12 PM']::text[], geo_faq='[{"question":"Is breakfast included at Embassy Suites Des Moines Downtown?","answer":"Yes. The hotel lists a free made-to-order breakfast, plus a complimentary evening reception."},{"question":"Does Embassy Suites Des Moines Downtown allow pets?","answer":"Yes, dogs or cats only, up to two pets. Hilton lists a non-refundable fee of $75 for 1-4 nights and $125 for 5 or more nights."},{"question":"What are check-in and check-out times?","answer":"Check-in is 4:00 PM and check-out is 12:00 PM."}]'::jsonb, updated_at=now() WHERE id='853a807f-3834-406d-8a34-6e4328c4e380';
UPDATE hotels SET description='Extended Stay America in Urbandale sits at 3940 114th Street on the west side of the metro, and booking sites now list it as an Extended Stay America Select Suites property. It''s built for longer stays: listings describe studio rooms with a kitchen that includes a full-size refrigerator, a stovetop and a microwave. Guests get a free grab-and-go breakfast, free WiFi, on-site laundry and free self parking, and all rooms are non-smoking. Pets are accepted for a nightly fee. The hotels.com listing puts Des Moines International Airport about a 20-minute drive away.', short_description='Extended-stay hotel on 114th Street in Urbandale with in-room kitchens, free parking, laundry and a grab-and-go breakfast.', seo_title='Extended Stay America Urbandale | Hotels in Urbandale, IA', seo_description='Extended Stay America in Urbandale, IA: studio rooms with kitchens, free parking, on-site laundry and grab-and-go breakfast at 3940 114th Street.', seo_h1='Extended Stay America - Des Moines - Urbandale', geo_summary='Extended Stay America - Des Moines - Urbandale is an extended-stay hotel at 3940 114th Street in Urbandale with kitchens in every room. It''s aimed at relocations, project work and other stays measured in weeks rather than nights.', geo_key_facts=ARRAY['3940 114th Street, Urbandale','Rooms have kitchens with full-size refrigerator, stovetop and microwave (listings)','Free grab-and-go breakfast, free WiFi, free self parking','On-site guest laundry; all rooms non-smoking','Pets accepted for a fee']::text[], geo_faq='[{"question":"Do rooms have kitchens?","answer":"Yes. Listings describe each room with a kitchen including a full-size refrigerator/freezer, a stovetop and a microwave."},{"question":"Is parking free?","answer":"Listings show free on-site self parking."},{"question":"How far is it from the Des Moines airport?","answer":"The hotels.com listing puts Des Moines International Airport about a 20-minute drive away."}]'::jsonb, updated_at=now() WHERE id='098480a4-0091-4d28-af4d-c9ebedb88d3b';
UPDATE hotels SET description='Extended Stay America Select Suites - Des Moines - West Des Moines is an 86-room, three-floor extended-stay hotel at 2701 Westown Parkway, close to Valley West Mall and near Exit 124 on I-80. Rooms have kitchenettes with a refrigerator and coffee maker, and listings show studios that sleep up to six with a sofa bed. There''s free parking, guest laundry and a breakfast, and pets are allowed. Booking listings give check-in after 3 PM and check-out before 11 AM, which suits a stay of a week or longer for work or a move.', short_description='86-room extended-stay hotel on Westown Parkway near Valley West Mall and I-80, with kitchenettes, laundry and free parking.', seo_title='Extended Stay America West Des Moines | WDM Hotels', seo_description='Extended Stay America Select Suites in West Des Moines: 86 rooms with kitchenettes on Westown Parkway near Valley West Mall and I-80, with laundry and parking.', seo_h1='Extended Stay America Select Suites - Des Moines - West Des Moines', geo_summary='Extended Stay America Select Suites - Des Moines - West Des Moines is an 86-room extended-stay hotel at 2701 Westown Parkway near Valley West Mall. It''s built for travelers staying a week or more who want a kitchenette and laundry on site.', geo_key_facts=ARRAY['86 rooms on 3 floors, interior hallways','2701 Westown Parkway, near Valley West Mall and I-80 Exit 124','Kitchenettes with refrigerator and coffee maker','Guest laundry and free parking','Pets allowed']::text[], geo_faq='[{"question":"Is it close to an interstate?","answer":"HotelPlanner lists it near Exit 124 on I-80."},{"question":"Are pets allowed?","answer":"Yes, the HotelPlanner listing says pets are allowed. Confirm any fee with the hotel."},{"question":"What are check-in and check-out times?","answer":"Booking listings give check-in after 3:00 PM and check-out before 11:00 AM."}]'::jsonb, updated_at=now() WHERE id='b259573b-b071-4091-87af-d96464a5c077';
UPDATE hotels SET description='Fairfield Inn & Suites Altoona Des Moines is at 460 Bass Pro Drive NW in Altoona, east of Des Moines, and Marriott names Adventureland Park, the Bass Pro Shop and the Outlets of Des Moines as nearby. Breakfast is free, served 6-9 AM on weekdays and 7-10 AM on weekends. There''s an indoor pool and whirlpool, a fitness center, a business center and on-site laundry, and parking and high-speed internet are free. Check-in is 3 PM, check-out noon. Pets are welcome for a $50 cleaning fee per stay; cats are not.', short_description='Altoona hotel on Bass Pro Drive near Adventureland and the Outlets of Des Moines, with free breakfast, parking and an indoor pool.', seo_title='Fairfield Inn & Suites Altoona | Hotels in Altoona, IA', seo_description='Fairfield Inn & Suites Altoona Des Moines: near Adventureland and the Outlets of Des Moines, with free breakfast, free parking and an indoor pool.', seo_h1='Fairfield Inn & Suites Altoona Des Moines', geo_summary='Fairfield Inn & Suites Altoona Des Moines is a Marriott hotel at 460 Bass Pro Drive NW in Altoona. It suits families headed to Adventureland Park and shoppers at the Outlets of Des Moines who want free breakfast and parking.', geo_key_facts=ARRAY['460 Bass Pro Drive NW, Altoona','Near Adventureland Park, Bass Pro Shop and the Outlets of Des Moines (per Marriott)','About 20.5 miles from Des Moines International Airport (per Marriott)','Free breakfast, free parking, indoor pool and whirlpool','Check-in 3 PM, check-out 12 PM']::text[], geo_faq='[{"question":"What time is breakfast?","answer":"Free breakfast runs 6-9 AM on weekdays and 7-10 AM on weekends."},{"question":"Are pets allowed?","answer":"Pets are welcome with a $50 deep cleaning fee per stay. Cats are not permitted."},{"question":"How far is it from Des Moines International Airport?","answer":"Marriott puts it about 20.5 miles from the airport."}]'::jsonb, updated_at=now() WHERE id='283bc887-c3c1-4bb7-b57e-ec6c98467868';
UPDATE hotels SET description='Fairfield Inn & Suites Des Moines Airport is at 6880 Fleur Drive, just south of Des Moines International Airport, and runs a complimentary airport shuttle, which makes it a practical stop before an early flight or after a late arrival. The hotel has an indoor pool and hot tub, breakfast, free parking and free Wi-Fi. Check-in is 3 PM and check-out is noon. Pets aren''t allowed; service animals are. An older Marriott listing gave shuttle hours of 4 AM to midnight daily, so confirm the current schedule when you book.', short_description='Hotel on Fleur Drive just south of Des Moines International Airport with a free airport shuttle, indoor pool and free parking.', seo_title='Fairfield Inn & Suites Des Moines Airport | DSM Hotels', seo_description='Fairfield Inn & Suites Des Moines Airport on Fleur Drive: free airport shuttle, indoor pool, hot tub, breakfast and free parking near DSM.', seo_h1='Fairfield Inn & Suites Des Moines Airport', geo_summary='Fairfield Inn & Suites Des Moines Airport is a Marriott hotel at 6880 Fleur Drive, just south of Des Moines International Airport. It''s for travelers with early or late flights who want a free shuttle and free parking.', geo_key_facts=ARRAY['6880 Fleur Drive, just south of Des Moines International Airport','Complimentary airport shuttle','Indoor pool and hot tub','Breakfast, free parking and free Wi-Fi','No pets; service animals only']::text[], geo_faq='[{"question":"Does the hotel have an airport shuttle?","answer":"Yes, a complimentary airport shuttle. An older Marriott listing gave hours of 4 AM to midnight daily; confirm current hours with the hotel."},{"question":"Are pets allowed?","answer":"No. Service animals only."},{"question":"What are check-in and check-out times?","answer":"Check-in is 3:00 PM and check-out is 12:00 PM."}]'::jsonb, updated_at=now() WHERE id='fcc9b5a9-0e8b-48ce-821d-e9275ad23981';
UPDATE hotels SET description='Fairfield Inn & Suites Des Moines Downtown is at 207 Crocker Street, steps from the Iowa Events Center and about a five-minute walk from Casey''s Center, so it works well for a convention or an arena show. Booking listings describe a three-floor, 91-room hotel built in 2019, with room types from king rooms to suites with sofa beds. Breakfast is free, and there are 24-hour fitness facilities, a business center and guest laundry. Suiteness puts Drake University about 1.8 miles away and the Iowa State Fairgrounds about 4.8 miles.', short_description='Downtown hotel on Crocker Street steps from the Iowa Events Center and Casey''s Center, with free breakfast and a 24-hour gym.', seo_title='Fairfield Inn & Suites Des Moines Downtown | DSM Hotels', seo_description='Fairfield Inn & Suites Des Moines Downtown at 207 Crocker Street: steps from the Iowa Events Center and Casey''s Center, with free breakfast and a 24-hour gym.', seo_h1='Fairfield Inn & Suites Des Moines Downtown', geo_summary='Fairfield Inn & Suites Des Moines Downtown is a Marriott hotel at 207 Crocker Street, steps from the Iowa Events Center. It suits convention-goers and fans heading to Casey''s Center who want to walk to the venue.', geo_key_facts=ARRAY['207 Crocker Street, downtown Des Moines','Steps from the Iowa Events Center; Casey''s Center about 5 minutes on foot (Suiteness)','About 91 rooms on 3 floors, built 2019 (meeting-directory listing)','Free breakfast and 24-hour fitness facilities','Drake University about 1.8 mi, Iowa State Fairgrounds about 4.8 mi (Suiteness)']::text[], geo_faq='[{"question":"How close is it to Casey''s Center?","answer":"Suiteness lists Casey''s Center as about 5 minutes on foot, and the hotel as steps from the Iowa Events Center."},{"question":"Is breakfast included?","answer":"Yes, listings include free breakfast."},{"question":"How far is it from the Iowa State Fairgrounds?","answer":"Suiteness puts the fairgrounds about 4.8 miles away."}]'::jsonb, updated_at=now() WHERE id='3efb99c5-765d-45f8-aca9-d16204956072';
UPDATE hotels SET description='Fairfield Inn & Suites Des Moines Urbandale is an 89-room Marriott hotel at 8661 Plum Drive in Urbandale that opened in April 2014. A free hot breakfast is included, and there''s an indoor pool with a whirlpool spa, an exercise room and free Wi-Fi. A 2,000-square-foot meeting room holds up to 150 people. At opening it was billed as 18 miles from Des Moines International Airport and 10 minutes from downtown Des Moines. Listings show free on-site parking, check-in at 3 PM and check-out at noon, and no pets other than service animals.', short_description='89-room Urbandale hotel on Plum Drive with free hot breakfast, an indoor pool and whirlpool, and a 150-person meeting room.', seo_title='Fairfield Inn & Suites Urbandale | Hotels in Urbandale, IA', seo_description='Fairfield Inn & Suites Des Moines Urbandale: 89 rooms on Plum Drive with free hot breakfast, an indoor pool and whirlpool, and a 2,000 sq ft meeting room.', seo_h1='Fairfield Inn & Suites Des Moines Urbandale', geo_summary='Fairfield Inn & Suites Des Moines Urbandale is an 89-room Marriott hotel at 8661 Plum Drive, opened in 2014. It works for business travelers and families on the northwest side of the metro who want free hot breakfast and a pool.', geo_key_facts=ARRAY['89 rooms, opened April 2014','8661 Plum Drive, Urbandale','Free hot breakfast; indoor pool with whirlpool spa; exercise room','2,000 sq ft meeting room for up to 150','18 miles from Des Moines International Airport, 10 minutes from downtown (2014 opening announcement)']::text[], geo_faq='[{"question":"Does the hotel have a pool?","answer":"Yes, an indoor pool with a whirlpool spa."},{"question":"Are pets allowed?","answer":"Listings say no pets, apart from service animals."},{"question":"How far is it from downtown Des Moines?","answer":"The 2014 opening announcement put it about 10 minutes from downtown and 18 miles from Des Moines International Airport."}]'::jsonb, updated_at=now() WHERE id='a74b5127-0066-43e9-93aa-9408f828e214';
UPDATE hotels SET description='Fairfield Inn & Suites Des Moines West is a 102-room Marriott hotel at 7225 Vista Drive in West Des Moines, one block south of I-80 at exit 121 and about 12 miles from Des Moines International Airport. Breakfast is hot and free, parking and high-speed internet are free, and there''s an indoor pool, a fitness center, a convenience store and guest laundry. Some suites have gas fireplaces and whirlpools. Two event rooms are available; the largest, the Jordan Creek room, holds 40. Pets are allowed, up to two at 50 lbs each, for a nightly fee.', short_description='102-room hotel off I-80 exit 121 in West Des Moines with free hot breakfast, an indoor pool and suites with fireplaces.', seo_title='Fairfield Inn & Suites Des Moines West | WDM Hotels', seo_description='Fairfield Inn & Suites Des Moines West: 102 rooms one block south of I-80 exit 121, with free hot breakfast, free parking, an indoor pool and pet rooms.', seo_h1='Fairfield Inn & Suites Des Moines West, West Des Moines', geo_summary='Fairfield Inn & Suites Des Moines West is a 102-room Marriott hotel at 7225 Vista Drive in West Des Moines, one block south of I-80 at exit 121. It suits drivers on I-80 and families who want free hot breakfast, a pool and pet-friendly rooms.', geo_key_facts=ARRAY['102 rooms; built 2002, renovated 2013 (OTA listing)','7225 Vista Drive, one block south of I-80 at exit 121','About 12 miles from Des Moines International Airport (Marriott)','Free hot breakfast, free parking, indoor pool','Some suites with gas fireplaces and whirlpools']::text[], geo_faq='[{"question":"Is it easy to reach from I-80?","answer":"Yes. The hotel is one block south of I-80 at exit 121."},{"question":"Are pets allowed?","answer":"Yes, up to two pets of up to 50 lbs each, for $50 per night per Marriott pages."},{"question":"How far is the airport?","answer":"Marriott puts Des Moines International Airport about 12 miles away."}]'::jsonb, updated_at=now() WHERE id='5aeca0c3-9585-41da-9423-1696b2351123';
UPDATE hotels SET description='Hampton Inn & Suites Altoona Des Moines is a 90-room hotel at 215 Adventureland Drive NW, just off I-80 in Altoona. The hotel says Prairie Meadows Casino and Racetrack is three minutes away, and the Outlets of Des Moines are about three miles off. Hot breakfast and parking are free, and there''s an indoor pool, a fitness center, a business center and a 720-square-foot meeting room. Connecting rooms, cribs and Digital Key are available. Dogs and cats are allowed, two per room up to 75 lbs, for a fee. Check-in is 3 PM, check-out 11 AM.', short_description='90-room Altoona hotel off I-80, three minutes from Prairie Meadows, with free hot breakfast, free parking and an indoor pool.', seo_title='Hampton Inn & Suites Altoona | Hotels in Altoona, IA', seo_description='Hampton Inn & Suites Altoona Des Moines: 90 rooms off I-80, three minutes from Prairie Meadows, with free hot breakfast, free parking and an indoor pool.', seo_h1='Hampton Inn & Suites Altoona Des Moines', geo_summary='Hampton Inn & Suites Altoona Des Moines is a 90-room Hilton hotel at 215 Adventureland Drive NW, just off I-80. It suits visitors to Prairie Meadows and the Outlets of Des Moines, and families who want free breakfast and a pool.', geo_key_facts=ARRAY['90 rooms at 215 Adventureland Drive NW, Altoona','Just off I-80; Prairie Meadows Casino and Racetrack three minutes away (per hotel)','Outlets of Des Moines about three miles away','Free hot breakfast, free parking, indoor pool','Check-in 3 PM, check-out 11 AM']::text[], geo_faq='[{"question":"How close is it to Prairie Meadows?","answer":"The hotel says Prairie Meadows Casino and Racetrack is three minutes away."},{"question":"Is the hotel pet friendly?","answer":"Yes, dogs or cats only, up to two pets, 75 lbs max each, with a non-refundable fee of $75 for 1-4 nights or $125 for 5+ nights plus taxes."},{"question":"Is parking free?","answer":"Yes, parking is free, and so is the daily hot breakfast."}]'::jsonb, updated_at=now() WHERE id='3d91e8a1-832a-4b0d-b6d1-b11ec7cdb740';
UPDATE hotels SET description='Hampton Inn & Suites Ames is a 90-room hotel at 2100 SE 16th Street, at the interchange of I-35 and US Highway 30. Hilton puts it about three miles from Iowa State University, with Jack Trice Stadium, Hilton Coliseum and Reiman Gardens about two to three miles away, which makes it a handy base for game days and campus visits. Hot breakfast, Wi-Fi and parking are free, and there''s an indoor pool, a fitness center, a business center and meeting rooms. Check-in is 3 PM and check-out 11 AM. Up to two dogs or cats are allowed for a fee.', short_description='90-room Ames hotel at I-35 and US 30, about three miles from Iowa State, with free hot breakfast, parking and an indoor pool.', seo_title='Hampton Inn & Suites Ames | Hotels in Ames, IA', seo_description='Hampton Inn & Suites Ames at I-35 and US 30: about three miles from Iowa State and Jack Trice Stadium, with free hot breakfast, parking and an indoor pool.', seo_h1='Hampton Inn & Suites Ames', geo_summary='Hampton Inn & Suites Ames is a 90-room Hilton hotel at the I-35 and US Highway 30 interchange, about three miles from Iowa State University. It''s for game-day visitors, campus visits and drivers on I-35 who want free breakfast and parking.', geo_key_facts=ARRAY['90 rooms; built 2016 (OTA listing)','2100 SE 16th Street, at the I-35 and US 30 interchange','About 3 miles from Iowa State University (Hilton)','Jack Trice Stadium, Hilton Coliseum and Reiman Gardens about 2-3 miles away','Free hot breakfast, free parking, indoor pool']::text[], geo_faq='[{"question":"How far is the hotel from Jack Trice Stadium?","answer":"Hilton lists Jack Trice Stadium, Hilton Coliseum and Reiman Gardens about 2-3 miles away."},{"question":"Are pets allowed?","answer":"Up to two dogs or cats, with a non-refundable fee of $75 for 1-4 nights or $125 for 5+ nights."},{"question":"What are check-in and check-out times?","answer":"Check-in is 3:00 PM and check-out is 11:00 AM."}]'::jsonb, updated_at=now() WHERE id='84870c80-5462-4be7-87fa-27f5c8048f49';
UPDATE hotels SET description='Hampton Inn & Suites Ankeny is a three-floor, 77-room hotel at 6210 SE Convenience Boulevard, just off I-35 at Exit 89. It opened in 2008, sits less than three miles from Ankeny Regional Airport and is about 15 minutes from the Iowa State Capitol, so a north-side stay still leaves a quick run into Des Moines. Hot breakfast, Wi-Fi and parking are free, and there''s an indoor pool, a fitness center and a business center. Rooms are non-smoking. Check-in is 3 PM, check-out 11 AM, and up to two dogs or cats are allowed for a fee.', short_description='77-room Ankeny hotel off I-35 Exit 89 with free hot breakfast, free parking and an indoor pool, 15 minutes from the Capitol.', seo_title='Hampton Inn & Suites Ankeny | Hotels in Ankeny, IA', seo_description='Hampton Inn & Suites Ankeny: 77 rooms off I-35 Exit 89, about 15 minutes from the Iowa State Capitol, with free hot breakfast, parking and an indoor pool.', seo_h1='Hampton Inn & Suites Ankeny', geo_summary='Hampton Inn & Suites Ankeny is a 77-room Hilton hotel at 6210 SE Convenience Boulevard, just off I-35 at Exit 89. It suits I-35 travelers and visitors to the north metro who want free breakfast and parking within 15 minutes of the Iowa State Capitol.', geo_key_facts=ARRAY['77 rooms on three floors, opened 2008','6210 SE Convenience Blvd, just off I-35 at Exit 89','Less than three miles from Ankeny Regional Airport','About 15 minutes from the Iowa State Capitol','Free hot breakfast, free parking, indoor pool']::text[], geo_faq='[{"question":"How far is it from downtown Des Moines?","answer":"The hotel is about 15 minutes from the Iowa State Capitol."},{"question":"Which I-35 exit is it near?","answer":"It''s just off I-35 at Exit 89."},{"question":"Are pets allowed?","answer":"Up to two dogs or cats per room, with a non-refundable fee of $75 for stays up to four nights or $125 for five nights or more, per a directory listing."}]'::jsonb, updated_at=now() WHERE id='26ba8a48-8da5-4764-9ccc-f6519ab97812';
UPDATE hotels SET description='Hampton Inn & Suites Des Moines Downtown is a 131-room, six-floor hotel at 120 SW Water Street in downtown Des Moines, opened by Hilton in 2014. Breakfast is hot and free, Wi-Fi is free, rooms are non-smoking and there''s an indoor pool. Check-in is 3 PM and check-out is noon. Pets are allowed, up to two per room at 75 lbs each, for a non-refundable fee of $75 for one to four nights or $125 for five nights or more. It''s a straightforward downtown option for a family that wants breakfast and a pool included.', short_description='131-room downtown Des Moines hotel on SW Water Street with free hot breakfast, free Wi-Fi and an indoor pool.', seo_title='Hampton Inn & Suites Des Moines Downtown | DSM Hotels', seo_description='Hampton Inn & Suites Des Moines Downtown: 131 rooms on SW Water Street, opened 2014, with free hot breakfast, free Wi-Fi, an indoor pool and pet rooms.', seo_h1='Hampton Inn & Suites Des Moines Downtown', geo_summary='Hampton Inn & Suites Des Moines Downtown is a 131-room Hilton hotel at 120 SW Water Street, opened in 2014. It''s for visitors who want a downtown address with free hot breakfast and an indoor pool.', geo_key_facts=ARRAY['131 rooms on six floors, opened 2014','120 SW Water Street, downtown Des Moines','Free hot breakfast and free Wi-Fi','Indoor pool; non-smoking rooms','Check-in 3 PM, check-out 12 PM']::text[], geo_faq='[{"question":"Is breakfast included?","answer":"Yes, a free hot breakfast."},{"question":"Are pets allowed?","answer":"Yes, up to two pets of 75 lbs max each, with a non-refundable fee of $75 for 1-4 nights or $125 for 5+ nights."},{"question":"What are check-in and check-out times?","answer":"Check-in is 3:00 PM and check-out is 12:00 PM."}]'::jsonb, updated_at=now() WHERE id='d6b8be24-2c67-4f7a-b16e-3955cd81f853';
UPDATE hotels SET description='Hampton Inn & Suites Des Moines/Urbandale is at 8811 Plum Drive in Urbandale, on the northwest side of the metro, and opened in 2017 according to Trip.com. A free hot breakfast is included, parking on site is free, and the hotel has an indoor pool and a fitness center. Listings describe rooms with a refrigerator, microwave and coffee maker, including studio suites and two-queen rooms with a sofa sleeper. Check-in is after 3 PM and check-out before 11 AM, and the front desk is staffed around the clock.', short_description='Urbandale hotel on Plum Drive, opened 2017, with free hot breakfast, free parking, an indoor pool and a fitness center.', seo_title='Hampton Inn & Suites Urbandale | Hotels in Urbandale, IA', seo_description='Hampton Inn & Suites Des Moines/Urbandale on Plum Drive: opened 2017, with free hot breakfast, free parking, an indoor pool and a fitness center.', seo_h1='Hampton Inn & Suites Des Moines/Urbandale', geo_summary='Hampton Inn & Suites Des Moines/Urbandale is a Hilton hotel at 8811 Plum Drive in Urbandale, opened in 2017. It suits travelers on the northwest side of the metro who want free hot breakfast, free parking and a pool.', geo_key_facts=ARRAY['8811 Plum Drive, Urbandale','Opened 2017 (Trip.com)','Free hot breakfast and free on-site parking','Indoor pool and fitness center','Check-in 3 PM, check-out 11 AM']::text[], geo_faq='[{"question":"Is breakfast included?","answer":"Yes, a free hot breakfast. Listings give serving hours of 7-9 AM; confirm with the hotel."},{"question":"Is there a pool?","answer":"Yes, an indoor pool, plus a fitness center."},{"question":"What are check-in and check-out times?","answer":"Check-in is after 3:00 PM and check-out before 11:00 AM."}]'::jsonb, updated_at=now() WHERE id='f67ca7ae-657c-4d03-9a82-4cd597a72689';
UPDATE hotels SET description='Hampton Inn & Suites West Des Moines Jordan Creek is a 102-room, five-floor hotel at 6160 Mills Civic Parkway, about 1.1 miles from Jordan Creek Town Center. It opened in 2015 and was developed and is owned by Kinseth Hospitality. Breakfast is hot and free, Wi-Fi is free, and the hotel has a fitness center, accessible rooms, connecting rooms and pet-friendly rooms. Pets carry a $50 non-refundable fee with a 75 lb limit. Guests must be 21 to register. Check-in is 3 PM and check-out is noon.', short_description='102-room hotel on Mills Civic Parkway about 1.1 miles from Jordan Creek Town Center, with free hot breakfast and pet rooms.', seo_title='Hampton Inn & Suites WDM Jordan Creek | West Des Moines', seo_description='Hampton Inn & Suites West Des Moines Jordan Creek: 102 rooms on Mills Civic Parkway, about 1.1 miles from Jordan Creek Town Center, with free hot breakfast.', seo_h1='Hampton Inn & Suites West Des Moines Jordan Creek', geo_summary='Hampton Inn & Suites West Des Moines Jordan Creek is a 102-room Hilton hotel at 6160 Mills Civic Parkway, about 1.1 miles from Jordan Creek Town Center. It''s for shoppers and business travelers in West Des Moines who want free hot breakfast and pet-friendly rooms.', geo_key_facts=ARRAY['102 rooms on 5 floors, opened 2015','6160 Mills Civic Parkway, West Des Moines','About 1.1 miles from Jordan Creek Town Center','Free hot breakfast and Wi-Fi; fitness center','Guests must be 21 to register']::text[], geo_faq='[{"question":"How far is it from Jordan Creek Town Center?","answer":"About 1.1 miles, per the hotel guide."},{"question":"Are pets allowed?","answer":"Yes, with a $50 non-refundable pet fee and a 75 lb maximum weight."},{"question":"What is the minimum age to check in?","answer":"Guests must be 21 to register, per Hilton''s policy page."}]'::jsonb, updated_at=now() WHERE id='ebdaac64-1c09-4eec-b0cd-2dfab8e2b43c';
UPDATE hotels SET description='Quality Inn & Suites Des Moines - Merle Hay Road is a Choice Hotels property at 4995 NW Merle Hay Rd on the northwest side of Des Moines. Listings show a pool, breakfast, free Wi-Fi and free parking for guests, and the building is listed as wheelchair accessible. Check-in is at 3 PM and check-out at 11 AM. Merle Hay Mall is about 2.4 km away according to Expedia, which makes it a practical base for errands and shopping on the northwest side.', short_description='Choice Hotels property on NW Merle Hay Rd in Des Moines with a pool, breakfast, free Wi-Fi and free parking.', seo_title='Quality Inn & Suites Merle Hay Rd | Des Moines, IA Hotel', seo_description='Quality Inn & Suites on NW Merle Hay Rd, Des Moines: pool, breakfast, free Wi-Fi and free parking. Check-in 3 PM, check-out 11 AM, near Merle Hay Mall.', seo_h1='Quality Inn & Suites Des Moines - Merle Hay Road', geo_summary='Quality Inn & Suites Des Moines - Merle Hay Road is a Choice Hotels property at 4995 NW Merle Hay Rd, close to Merle Hay Mall. It suits drivers who want free parking, breakfast and a pool on the northwest side of Des Moines.', geo_key_facts=ARRAY['Address: 4995 NW Merle Hay Rd, Des Moines, IA 50322','Pool, breakfast, free Wi-Fi and free guest parking listed','Check-in 3 PM, check-out 11 AM','About 2.4 km from Merle Hay Mall (Expedia)']::text[], geo_faq='[{"question":"Is parking free?","answer":"Yes. Listings show free parking for guests."},{"question":"Is breakfast included?","answer":"Listings show breakfast as an amenity, and booking sites describe it as free."},{"question":"What are check-in and check-out times?","answer":"Check-in is at 3 PM and check-out is at 11 AM."}]'::jsonb, updated_at=now() WHERE id='185c2392-ed9d-4cb2-bc2a-b13ffc0438c8';
UPDATE hotels SET description='Quality Inn & Suites Des Moines Airport is a 55-room hotel at 5231 Fleur Dr, about half a mile from Des Moines International Airport. A free shuttle runs to the airport 24 hours a day, and a 7-day Park and Fly package lets you leave your car while you travel. Rooms come with free Wi-Fi, a hot breakfast is included, coffee is out around the clock, and there is an indoor pool. Check-in is 3 PM, check-out 11 AM. Pets are not allowed.', short_description='55-room hotel on Fleur Dr, half a mile from DSM airport, with a free 24-hour shuttle, hot breakfast and Park and Fly.', seo_title='Quality Inn & Suites Des Moines Airport | Fleur Dr Hotel', seo_description='55-room Quality Inn & Suites on Fleur Dr, half a mile from Des Moines airport. Free 24-hour shuttle, hot breakfast, indoor pool and a 7-day Park and Fly.', seo_h1='Quality Inn & Suites Des Moines Airport', geo_summary='Quality Inn & Suites Des Moines Airport is a 55-room hotel on Fleur Dr about half a mile from Des Moines International Airport. It is built around early flights: a free 24-hour shuttle, a Park and Fly package and hot breakfast.', geo_key_facts=ARRAY['55 rooms at 5231 Fleur Dr, Des Moines','About half a mile from Des Moines International Airport','Free 24-hour airport shuttle','7-day Park and Fly package','Free hot breakfast and indoor pool','No pets allowed']::text[], geo_faq='[{"question":"Does the hotel have an airport shuttle?","answer":"Yes. A free airport shuttle runs 24 hours a day."},{"question":"Can I leave my car while I fly?","answer":"The hotel offers a 7-day Park and Fly package."},{"question":"Are pets allowed?","answer":"No. The hotel does not allow pets."}]'::jsonb, updated_at=now() WHERE id='94601772-983a-47e6-8e94-7023ba5d263c';
UPDATE hotels SET description='Quality Inn West Des Moines - Clive is a two-story motor lodge at 1258 8th St in West Des Moines, just off I-235 and about 10 miles from Des Moines International Airport. It has an indoor pool, free on-the-go breakfast from 6 to 9 AM, complimentary coffee and free on-site parking. Pets are accepted for an added fee, with a 35 lb size limit. Two meeting rooms cover 1,638 sq ft for small groups. There is no on-site fitness center listed.', short_description='Two-story motor lodge off I-235 in West Des Moines with an indoor pool, free breakfast and free parking.', seo_title='Quality Inn West Des Moines - Clive | Hotel off I-235', seo_description='Quality Inn West Des Moines - Clive on 8th St, off I-235: indoor pool, free breakfast 6-9 AM, free parking, and pets up to 35 lb for a fee.', seo_h1='Quality Inn West Des Moines - Clive', geo_summary='Quality Inn West Des Moines - Clive is a two-story Choice Hotels motor lodge at 1258 8th St, just off I-235. It fits travelers who want an indoor pool, free breakfast and free parking, and it accepts pets up to 35 lb.', geo_key_facts=ARRAY['Address: 1258 8th St, West Des Moines, IA 50265','Two-story motor lodge off I-235','About 10 miles from Des Moines International Airport','Indoor pool and free breakfast (6-9 AM)','Pets accepted for a fee, 35 lb limit','2 meeting rooms, 1,638 sq ft']::text[], geo_faq='[{"question":"Is breakfast included?","answer":"Yes. A free on-the-go breakfast is served daily from 6 to 9 AM."},{"question":"Are pets allowed?","answer":"Yes, for an additional fee, with a size limit of 35 lb."},{"question":"How far is it from the airport?","answer":"About 10 miles from Des Moines International Airport."}]'::jsonb, updated_at=now() WHERE id='2701cd1e-09ce-4a17-80c6-6e473f0db3ac';
UPDATE hotels SET description='Ramada by Wyndham Des Moines Airport sits at 1810 Army Post Rd on the south side of Des Moines and runs a free shuttle to and from Des Moines International Airport. Every room has a microwave and refrigerator, and suites add a kitchen area and sofa bed. There is a heated indoor pool, a fitness center and free Wi-Fi, and the hotel is non-smoking. Eight meeting rooms total about 8,000 sq ft for groups up to 350. Blank Park Zoo and the Iowa State Fairgrounds are nearby.', short_description='Airport hotel on Army Post Rd with a free DSM shuttle, heated indoor pool and microwave and fridge in every room.', seo_title='Ramada Des Moines Airport | Army Post Rd Hotel, Des Moines', seo_description='Ramada by Wyndham on Army Post Rd: free shuttle to Des Moines International Airport, heated indoor pool, fitness center and 8 meeting rooms.', seo_h1='Ramada by Wyndham Des Moines Airport', geo_summary='Ramada by Wyndham Des Moines Airport is a non-smoking hotel at 1810 Army Post Rd with a free shuttle to Des Moines International Airport. It suits fliers and groups, with suites that have kitchen areas and eight meeting rooms.', geo_key_facts=ARRAY['Address: 1810 Army Post Rd, Des Moines, IA 50315','Free shuttle to and from Des Moines International Airport','Microwave and refrigerator in every room; suites with kitchen area','Heated indoor pool and fitness center','8 meeting rooms, about 8,000 sq ft, up to 350 guests','Near Blank Park Zoo and the Iowa State Fairgrounds']::text[], geo_faq='[{"question":"Is there an airport shuttle?","answer":"Yes. The hotel runs a free shuttle to and from Des Moines International Airport."},{"question":"Do rooms have a fridge and microwave?","answer":"Yes. Every room has a microwave and refrigerator, and suites have a kitchen area."},{"question":"Does the hotel have a pool?","answer":"Yes, a heated indoor pool."}]'::jsonb, updated_at=now() WHERE id='84d20ac2-05d8-4fef-b0fa-344eb3c00e1d';
UPDATE hotels SET description='The Ramada by Wyndham Des Moines Tropics Resort & Conference Center is at 5000 Merle Hay Rd, off I-35 and I-80 near Merle Hay Mall. Its draw is an 18,000 sq ft indoor water park with waterslides and a pirate ship play center, plus a pool and hot tub open 9 AM to 9 PM. Breakfast is served at Boss Pizzeria and Sports Bar, which stays open until 2 AM, and there is a poolside tiki bar. Six meeting rooms cover about 10,000 sq ft for up to 350. Wi-Fi is free.', short_description='Merle Hay Rd resort hotel with an 18,000 sq ft indoor water park, Boss Pizzeria and 10,000 sq ft of meeting space.', seo_title='Ramada Tropics Resort Des Moines | Water Park Hotel', seo_description='Ramada Tropics Resort on Merle Hay Rd, Des Moines: 18,000 sq ft indoor water park, Boss Pizzeria and Sports Bar, free Wi-Fi and six meeting rooms.', seo_h1='Ramada by Wyndham Des Moines Tropics Resort & Conference Center', geo_summary='The Ramada Tropics Resort is a Des Moines hotel at 5000 Merle Hay Rd built around an 18,000 sq ft indoor water park. It suits families and groups, with an on-site pizzeria and sports bar and about 10,000 sq ft of meeting space.', geo_key_facts=ARRAY['Address: 5000 Merle Hay Rd, Des Moines, IA 50322','18,000 sq ft indoor water park with slides and a pirate ship play center','Pool and hot tub open 9 AM-9 PM; hot tub 18+','Boss Pizzeria and Sports Bar serves breakfast, lunch and dinner','6 meeting rooms, about 10,000 sq ft, up to 350 guests','Off I-35 and I-80, near Merle Hay Mall']::text[], geo_faq='[{"question":"Does the hotel have a water park?","answer":"Yes. An 18,000 sq ft indoor water park with waterslides and a pirate ship play center; hours vary by season."},{"question":"Where is breakfast served?","answer":"Breakfast is served each morning at Boss Pizzeria and Sports Bar on site."},{"question":"Is the hotel pet-friendly?","answer":"The hotel describes itself as pet-friendly; extra charges may apply, so ask the hotel for details."}]'::jsonb, updated_at=now() WHERE id='596a10f0-2d1e-4c1d-86a6-de29e6ec959c';
UPDATE hotels SET description='Red Lion Inn & Suites Grimes is a Sonesta-brand hotel at 251 Gateway Cir in Grimes, on the northwest edge of the Des Moines metro. A free continental breakfast runs daily from 6 to 9 AM, and there is an indoor heated pool with a hot tub and sauna. Wi-Fi and parking are free, with long-term parking available for a nightly fee. Check-in is 3 PM and check-out 11 AM, with paid early and late options. Jester Park, Big Creek Park and Saylorville Lake are nearby for outdoor time.', short_description='Sonesta-brand hotel in Grimes with free breakfast, an indoor heated pool, hot tub, sauna and free parking.', seo_title='Red Lion Inn & Suites Grimes | Hotels in Grimes, IA', seo_description='Red Lion Inn & Suites in Grimes, IA: free continental breakfast 6-9 AM, indoor heated pool, hot tub, sauna, free Wi-Fi and free parking.', seo_h1='Red Lion Inn & Suites Grimes', geo_summary='Red Lion Inn & Suites Grimes is a Sonesta-brand hotel at 251 Gateway Cir in Grimes, Iowa. It suits travelers on the northwest side of the metro who want free breakfast, a pool and free parking near Jester Park and Saylorville Lake.', geo_key_facts=ARRAY['Address: 251 Gateway Cir, Grimes, IA 50111','Free continental breakfast daily, 6-9 AM','Indoor heated pool, hot tub and sauna','Free Wi-Fi and free parking; long-term parking $15/night','Check-in 3 PM (early 11 AM for $30); check-out 11 AM (late to 6 PM for $50)']::text[], geo_faq='[{"question":"Is breakfast included?","answer":"Yes. A free continental breakfast is served daily from 6 to 9 AM."},{"question":"Can I check in early or check out late?","answer":"Early check-in at 11 AM costs $30 and late check-out until 6 PM costs $50. Standard times are 3 PM and 11 AM."},{"question":"Is parking free?","answer":"Yes. Long-term parking is $15 per night."}]'::jsonb, updated_at=now() WHERE id='baa94e37-1144-43ea-8e92-83a323475b1e';
UPDATE hotels SET description='Red Roof Inn Des Moines is a 55-room motel at 5020 NE 14th St on the north side of Des Moines, about 2 miles from Grand View University. Rooms have one or two beds, parking is free, and bus parking is available. The pet policy is generous: one well-behaved cat or dog stays free, a second costs $15 a night, and pets must be under 80 lb and declared at check-in. Service and emotional support animals are always welcome. Expect a $100 refundable incidentals deposit.', short_description='55-room motel on NE 14th St in Des Moines with free parking; one pet stays free.', seo_title='Red Roof Inn Des Moines | NE 14th St Pet-Friendly Motel', seo_description='Red Roof Inn Des Moines on NE 14th St: 55 rooms, free parking, bus parking, and one pet stays free (under 80 lb). About 2 miles from Grand View University.', seo_h1='Red Roof Inn Des Moines', geo_summary='Red Roof Inn Des Moines is a 55-room motel at 5020 NE 14th St on the north side of the city. It suits budget travelers with pets, since one pet stays free, and drivers who need free or bus parking.', geo_key_facts=ARRAY['55 rooms at 5020 NE 14th St, Des Moines, IA 50313','One pet stays free; second pet $15/night; under 80 lb','Free parking and bus parking','$100 refundable incidentals deposit','About 2 miles from Grand View University']::text[], geo_faq='[{"question":"Are pets allowed?","answer":"Yes. One well-behaved cat or dog stays free, a second is $15 per night, pets must be under 80 lb and declared at check-in."},{"question":"Is there a deposit?","answer":"Yes, a $100 refundable deposit for incidentals is required."},{"question":"Is parking free?","answer":"Yes, parking is complimentary, and bus parking is available."}]'::jsonb, updated_at=now() WHERE id='d2061cc5-b275-4f8b-a989-19814c927094';
UPDATE hotels SET description='The Renaissance Des Moines Savery Hotel is a 212-room Marriott hotel at 401 Locust St downtown, in a building dating to 1919. It connects to the 4-mile climate-controlled skywalk, so Wells Fargo Arena, the Iowa Events Center and the Civic Center are reachable without going outside. Revelry Room Bar + Kitchen is the main restaurant and Scopri serves breakfast. There is an indoor pool, seven meeting rooms and a complimentary airport shuttle; the airport is about 4.7 miles away. Valet parking is $37 a day.', short_description='212-room downtown hotel from 1919 on Locust St, on the skywalk near Wells Fargo Arena, with Revelry Room and a pool.', seo_title='Renaissance Des Moines Savery Hotel | Downtown Des Moines', seo_description='Renaissance Savery Hotel, 401 Locust St: 212 rooms in a 1919 building on the downtown skywalk, Revelry Room Bar + Kitchen, indoor pool, airport shuttle.', seo_h1='Renaissance Des Moines Savery Hotel', geo_summary='The Renaissance Des Moines Savery Hotel is a 212-room Marriott hotel in a 1919 building at 401 Locust St, connected to downtown''s skywalk. It suits event-goers and business travelers heading to Wells Fargo Arena, the Iowa Events Center or the Civic Center.', geo_key_facts=ARRAY['212 rooms at 401 Locust St, downtown Des Moines','Built 1919; reopened after renovation (2018)','Connected to the 4-mile skywalk','Revelry Room Bar + Kitchen; Scopri for breakfast','Valet parking $37/day; complimentary airport shuttle','Check-in 4 PM, check-out 11 AM']::text[], geo_faq='[{"question":"How do I get to Wells Fargo Arena?","answer":"The hotel connects to downtown''s 4-mile climate-controlled skywalk, which links to Wells Fargo Arena and the Iowa Events Center."},{"question":"How much is parking?","answer":"Valet parking is $37 per day."},{"question":"Are pets allowed?","answer":"The current marriott.com listing allows one pet per room up to 30 lb."}]'::jsonb, updated_at=now() WHERE id='2725d4dd-aa69-4b43-8f6b-356be9fc4045';
UPDATE hotels SET description='Residence Inn Des Moines Ankeny is a 90-suite extended-stay hotel at 1515 SW Main St in Ankeny''s District at Prairie Trail, with restaurants and shops within walking distance. It opened in October 2019. Studio, one- and two-bedroom suites have full kitchens, a hot breakfast buffet is included, and there is an indoor pool, fitness center and patio fire pit. Parking is free. Pets are welcome, up to two per room, for a $150 fee per stay. The airport is about 15 miles away.', short_description='90-suite extended-stay hotel in Ankeny''s District at Prairie Trail with kitchens, hot breakfast and free parking.', seo_title='Residence Inn Des Moines Ankeny | Hotels in Ankeny, IA', seo_description='Residence Inn Ankeny at Prairie Trail: 90 suites with full kitchens, free hot breakfast, indoor pool, free parking and pets welcome ($150 per stay).', seo_h1='Residence Inn Des Moines Ankeny', geo_summary='Residence Inn Des Moines Ankeny is a 90-suite Marriott extended-stay hotel at 1515 SW Main St in The District at Prairie Trail. It suits longer stays and families who want a kitchen, free breakfast and walkable restaurants in Ankeny.', geo_key_facts=ARRAY['90 suites at 1515 SW Main St, Ankeny','Opened October 2019','Studio, one- and two-bedroom suites with full kitchens','Free hot breakfast, indoor pool, fitness center','Pets welcome: up to 2, $150 per stay','About 15 miles from Des Moines International Airport']::text[], geo_faq='[{"question":"Is breakfast included?","answer":"Yes, a complimentary hot breakfast buffet is served each morning."},{"question":"Are pets allowed?","answer":"Yes, up to two pets per room with a $150 non-refundable fee per stay."},{"question":"What are check-in and check-out times?","answer":"Check-in is at 4 PM and check-out at 12 PM; minimum check-in age is 21."}]'::jsonb, updated_at=now() WHERE id='de647fce-ae5b-4dfb-bc27-076ebb01a8f0';
UPDATE hotels SET description='Residence Inn Des Moines Downtown is a 127-suite, five-story extended-stay hotel at 100 SW Water St on the Des Moines River, near Principal Park and the Court Avenue district. Studio, one- and two-bedroom suites have kitchens with a cooktop and full-size refrigerator. Breakfast is free, and the property has an indoor heated pool, hot tub, fitness center, sports court, putting green and a fire-pit patio. Parking on site carries a fee. Pets are accepted for an added fee. Check-in is 4 PM.', short_description='127-suite extended-stay hotel on the Des Moines River near Principal Park, with kitchens, free breakfast and a pool.', seo_title='Residence Inn Des Moines Downtown | Water St Hotel', seo_description='Residence Inn Downtown on SW Water St: 127 suites with kitchens, free breakfast, indoor pool, sports court and putting green, near Principal Park.', seo_h1='Residence Inn Des Moines Downtown', geo_summary='Residence Inn Des Moines Downtown is a 127-suite Marriott extended-stay hotel at 100 SW Water St on the Des Moines River. It suits longer stays and Iowa Cubs fans, near Principal Park and the Court Avenue district.', geo_key_facts=ARRAY['127 suites over five stories, smoke-free','100 SW Water St, on the Des Moines River','Near Principal Park and the Court Avenue district','Kitchens with cooktop and full-size refrigerator','Free breakfast, indoor heated pool, sports court, putting green','Check-in 4 PM, check-out 12 PM']::text[], geo_faq='[{"question":"Is breakfast included?","answer":"Yes, breakfast is free."},{"question":"Is parking free?","answer":"No. On-site parking carries a fee."},{"question":"Are pets allowed?","answer":"Yes, pets are accepted for an additional fee."}]'::jsonb, updated_at=now() WHERE id='fab49767-bdcb-4fe1-b842-8342effd4d74';
UPDATE hotels SET description='Residence Inn Des Moines West at Jordan Creek is a 122-suite extended-stay hotel at 160 S Jordan Creek Pkwy in West Des Moines, right outside Jordan Creek Town Center and minutes from Wells Fargo offices. Built in 2004, it is all-suite and smoke-free. Breakfast is free, and there is an indoor pool, hot tub, fitness center and on-site laundry. Self parking is $10 a day. Pets are welcome, up to two and 100 lb, for a $100 fee per stay. The airport is about 15 miles away.', short_description='122-suite extended-stay hotel beside Jordan Creek Town Center with free breakfast, indoor pool and pets welcome.', seo_title='Residence Inn West at Jordan Creek | West Des Moines, IA', seo_description='Residence Inn West at Jordan Creek: 122 suites by Jordan Creek Town Center, free breakfast, indoor pool, $10 parking and pets welcome ($100 per stay).', seo_h1='Residence Inn Des Moines West at Jordan Creek, West Des Moines', geo_summary='Residence Inn Des Moines West at Jordan Creek is a 122-suite Marriott extended-stay hotel beside Jordan Creek Town Center in West Des Moines. It suits longer business stays near the Wells Fargo offices and shoppers who want the mall next door.', geo_key_facts=ARRAY['122 suites at 160 S Jordan Creek Pkwy, West Des Moines','Right outside Jordan Creek Town Center','Built in 2004; all-suite, smoke-free','Free breakfast, indoor pool, hot tub','Self parking $10/day','About 15 miles from Des Moines International Airport']::text[], geo_faq='[{"question":"How close is Jordan Creek Town Center?","answer":"The hotel is right outside Jordan Creek Town Center."},{"question":"Are pets allowed?","answer":"Yes. Up to two pets, 100 lb max, with a $100 non-refundable fee per stay."},{"question":"How much is parking?","answer":"Self parking is $10 per day."}]'::jsonb, updated_at=now() WHERE id='199f6c4f-2584-41c0-8614-06bd1a5b1396';
UPDATE hotels SET description='Revel Hotel Des Moines Urbandale is a Tapestry Collection by Hilton hotel at 11211 Hickman Rd in Urbandale. Its design nods to Iowa farm country, using patterns and textures from the farm landscape with natural materials and bright colors. The on-site Revel Lounge serves American food at breakfast, lunch and dinner and has a bar. Outside there is a terrace and a fire pit. Listings show free parking, free Wi-Fi and pet-friendly rooms. A venue directory lists 110 rooms on three floors, renovated in 2019.', short_description='Tapestry Collection by Hilton hotel on Hickman Rd in Urbandale with farm-inspired design, Revel Lounge and a fire pit.', seo_title='Revel Hotel Urbandale, Tapestry Collection | Urbandale, IA', seo_description='Revel Hotel on Hickman Rd in Urbandale, a Tapestry Collection by Hilton hotel with farm-inspired design, Revel Lounge, a terrace fire pit and free parking.', seo_h1='Revel Hotel Des Moines Urbandale, Tapestry Collection by Hilton', geo_summary='Revel Hotel Des Moines Urbandale is a Tapestry Collection by Hilton hotel at 11211 Hickman Rd with a design drawn from Iowa farm landscapes. It suits travelers on the west side who want an on-site restaurant and bar, free parking and a pet-friendly room.', geo_key_facts=ARRAY['Address: 11211 Hickman Rd, Urbandale, IA 50322','Tapestry Collection by Hilton','Design draws on Iowa farm-landscape patterns and textures','Revel Lounge serves breakfast, lunch and dinner','Terrace with fire pit; free parking and Wi-Fi','110 rooms, 3 floors, renovated 2019 (venue directory)']::text[], geo_faq='[{"question":"Does the hotel have a restaurant?","answer":"Yes. Revel Lounge serves American food at breakfast, lunch and dinner."},{"question":"Is parking free?","answer":"Listings show free parking."},{"question":"Are pets allowed?","answer":"Listings describe the hotel as pet-friendly; a venue directory notes a fee."}]'::jsonb, updated_at=now() WHERE id='327bf2cf-52c9-49c3-ac23-8386fb09b81a';
UPDATE hotels SET description='Sheraton West Des Moines Hotel is a 285-room hotel at 1800 50th St, near Exit 124 on I-80 and about half a mile from Living History Farms and the Clive Aquatic Center. It has about 29,000 sq ft of event space in 14 meeting rooms, including a 12,000 sq ft room that seats 1,200 theater-style, so it is set up for conferences and large banquets. Rooms include 57 suites. There is an indoor pool and an on-site gym. Check-in is 3 PM and check-out 12 PM.', short_description='285-room West Des Moines hotel off I-80 Exit 124 with about 29,000 sq ft of meeting space and an indoor pool.', seo_title='Sheraton West Des Moines Hotel | Hotels off I-80', seo_description='Sheraton West Des Moines on 50th St near I-80 Exit 124: 285 rooms including 57 suites, about 29,000 sq ft of meeting space, indoor pool and gym.', seo_h1='Sheraton West Des Moines Hotel', geo_summary='Sheraton West Des Moines Hotel is a 285-room Marriott hotel at 1800 50th St, just off I-80 Exit 124. It suits conferences and group events, with 14 meeting rooms and a 12,000 sq ft hall, and travelers who want quick interstate access.', geo_key_facts=ARRAY['285 rooms including 57 suites, 1800 50th St','Near Exit 124 on I-80','14 meeting rooms, about 29,197 sq ft of event space','Largest room 12,000 sq ft, 1,200 theater-style','About half a mile from Living History Farms','Check-in 3 PM, check-out 12 PM']::text[], geo_faq='[{"question":"How close is Living History Farms?","answer":"About half a mile, per a hotel listing."},{"question":"Does the hotel have a pool?","answer":"Yes, an indoor pool, plus an on-site gym."},{"question":"How much meeting space is there?","answer":"A venue directory lists 14 meeting rooms with about 29,197 sq ft, the largest 12,000 sq ft."}]'::jsonb, updated_at=now() WHERE id='0331d5a8-7cc4-4665-99b9-a564b843f724';
UPDATE hotels SET description='Sleep Inn & Suites Ankeny - Des Moines is a 67-room, smoke-free Choice Hotels property at 2406 SE Tones Dr in Ankeny. Rooms have a refrigerator, microwave and flat-screen TV. Breakfast is free, and the hotel has an indoor pool, hot tub, fitness center and a small snack bar. Parking and Wi-Fi are free, and there is a guest laundry. Check-in starts at 3 PM and check-out is by 11 AM. Woodland Hills Golf Course is about 2.4 miles away.', short_description='67-room smoke-free hotel on SE Tones Dr in Ankeny with free breakfast, an indoor pool and free parking.', seo_title='Sleep Inn & Suites Ankeny | Hotels in Ankeny, IA', seo_description='Sleep Inn & Suites Ankeny on SE Tones Dr: 67 smoke-free rooms with fridge and microwave, free breakfast, indoor pool, hot tub, free parking and Wi-Fi.', seo_h1='Sleep Inn & Suites Ankeny - Des Moines', geo_summary='Sleep Inn & Suites Ankeny - Des Moines is a 67-room Choice Hotels property at 2406 SE Tones Dr in Ankeny. It suits drivers who want free breakfast, a pool and free parking on the north side of the metro.', geo_key_facts=ARRAY['67 rooms at 2406 SE Tones Dr, Ankeny','Smoke-free property','Free breakfast; indoor pool, hot tub and fitness center','Fridge and microwave in rooms','Free parking and Wi-Fi','Check-in 3 PM, check-out 11 AM']::text[], geo_faq='[{"question":"Is breakfast included?","answer":"Yes. Listings show a free breakfast, served 6 to 9 AM on weekdays and 6 to 10 AM on weekends."},{"question":"Is parking free?","answer":"Yes, free self parking on site."},{"question":"What are check-in and check-out times?","answer":"Check-in is after 3 PM and check-out is before 11 AM."}]'::jsonb, updated_at=now() WHERE id='ff929076-fc3d-4262-a7e4-d2d51ff149db';
UPDATE hotels SET description='AC Hotel by Marriott Des Moines East Village is a 109-room hotel at 401 E Grand Ave in the East Village, east of the Des Moines River from downtown. Three of the rooms are suites, and rooms come with free WiFi, smart TVs and a refrigerator. Breakfast is the European-style spread at AC Kitchen, and the AC Lounge works as a place to get work done during the day before turning into the bar at night. There is a fitness center on site. Check-in is at 3 PM and check-out at 11 AM.', short_description='109-room AC Hotel at 401 E Grand Ave in the East Village, with AC Kitchen breakfast and the AC Lounge bar.', seo_title='AC Hotel Des Moines East Village | Hotels in Des Moines', seo_description='AC Hotel by Marriott at 401 E Grand Ave in the East Village: 109 rooms, European-style AC Kitchen breakfast, AC Lounge bar, fitness center and free WiFi.', seo_h1='AC Hotel by Marriott Des Moines East Village', geo_summary='AC Hotel by Marriott Des Moines East Village is a 109-room Marriott hotel at 401 E Grand Ave in the Des Moines East Village. It suits travellers who want to stay in the East Village with breakfast and a bar in the building.', geo_key_facts=ARRAY['Address: 401 E Grand Ave, Des Moines (East Village)','109 rooms, including 3 suites','AC Kitchen serves a European-style breakfast','AC Lounge is a workspace by day and a bar by night','Check-in 3:00 PM, check-out 11:00 AM']::text[], geo_faq='[{"question":"What time is check-in at AC Hotel Des Moines East Village?","answer":"Check-in is at 3:00 PM and check-out is at 11:00 AM."},{"question":"Does AC Hotel Des Moines East Village serve breakfast?","answer":"Yes. AC Kitchen serves a European-style breakfast."},{"question":"Is there a bar at the AC Hotel in the East Village?","answer":"Yes. The AC Lounge is a workspace during the day and a bar at night."}]'::jsonb, updated_at=now() WHERE id='703a5cd0-885e-4c0c-8cb1-dd262bfd7667';
UPDATE hotels SET description='Aloft Waukee is a four-story, 126-room hotel at 2848 Grand Prairie Pkwy in the KeeTown Loop entertainment district, next door to Vibrant Music Hall. It opened in 2024 as Iowa''s first Aloft. Marriott puts Jordan Creek Town Center about 10 minutes away. On site there is the W XYZ bar, the Re:mix lounge, a 24-hour pantry, an indoor pool, a fitness center and a business center. Parking is $5 per day and pets are welcome for a non-refundable $50-per-night fee, per listings. Check-in is 3 PM, check-out noon.', short_description='Iowa''s first Aloft: 126 rooms in Waukee''s KeeTown Loop, next door to Vibrant Music Hall, with an indoor pool and W XYZ bar.', seo_title='Aloft Waukee | Hotels in Waukee, IA', seo_description='Aloft Waukee, Iowa''s first Aloft, has 126 rooms in the KeeTown Loop next to Vibrant Music Hall, with an indoor pool, W XYZ bar and a 24-hour pantry.', seo_h1='Aloft Waukee', geo_summary='Aloft Waukee is a 126-room Marriott hotel that opened in 2024 in Waukee''s KeeTown Loop district, next door to Vibrant Music Hall. It fits concertgoers and west-metro visitors who want an indoor pool and a bar on site, about 10 minutes from Jordan Creek Town Center.', geo_key_facts=ARRAY['Iowa''s first Aloft hotel, completed in 2024','126 rooms on four floors','Next door to Vibrant Music Hall in the KeeTown Loop','About 10 minutes from Jordan Creek Town Center (per Marriott)','On-site parking $5 per day','Pets welcome for a $50 non-refundable fee per night (per listing)']::text[], geo_faq='[{"question":"Is Aloft Waukee close to Vibrant Music Hall?","answer":"Yes. The hotel is next door to Vibrant Music Hall in the KeeTown Loop entertainment district."},{"question":"Does Aloft Waukee allow pets?","answer":"Pets are welcome; listings show a non-refundable pet fee of $50 per night."},{"question":"Is parking free at Aloft Waukee?","answer":"No. On-site parking is listed at $5 per day."}]'::jsonb, updated_at=now() WHERE id='9b0d24c8-673b-49e4-8980-d912a6721c7e';
UPDATE hotels SET description='AmericInn by Wyndham Des Moines Airport is at 1920 Hackley Ave, across from Des Moines International Airport and near I-35 and I-235. A free 24/7 airport shuttle runs to the terminal, and parking is free for the length of your stay. Breakfast is a free buffet with waffles, scrambled eggs and biscuits and gravy. The hotel has an indoor pool, a fitness center and guest laundry, and every non-smoking room has free WiFi. Wyndham lists Blank Park Zoo and Drake University among the places nearby.', short_description='Airport hotel at 1920 Hackley Ave, across from DSM, with a free 24/7 shuttle, free parking, free breakfast and an indoor pool.', seo_title='AmericInn Des Moines Airport | Hotels in Des Moines, IA', seo_description='AmericInn by Wyndham at 1920 Hackley Ave sits across from Des Moines International Airport, with a free 24/7 shuttle, free parking, breakfast and a pool.', seo_h1='AmericInn by Wyndham Des Moines Airport', geo_summary='AmericInn by Wyndham Des Moines Airport is a hotel at 1920 Hackley Ave, across from Des Moines International Airport near I-35 and I-235. It is built for travellers with early flights or a car to park, with a free 24/7 airport shuttle, free parking and free breakfast.', geo_key_facts=ARRAY['Address: 1920 Hackley Ave, Des Moines, IA 50315','Across from Des Moines International Airport (DSM), near I-35 and I-235','Free 24/7 airport shuttle','Free parking and free WiFi','Free breakfast buffet; indoor pool, fitness center, guest laundry']::text[], geo_faq='[{"question":"Does AmericInn Des Moines Airport have an airport shuttle?","answer":"Yes. Wyndham lists a free 24/7 airport shuttle; the hotel is across from Des Moines International Airport."},{"question":"Is parking free at AmericInn Des Moines Airport?","answer":"Yes. Wyndham says parking is free during your stay."},{"question":"Is breakfast included at AmericInn Des Moines Airport?","answer":"Yes. A free breakfast buffet includes waffles, scrambled eggs and biscuits and gravy."}]'::jsonb, updated_at=now() WHERE id='efaab402-5a12-4846-9e66-d03751f0d932';
UPDATE hotels SET description='AmericInn by Wyndham Johnston Des Moines is at 5050 Merle Hay Rd in Johnston, off I-80 and I-35 and a short drive from Des Moines International Airport. Camp Dodge and the Iowa Gold Star Military Museum are among the nearby places Wyndham lists. Breakfast is free and includes waffles and eggs, parking is free, and every room has free WiFi. There is a heated indoor pool. Dogs can stay in designated pet-friendly rooms for a small fee.', short_description='Johnston hotel at 5050 Merle Hay Rd off I-80 and I-35, with free breakfast, free parking, a heated indoor pool and dog-friendly rooms.', seo_title='AmericInn Johnston Des Moines | Hotels in Johnston, IA', seo_description='AmericInn by Wyndham at 5050 Merle Hay Rd in Johnston, off I-80 and I-35: free breakfast, free parking and WiFi, a heated indoor pool and pet-friendly rooms.', seo_h1='AmericInn by Wyndham Johnston Des Moines', geo_summary='AmericInn by Wyndham Johnston Des Moines is a hotel at 5050 Merle Hay Rd in Johnston, off I-80 and I-35 on the north side of the metro. It suits drivers, families and dog owners who want free breakfast, free parking and a heated indoor pool near Camp Dodge.', geo_key_facts=ARRAY['Address: 5050 Merle Hay Rd, Johnston, IA 50131','Off I-80 and I-35; near Camp Dodge','Free breakfast with waffles and eggs','Free parking and free WiFi in every room','Heated indoor pool','Dogs allowed in pet-friendly rooms for a fee']::text[], geo_faq='[{"question":"Does AmericInn Johnston allow dogs?","answer":"Yes. You can book a pet-friendly room for a small fee."},{"question":"Is breakfast free at AmericInn Johnston Des Moines?","answer":"Yes. Wyndham lists a free breakfast that includes waffles and eggs."},{"question":"Does AmericInn Johnston have a pool?","answer":"Yes, a heated indoor pool."}]'::jsonb, updated_at=now() WHERE id='653f2ece-157d-4bcf-9e82-33fac7988b66';
UPDATE hotels SET description='Baymont by Wyndham Des Moines Airport is a 56-room hotel at 6221 Willow Creek Ave, minutes from Des Moines International Airport and across the street from Willow Creek Golf Course. The airport shuttle is free, and the parking lot has room for large vehicles. Continental breakfast is included. There is a heated indoor pool and hot tub, a fitness center, an arcade and a gift shop. About 4,000 sq ft of meeting space across four rooms holds up to 250 guests. Built in 1995 and renovated in 2019, the property is non-smoking.', short_description='56-room airport hotel across from Willow Creek Golf Course, with a free airport shuttle, free breakfast and a heated indoor pool.', seo_title='Baymont Des Moines Airport | Hotels in Des Moines, IA', seo_description='Baymont by Wyndham at 6221 Willow Creek Ave: 56 rooms, free shuttle to Des Moines International Airport, free continental breakfast, indoor pool and hot tub.', seo_h1='Baymont by Wyndham Des Moines Airport', geo_summary='Baymont by Wyndham Des Moines Airport is a 56-room hotel at 6221 Willow Creek Ave, minutes from Des Moines International Airport and across from Willow Creek Golf Course. It suits fliers, golfers and groups needing meeting rooms, with a free airport shuttle and free breakfast.', geo_key_facts=ARRAY['56 rooms at 6221 Willow Creek Ave','Free shuttle to Des Moines International Airport','Across the street from Willow Creek Golf Course','Free continental breakfast; heated indoor pool and hot tub','About 4,000 sq ft of meeting space in four rooms, up to 250 guests','Built 1995, renovated 2019; non-smoking']::text[], geo_faq='[{"question":"Does Baymont Des Moines Airport have a free airport shuttle?","answer":"Yes. Wyndham lists a free shuttle to Des Moines International Airport."},{"question":"What time is check-in and check-out at Baymont Des Moines Airport?","answer":"Check-in is at 3:00 PM and check-out is at 12:00 PM."},{"question":"Is there parking for trucks or large vehicles?","answer":"Yes. Parking includes space for large vehicles."}]'::jsonb, updated_at=now() WHERE id='ed40c936-b3a5-41ff-a536-40ee3b8e1c47';
UPDATE hotels SET description='Baymont by Wyndham Des Moines North is at 4685 NE 14th St on the north side of Des Moines, off I-80 and I-35. Wyndham describes it as minutes from the Polk County Convention Center and the Iowa State Fairgrounds, and lists Prairie Meadows, Wells Fargo Arena and the Iowa State Capitol among the places nearby. Breakfast is free and hot, WiFi is free, and there is a heated indoor pool. It works as a base for State Fair trips or for drivers coming off the interstate on the north edge of the city.', short_description='North Des Moines hotel at 4685 NE 14th St off I-80 and I-35, with free hot breakfast, free WiFi and a heated indoor pool.', seo_title='Baymont Des Moines North | Hotels in Des Moines, IA', seo_description='Baymont by Wyndham at 4685 NE 14th St, off I-80 and I-35 near the Iowa State Fairgrounds, with free hot breakfast, free WiFi and a heated indoor pool.', seo_h1='Baymont by Wyndham Des Moines North', geo_summary='Baymont by Wyndham Des Moines North is a hotel at 4685 NE 14th St on the north side of Des Moines, off I-80 and I-35. It suits interstate drivers and Iowa State Fair visitors who want free hot breakfast and an indoor pool.', geo_key_facts=ARRAY['Address: 4685 NE 14th St, Des Moines, IA 50313','Off I-80 and I-35','Minutes from the Polk County Convention Center and Iowa State Fairgrounds (per Wyndham)','Free hot breakfast and free WiFi','Heated indoor pool']::text[], geo_faq='[{"question":"Is Baymont Des Moines North near the Iowa State Fairgrounds?","answer":"Wyndham describes the hotel as minutes from the Iowa State Fairgrounds and the Polk County Convention Center; it does not give an exact distance."},{"question":"Does Baymont Des Moines North serve breakfast?","answer":"Yes. Wyndham lists a free hot breakfast."},{"question":"Does Baymont Des Moines North have a pool?","answer":"Yes, a heated indoor pool."}]'::jsonb, updated_at=now() WHERE id='ea841489-2345-4bd0-8abf-c90c73fa77ad';
UPDATE hotels SET description='Best Western Plus Altoona Inn is at 300 34th Avenue NW in Altoona, east of Des Moines. Best Western describes it as near Adventureland and the outlets in Altoona and minutes from Des Moines, which makes it a practical stop for a theme park or shopping trip. Breakfast and parking are free, and the hotel has a pool, a fitness center and high-speed internet. Pets are not accepted. Check-in is at 3 PM and check-out at 11 AM.', short_description='Altoona hotel at 300 34th Avenue NW near Adventureland and the Altoona outlets, with free breakfast, free parking and a pool.', seo_title='Best Western Plus Altoona Inn | Hotels in Altoona, IA', seo_description='Best Western Plus Altoona Inn at 300 34th Avenue NW, near Adventureland and the outlets in Altoona, with free breakfast, free parking and a pool.', seo_h1='Best Western Plus Altoona Inn', geo_summary='Best Western Plus Altoona Inn is a hotel at 300 34th Avenue NW in Altoona, near Adventureland and the outlets. It suits families and shoppers who want free breakfast, free parking and a pool, and who are travelling without pets.', geo_key_facts=ARRAY['Address: 300 34th Avenue NW, Altoona','Near Adventureland and the outlets in Altoona (per Best Western)','Free breakfast and free parking','Pool and fitness center','Pets are not accepted','Check-in 3:00 PM, check-out 11:00 AM']::text[], geo_faq='[{"question":"Is Best Western Plus Altoona Inn near Adventureland?","answer":"Yes. Best Western describes it as near Adventureland and the outlets in Altoona; no exact distance is given."},{"question":"Does Best Western Plus Altoona Inn allow pets?","answer":"No. Pets are not accepted."},{"question":"Is breakfast free at Best Western Plus Altoona Inn?","answer":"Yes. Breakfast and parking are both free."}]'::jsonb, updated_at=now() WHERE id='a07d632e-2512-45c8-91d2-d51ba86293e6';
UPDATE hotels SET description='Best Western Plus Des Moines West Inn & Suites is a three-story, 64-room hotel at 1450 NW 118th St in Clive, near the I-80/I-35 interchange and about seven miles west of downtown Des Moines. Des Moines International Airport is about a 15 to 18 minute drive. Breakfast is included, and rooms have a coffeemaker, microwave and refrigerator. There is an indoor heated pool, a hot tub, a fitness center, a business center and free wireless internet. The property is smoke-free and accepts pets for an extra fee, per AAA.', short_description='64-room Clive hotel near the I-80/I-35 interchange, with breakfast included, an indoor heated pool and pets accepted for a fee.', seo_title='Best Western Plus Des Moines West | Hotels in Clive, IA', seo_description='Best Western Plus Des Moines West Inn & Suites in Clive: 64 rooms near the I-80/I-35 interchange, breakfast included, indoor heated pool, pets for a fee.', seo_h1='Best Western Plus Des Moines West Inn & Suites, Clive', geo_summary='Best Western Plus Des Moines West Inn & Suites is a 64-room hotel at 1450 NW 118th St in Clive, near the I-80/I-35 interchange about seven miles west of downtown Des Moines. It suits interstate travellers and pet owners who want breakfast included and an indoor pool.', geo_key_facts=ARRAY['64 rooms on three floors at 1450 NW 118th St, Clive','Near the I-80 / I-35 interchange','About seven miles west of downtown Des Moines','About 15-18 minutes'' drive to Des Moines International Airport','Breakfast included; indoor heated pool and hot tub','Pets accepted for an additional fee (AAA)']::text[], geo_faq='[{"question":"How far is Best Western Plus Des Moines West from the airport?","answer":"About a 15 to 18 minute drive to Des Moines International Airport."},{"question":"Does Best Western Plus Des Moines West allow pets?","answer":"Yes. AAA lists pets as accepted for an additional fee."},{"question":"What time is check-in at Best Western Plus Des Moines West?","answer":"Check-in is at 3:00 PM and check-out is at 11:00 AM."}]'::jsonb, updated_at=now() WHERE id='0d7ed673-b915-44bb-889f-6ebcb75922d2';
UPDATE hotels SET description='Best Western Premier Ankeny Hotel is a four-story, 84-room hotel at 2502 SE Tones Dr in Ankeny, near I-35 at Exit 90. It opened in 2018. Outlets of Des Moines is about a 10 minute drive, and Adventureland and Prairie Meadows are about 12 minutes. Breakfast is included and self-parking is free, with an EV charging station on site. There is an indoor heated pool, a 24-hour fitness center, coin laundry, a business center and a meeting room of about 1,000 sq ft. Rooms have a refrigerator, microwave and LED TV. Pets are not allowed in guest rooms.', short_description='84-room Ankeny hotel off I-35 Exit 90, built 2018, with breakfast included, free parking, an indoor pool and EV charging.', seo_title='Best Western Premier Ankeny Hotel | Hotels in Ankeny, IA', seo_description='Best Western Premier Ankeny at 2502 SE Tones Dr off I-35 Exit 90: 84 rooms, breakfast included, free self-parking, EV charging and an indoor heated pool.', seo_h1='Best Western Premier Ankeny Hotel', geo_summary='Best Western Premier Ankeny Hotel is an 84-room hotel built in 2018 at 2502 SE Tones Dr, near I-35 Exit 90 in Ankeny. It suits drivers and families heading to Adventureland, Prairie Meadows or the Outlets of Des Moines who want breakfast, free parking and an EV charger.', geo_key_facts=ARRAY['84 rooms, four stories, built 2018','Near I-35 at Exit 90','About 10 minutes'' drive to Outlets of Des Moines','About 12 minutes'' drive to Adventureland and Prairie Meadows','Breakfast included, free self-parking, EV charging station','Pets not allowed in guest rooms (AAA)']::text[], geo_faq='[{"question":"How far is Best Western Premier Ankeny from Adventureland?","answer":"About a 12 minute drive, the same as to Prairie Meadows."},{"question":"Does Best Western Premier Ankeny allow pets?","answer":"No. AAA lists pets as not allowed in guest rooms."},{"question":"Does Best Western Premier Ankeny have EV charging?","answer":"Yes. There is an EV charging station, and self-parking is free."}]'::jsonb, updated_at=now() WHERE id='9167631c-1f6f-471f-bbcf-6b0fcaccfd98';
UPDATE hotels SET description='Comfort Inn & Suites Ames is an 82-room hotel at 603 S 16th St in Ames, next to the Coldwater Golf Links public course. Choice Hotels puts it less than 2 miles from Iowa State University and about 1 mile from Jack Trice Stadium, so it is a short drive on Cyclone game days. The hotel has an indoor heated pool, a fitness center and free WiFi, and Choice lists it as pet friendly. Check-in is at 3 PM and check-out at 11 AM.', short_description='82-room Ames hotel about 1 mile from Jack Trice Stadium, next to Coldwater Golf Links, with an indoor heated pool and free WiFi.', seo_title='Comfort Inn & Suites Ames | Hotels in Ames, IA', seo_description='Comfort Inn & Suites Ames at 603 S 16th St: 82 rooms about 1 mile from Jack Trice Stadium and under 2 miles from Iowa State, with an indoor pool and free WiFi.', seo_h1='Comfort Inn & Suites Ames', geo_summary='Comfort Inn & Suites Ames is an 82-room Choice hotel at 603 S 16th St, about 1 mile from Jack Trice Stadium and less than 2 miles from Iowa State University. It suits Iowa State visitors, game-day crowds and golfers, with an indoor heated pool and a pet-friendly listing.', geo_key_facts=ARRAY['82 rooms at 603 S 16th St, Ames','About 1 mile from Jack Trice Stadium (Choice Hotels)','Less than 2 miles from Iowa State University (Choice Hotels)','Next to Coldwater Golf Links public golf course','Indoor heated pool, fitness center, free WiFi','Check-in 3:00 PM, check-out 11:00 AM']::text[], geo_faq='[{"question":"How far is Comfort Inn & Suites Ames from Jack Trice Stadium?","answer":"Choice Hotels puts it about 1 mile from Jack Trice Stadium."},{"question":"Is Comfort Inn & Suites Ames pet friendly?","answer":"Choice Hotels lists it as pet friendly; check the hotel''s pet conditions when booking."},{"question":"Does Comfort Inn & Suites Ames have a pool?","answer":"Yes, an indoor heated pool."}]'::jsonb, updated_at=now() WHERE id='b93d0b9a-f504-4b62-a761-abc041977d77';
UPDATE hotels SET description='Comfort Inn & Suites Ankeny - Des Moines is a three-story, 67-room hotel at 215 NE Delaware Ave in Ankeny, off Interstate 35. Breakfast is included, WiFi is free and parking is on site. The hotel has an indoor heated pool, a fitness center, a business center and coin laundry. Rooms come with a coffeemaker, microwave and refrigerator. AAA lists pets as accepted for an additional fee. Check-in is at 3 PM and check-out at 11 AM.', short_description='67-room Ankeny hotel off I-35 at 215 NE Delaware Ave, with breakfast included, an indoor heated pool and pets accepted for a fee.', seo_title='Comfort Inn & Suites Ankeny | Hotels in Ankeny, IA', seo_description='Comfort Inn & Suites Ankeny - Des Moines at 215 NE Delaware Ave off I-35: 67 rooms, breakfast included, free WiFi, indoor heated pool and pets for a fee.', seo_h1='Comfort Inn & Suites Ankeny - Des Moines', geo_summary='Comfort Inn & Suites Ankeny - Des Moines is a 67-room Choice hotel at 215 NE Delaware Ave in Ankeny, off Interstate 35 north of Des Moines. It suits drivers and pet owners who want breakfast included, an indoor pool and in-room microwaves and refrigerators.', geo_key_facts=ARRAY['67 rooms, three stories (AAA)','Address: 215 NE Delaware Ave, Ankeny, near Interstate 35','Breakfast included; free WiFi; on-site parking','Indoor heated pool, fitness center, coin laundry','Pets accepted for an additional fee (AAA)','Check-in 3:00 PM, check-out 11:00 AM']::text[], geo_faq='[{"question":"Does Comfort Inn & Suites Ankeny allow pets?","answer":"AAA lists pets as accepted for an additional fee."},{"question":"Is breakfast included at Comfort Inn & Suites Ankeny?","answer":"Yes. AAA lists breakfast as included."},{"question":"What time is check-in at Comfort Inn & Suites Ankeny?","answer":"Check-in is at 3:00 PM and check-out is at 11:00 AM."}]'::jsonb, updated_at=now() WHERE id='b4b92ed3-d775-4ad5-b855-1a0575790c88';
UPDATE hotels SET description='Comfort Inn & Suites Event Center is a seven-story, 155-room hotel at 929 3rd St in downtown Des Moines, off I-235 at the 3rd St exit. It sits on the same street as the Iowa Events Center (730 3rd St), and AAA notes the events center is within walking distance. Breakfast is free and there is on-site parking, an indoor heated pool, an exercise room and wireless internet. Rooms have a coffeemaker, microwave, refrigerator and in-room safe. Pets are welcome for an added fee. Check-in is 3 PM, check-out 11 AM.', short_description='155-room downtown hotel at 929 3rd St, off I-235, within walking distance of the Iowa Events Center, with free breakfast and a pool.', seo_title='Comfort Inn & Suites Event Center | Hotels in Des Moines', seo_description='Comfort Inn & Suites Event Center at 929 3rd St, downtown Des Moines: 155 rooms off I-235, walkable to the events center, free breakfast and an indoor pool.', seo_h1='Comfort Inn & Suites Event Center, Des Moines', geo_summary='Comfort Inn & Suites Event Center is a 155-room hotel at 929 3rd St in downtown Des Moines, off I-235 at the 3rd St exit and up the street from the Iowa Events Center. It suits people attending games, concerts or conventions downtown who want free breakfast, on-site parking and an indoor pool.', geo_key_facts=ARRAY['155 rooms on seven floors (AAA)','Address: 929 3rd St, downtown Des Moines, off I-235 at the 3rd St exit','Same street as the Iowa Events Center at 730 3rd St; walkable per AAA','Free breakfast, on-site parking, indoor heated pool','Pets welcome for an added fee','Check-in 3:00 PM, check-out 11:00 AM']::text[], geo_faq='[{"question":"Can you walk from Comfort Inn & Suites Event Center to the Iowa Events Center?","answer":"Yes. AAA notes the hotel is within walking distance of the events center; both are on 3rd St (929 and 730 3rd St)."},{"question":"Does Comfort Inn & Suites Event Center allow pets?","answer":"Yes, for an added fee, per AAA."},{"question":"Is breakfast free at Comfort Inn & Suites Event Center?","answer":"Yes. AAA lists a free breakfast."}]'::jsonb, updated_at=now() WHERE id='25ba2eea-1dbf-4e00-8b5a-ad907e3772a5';
UPDATE hotels SET description='Comfort Inn & Suites West Des Moines is an 82-room hotel at 1625 Jordan Creek Pkwy, about a 3 minute drive from Jordan Creek Town Center and about 7 minutes from Living History Farms. Des Moines International Airport is roughly 19 to 25 minutes by car. Breakfast, WiFi and self parking are free, and there is an EV charging station on site. The hotel has an indoor pool, a 24-hour fitness center, a convenience shop and laundry facilities. Check-in is at 3 PM and check-out at 11 AM.', short_description='82-room hotel on Jordan Creek Pkwy, 3 minutes from Jordan Creek Town Center, with free breakfast, free parking and EV charging.', seo_title='Comfort Inn & Suites West Des Moines | Hotels in WDM, IA', seo_description='Comfort Inn & Suites at 1625 Jordan Creek Pkwy: 82 rooms about 3 minutes from Jordan Creek Town Center, free breakfast and parking, indoor pool, EV charging.', seo_h1='Comfort Inn & Suites West Des Moines', geo_summary='Comfort Inn & Suites West Des Moines is an 82-room Choice hotel at 1625 Jordan Creek Pkwy, about a 3 minute drive from Jordan Creek Town Center. It suits shoppers and west-metro visitors who want free breakfast, free parking and EV charging.', geo_key_facts=ARRAY['82 rooms at 1625 Jordan Creek Pkwy, West Des Moines','About 3 minutes'' drive from Jordan Creek Town Center','About 7 minutes from Living History Farms','Roughly 19-25 minutes by car from Des Moines International Airport','Free breakfast, free self parking, free WiFi, EV charging','Check-in 3:00 PM, check-out 11:00 AM']::text[], geo_faq='[{"question":"How far is Comfort Inn & Suites West Des Moines from Jordan Creek Town Center?","answer":"About a 3 minute drive."},{"question":"Is parking free at Comfort Inn & Suites West Des Moines?","answer":"Yes. Self parking is free, and there is an EV charging station."},{"question":"How long is the drive to the Des Moines airport?","answer":"Roughly 19 to 25 minutes by car to Des Moines International Airport."}]'::jsonb, updated_at=now() WHERE id='f813a4bc-ebc5-43ed-802f-4dbc4eb1637f';
UPDATE hotels SET description='Country Inn & Suites by Radisson, Ankeny is at 2510 SE Tones Dr in Ankeny, about 15 miles from Des Moines International Airport. Adventureland Park is 8 miles away and the Science Center of Iowa is about a 15 minute drive, per Priceline. A daily hot breakfast with eggs, fruit and bagels is included, and parking and Wi-Fi are free. There is an indoor pool, a hot tub and a fitness center. Rooms are non-smoking, and pets are not allowed. Check-in is after 3 PM and check-out before noon.', short_description='Ankeny hotel at 2510 SE Tones Dr, 8 miles from Adventureland, with free hot breakfast, free parking and an indoor pool. No pets.', seo_title='Country Inn & Suites Ankeny | Hotels in Ankeny, IA', seo_description='Country Inn & Suites by Radisson at 2510 SE Tones Dr, Ankeny: free hot breakfast, free parking and Wi-Fi, indoor pool and hot tub, 8 miles from Adventureland.', seo_h1='Country Inn & Suites by Radisson, Ankeny, IA', geo_summary='Country Inn & Suites by Radisson, Ankeny is a hotel at 2510 SE Tones Dr in Ankeny, 8 miles from Adventureland Park and about 15 miles from Des Moines International Airport. It suits families and drivers without pets who want a free hot breakfast, free parking and an indoor pool.', geo_key_facts=ARRAY['Address: 2510 SE Tones Dr, Ankeny','8 miles from Adventureland Park; 15 miles from Des Moines International Airport (Priceline)','Free daily hot breakfast, free parking, free Wi-Fi','Indoor pool, hot tub and fitness center','Pets are not allowed','Check-in after 3:00 PM, check-out before 12:00 PM']::text[], geo_faq='[{"question":"How far is Country Inn & Suites Ankeny from Adventureland?","answer":"Priceline lists Adventureland Park as 8 miles away."},{"question":"Does Country Inn & Suites Ankeny allow pets?","answer":"No. Pets are not allowed."},{"question":"Is breakfast free at Country Inn & Suites Ankeny?","answer":"Yes. A daily hot breakfast with eggs, fruit and bagels is included."}]'::jsonb, updated_at=now() WHERE id='61bf164c-0ecb-42b2-8c0f-3d040930d8a2';
UPDATE hotels SET description='La Quinta by Wyndham Altoona Des Moines is an 80-room, four-floor hotel at 1785 11th Street NW in Altoona, less than a mile from Adventureland and 17 miles from Des Moines International Airport. It opened in 2019. Rooms are non-smoking and come with a mini-refrigerator, microwave, coffee maker and flat-screen TV. The free Bright Side Breakfast, free parking, a heated indoor pool, a 24/7 gym and guest laundry are included, and the lobby bar and lounge is open daily from 5 p.m. to 1 a.m. A 500 sq ft meeting room holds up to 12 people.', short_description='80-room Altoona hotel under a mile from Adventureland, with free breakfast, indoor pool and a lobby bar.', seo_title='La Quinta Altoona Des Moines | Hotels in Altoona, IA', seo_description='La Quinta by Wyndham Altoona: 80 rooms under a mile from Adventureland, free breakfast and parking, heated indoor pool, and a lobby bar open until 1 a.m.', seo_h1='La Quinta by Wyndham Altoona Des Moines', geo_summary='La Quinta by Wyndham Altoona Des Moines is an 80-room hotel on the east side of the metro, less than a mile from Adventureland. It suits families headed to the park and drivers who want free breakfast, free parking and an indoor pool.', geo_key_facts=ARRAY['80 rooms on four floors, opened 2019','Less than 1 mile from Adventureland','17 miles from Des Moines International Airport','Free Bright Side Breakfast and free parking','Lobby bar open daily 5 p.m. to 1 a.m.','Check-in 3:00 PM, check-out 11:00 AM']::text[], geo_faq='[{"question":"How far is La Quinta Altoona from Adventureland?","answer":"Wyndham lists it as less than 1 mile from Adventureland."},{"question":"Is breakfast included?","answer":"Yes. The free Bright Side Breakfast is included, and parking is free."},{"question":"What are check-in and check-out times?","answer":"Check-in is 3:00 PM and check-out is 11:00 AM."}]'::jsonb, updated_at=now() WHERE id='5b77fdfd-e662-4968-ae51-3ff38fd6d451';
UPDATE hotels SET description='La Quinta Inn & Suites Ankeny is at 2402 SE Tones Dr in Ankeny, about one mile from Ankeny Regional Airport and 16 miles from Des Moines International Airport, according to Wyndham. Rooms have a mini-refrigerator, microwave, coffee maker, flat-screen TV and desk. Guests get the free Bright Side Breakfast, free WiFi and free parking, plus a heated indoor pool, fitness center, business center and the Bright Side Market for snacks. The front desk is staffed around the clock.', short_description='Ankeny hotel on SE Tones Dr with free breakfast, WiFi and parking, a heated indoor pool and a 24/7 front desk.', seo_title='La Quinta Inn & Suites Ankeny | Hotels in Ankeny, IA', seo_description='La Quinta Inn & Suites Ankeny on SE Tones Dr: free Bright Side Breakfast, WiFi and parking, heated indoor pool, fitness center, 16 miles from DSM airport.', seo_h1='La Quinta Inn & Suites by Wyndham Ankeny IA / Des Moines IA', geo_summary='La Quinta Inn & Suites Ankeny is a Wyndham-brand hotel on SE Tones Dr in Ankeny, north of Des Moines. It fits travelers who want free breakfast and parking, an indoor pool and in-room fridges and microwaves.', geo_key_facts=ARRAY['2402 SE Tones Dr, Ankeny','About 1 mile from Ankeny Regional Airport','16 miles from Des Moines International Airport','Free Bright Side Breakfast, WiFi and parking','Heated indoor pool and fitness center','24/7 front desk']::text[], geo_faq='[{"question":"Does La Quinta Ankeny serve breakfast?","answer":"Yes. Wyndham lists a free Bright Side Breakfast."},{"question":"Is parking free?","answer":"Yes, Wyndham lists free parking."},{"question":"How far is it from Des Moines International Airport?","answer":"Wyndham puts it 16 miles from Des Moines International Airport."}]'::jsonb, updated_at=now() WHERE id='0f0368b2-1d22-477e-a47e-4b075fc90d4e';
UPDATE hotels SET description='La Quinta Inn & Suites by Wyndham Clive is a 96-room hotel at 1390 NW 118th St in Clive, about 10 miles from downtown Des Moines and a short drive from Des Moines International Airport. The free Bright Side Breakfast, free WiFi and free parking are included. There is an indoor pool and hot tub, a fitness center, laundry facilities and business services, and a 406 sq ft meeting room for up to 25 people. All rooms are non-smoking. Check-in is 3:00 PM and check-out 11:00 AM.', short_description='96-room Clive hotel about 10 miles from downtown Des Moines, with free breakfast, indoor pool and hot tub.', seo_title='La Quinta Inn & Suites Clive | Hotels in Clive, IA', seo_description='La Quinta Inn & Suites Clive: 96 non-smoking rooms on NW 118th St, about 10 miles from downtown Des Moines, with free breakfast, parking and an indoor pool.', seo_h1='La Quinta Inn & Suites by Wyndham Clive', geo_summary='La Quinta Inn & Suites by Wyndham Clive is a 96-room hotel in the western suburb of Clive, about 10 miles from downtown Des Moines. It suits business travelers and families who want free breakfast, free parking and a pool.', geo_key_facts=ARRAY['96 rooms, all non-smoking','About 10 miles from downtown Des Moines','Free Bright Side Breakfast, WiFi and parking','Indoor pool and hot tub','406 sq ft meeting room for up to 25','Check-in 3:00 PM, check-out 11:00 AM']::text[], geo_faq='[{"question":"How far is La Quinta Clive from downtown Des Moines?","answer":"Wyndham says it is about 10 miles from downtown Des Moines."},{"question":"Is there a pool?","answer":"Yes, an indoor pool and hot tub."},{"question":"What time is check-in?","answer":"Check-in is 3:00 PM and check-out is 11:00 AM."}]'::jsonb, updated_at=now() WHERE id='f2a6890e-11e9-479c-9074-b16cdf59afe6';
UPDATE hotels SET description='La Quinta Inn & Suites by Wyndham Johnston sits at 6215 Merle Hay Road, off I-35 and I-80, within walking distance of Johnston Town Center and 13 miles from Des Moines International Airport. Corteva and John Deere Financial are minutes away. Guests get the free Bright Side Breakfast, free WiFi and free parking, a heated indoor pool and hot tub, a 24/7 fitness center, an outdoor patio and laundry. Extended-stay suites have kitchenettes, EV charging is free for the first four hours, and an 875 sq ft meeting room holds up to 30.', short_description='Johnston hotel on Merle Hay Road near Johnston Town Center, with free breakfast, indoor pool and kitchenette suites.', seo_title='La Quinta Inn & Suites Johnston | Hotels in Johnston, IA', seo_description='La Quinta Johnston on Merle Hay Road, off I-35/I-80 near Johnston Town Center: free breakfast and parking, indoor pool, kitchenette suites, EV charging.', seo_h1='La Quinta Inn & Suites by Wyndham Johnston', geo_summary='La Quinta Inn & Suites by Wyndham Johnston is a hotel on Merle Hay Road in Johnston, off I-35 and I-80 and walkable to Johnston Town Center. It suits business travelers visiting Corteva or John Deere Financial and longer stays that need a kitchenette.', geo_key_facts=ARRAY['6215 Merle Hay Road, off I-35 and I-80','Walking distance to Johnston Town Center','13 miles from Des Moines International Airport','Free Bright Side Breakfast, WiFi and parking','Heated indoor pool, hot tub, 24/7 fitness center','EV charging free for the first four hours']::text[], geo_faq='[{"question":"Does La Quinta Johnston have rooms with kitchens?","answer":"Wyndham lists extended-stay suites with kitchenettes."},{"question":"Is it pet-friendly?","answer":"Wyndham describes the hotel as pet-friendly; ask the hotel about fees and limits."},{"question":"How far is it from the Des Moines airport?","answer":"Wyndham puts it 13 miles from Des Moines International Airport."}]'::jsonb, updated_at=now() WHERE id='52c99877-7d8f-468e-a9bc-2fa8ed6a5c2e';
UPDATE hotels SET description='MainStay Suites Waukee-West Des Moines is an extended-stay hotel at 2885 Grand Prairie Parkway, Building B, in Waukee. Choice Hotels describes it as apartment-style, with a kitchen, desk and sitting area in each suite, and offers weekly rates. Breakfast is free, and there is an indoor pool, self-service laundry, an elevator and free on-site parking. The hotel is pet-friendly. Check-in is 3:00 PM and check-out 11:00 AM.', short_description='Extended-stay suites with kitchens on Grand Prairie Parkway in Waukee, with free breakfast, indoor pool and laundry.', seo_title='MainStay Suites Waukee-West Des Moines | Waukee, IA', seo_description='MainStay Suites Waukee on Grand Prairie Parkway: extended-stay suites with kitchens, free breakfast and parking, indoor pool, guest laundry, pet-friendly.', seo_h1='MainStay Suites Waukee-West Des Moines', geo_summary='MainStay Suites Waukee-West Des Moines is a Choice Hotels extended-stay property on Grand Prairie Parkway in Waukee. It is set up for longer stays, with a kitchen in every suite, weekly rates and on-site laundry.', geo_key_facts=ARRAY['2885 Grand Prairie Parkway, Building B, Waukee','Extended stay: every suite has a kitchen','Free breakfast and free on-site parking','Indoor pool and self-service laundry','Pet-friendly','Check-in 3:00 PM, check-out 11:00 AM']::text[], geo_faq='[{"question":"Do the suites have kitchens?","answer":"Yes. Choice Hotels says each suite has a kitchen, a desk and a sitting area."},{"question":"Does MainStay Suites Waukee allow pets?","answer":"Yes, it is listed as pet-friendly; ask the hotel about fees."},{"question":"What are check-in and check-out times?","answer":"Check-in is 3:00 PM and check-out is 11:00 AM."}]'::jsonb, updated_at=now() WHERE id='3408622c-8ab2-4cc3-9776-68741c309ce8';
UPDATE hotels SET description='Microtel Inn & Suites by Wyndham Urbandale/Des Moines is a 100% non-smoking hotel at 8711 Plum Drive in Urbandale. Wyndham puts it about 10 minutes from Living History Farms, about 20 minutes from downtown Des Moines and about 25 minutes from Des Moines International Airport, with Adventureland nearby. A free continental breakfast is served every morning, and there is an on-site fitness center, elevators, express checkout and free WiFi for Wyndham Rewards members. Two meeting rooms seat up to 40.', short_description='Non-smoking Urbandale hotel on Plum Drive, about 10 minutes from Living History Farms, with free continental breakfast.', seo_title='Microtel Inn & Suites Urbandale | Hotels in Urbandale, IA', seo_description='Microtel Inn & Suites Urbandale on Plum Drive: free continental breakfast, fitness center, non-smoking rooms, about 10 minutes from Living History Farms.', seo_h1='Microtel Inn & Suites by Wyndham Urbandale/Des Moines', geo_summary='Microtel Inn & Suites by Wyndham Urbandale/Des Moines is a non-smoking hotel on Plum Drive in Urbandale, northwest of Des Moines. It suits budget-minded travelers who want free breakfast and quick access to Living History Farms.', geo_key_facts=ARRAY['8711 Plum Drive, Urbandale','100% non-smoking','Free continental breakfast daily','About 10 minutes from Living History Farms','About 25 minutes from Des Moines International Airport','Two meeting rooms seating up to 40']::text[], geo_faq='[{"question":"Is breakfast included at Microtel Urbandale?","answer":"Yes, Wyndham lists a free continental breakfast every morning."},{"question":"How far is it from Living History Farms?","answer":"Wyndham says about 10 minutes."},{"question":"Is the hotel pet-friendly?","answer":"Wyndham describes it as pet-friendly and says additional charges may apply."}]'::jsonb, updated_at=now() WHERE id='83c01f1f-c408-4456-8d27-c458b510d4f1';
UPDATE hotels SET description='Motel 6 Altoona, IA - Des Moines East is at 3225 Adventureland Dr, about 0.4 km from Adventureland Park and 0.9 km from Prairie Meadows Racetrack and Casino; the Iowa State Fairgrounds are about 15 minutes away. Rooms open from interior halls. There is an indoor pool, free WiFi, free parking, coin-op laundry, a vending area and free morning coffee in the lobby, and the casino runs a free shuttle on its own schedule. Pets are allowed on request. Check-in is after 3:00 PM and check-out before 11:00 AM.', short_description='Budget motel on Adventureland Dr in Altoona, about 0.4 km from Adventureland Park, with an indoor pool.', seo_title='Motel 6 Altoona Des Moines East | Hotels in Altoona, IA', seo_description='Motel 6 Altoona on Adventureland Dr, about 0.4 km from Adventureland and near Prairie Meadows: indoor pool, free WiFi and parking, pets on request.', seo_h1='Motel 6 Altoona, IA - Des Moines East', geo_summary='Motel 6 Altoona, IA - Des Moines East is a budget motel on Adventureland Drive, next to Adventureland and close to Prairie Meadows. It fits travelers who want a low-cost base for the park or the casino with an indoor pool and free parking.', geo_key_facts=ARRAY['3225 Adventureland Dr, Altoona','About 0.4 km from Adventureland Park','About 0.9 km from Prairie Meadows Racetrack and Casino','Indoor pool, free WiFi and free parking','Free casino shuttle run by Prairie Meadows','Check-in after 3:00 PM, check-out before 11:00 AM']::text[], geo_faq='[{"question":"How close is Motel 6 Altoona to Adventureland?","answer":"Kayak lists Adventureland Park about 0.4 km away."},{"question":"Is there a shuttle to Prairie Meadows?","answer":"The casino offers a free shuttle on its own schedule."},{"question":"Are pets allowed?","answer":"Pets are allowed on request, and charges may apply."}]'::jsonb, updated_at=now() WHERE id='46b8ffe4-929b-4b0c-903f-05cfe57f8f12';
UPDATE hotels SET description='Motel 6 Des Moines, IA - North is a budget motel at 4940 NE 14th St on the north side of Des Moines, about 6.6 km from the Iowa State Capitol and 7.5 km from the city center. Adventureland Park and the Des Moines Botanical Center are within 5 miles. Free WiFi and free parking are included, and there are laundry facilities, a 24-hour front desk and an outdoor pool open May to September. Pets are allowed on request. Check-out is before 11:00 AM.', short_description='Budget motel on NE 14th St in north Des Moines, about 6.6 km from the Capitol, with free WiFi and parking.', seo_title='Motel 6 Des Moines North | Hotels in Des Moines, IA', seo_description='Motel 6 Des Moines North on NE 14th St: free WiFi and parking, laundry, 24-hour desk, seasonal outdoor pool, about 6.6 km from the Iowa State Capitol.', seo_h1='Motel 6 Des Moines, IA - North', geo_summary='Motel 6 Des Moines, IA - North is a budget motel on NE 14th Street on the city''s north side. It suits drivers who want a low-cost room with free parking and WiFi a short drive from the Iowa State Capitol and Adventureland.', geo_key_facts=ARRAY['4940 NE 14th St, Des Moines','About 6.6 km from the Iowa State Capitol','About 13.2 km from Des Moines International Airport','Free WiFi and free parking','Outdoor pool open May to September','24-hour front desk']::text[], geo_faq='[{"question":"Does Motel 6 Des Moines North have a pool?","answer":"Kayak lists an outdoor pool open May to September."},{"question":"Is parking free?","answer":"Yes, free parking and free WiFi are listed."},{"question":"Are pets allowed?","answer":"Pets are allowed on request, and charges may apply."}]'::jsonb, updated_at=now() WHERE id='2560b6c2-cf59-4bf4-81f0-68a275e3a924';
UPDATE hotels SET description='Motel 6 West Des Moines, IA is a 121-room budget motel at 7655 Office Plaza Drive North in West Des Moines, about 13.9 km from Des Moines International Airport and 8.8 km from Valley Junction. Free WiFi and free parking are included, and there are laundry facilities and an outdoor pool. Pets are allowed on request, and charges may apply. Check-in is after 3:00 PM and check-out before 11:00 AM.', short_description='121-room budget motel on Office Plaza Drive North in West Des Moines, with free WiFi, parking and an outdoor pool.', seo_title='Motel 6 West Des Moines | Hotels in West Des Moines, IA', seo_description='Motel 6 West Des Moines on Office Plaza Drive North: 121 rooms, free WiFi and parking, laundry, outdoor pool, about 13.9 km from the Des Moines airport.', seo_h1='Motel 6 West Des Moines, IA', geo_summary='Motel 6 West Des Moines, IA is a 121-room budget motel on Office Plaza Drive North in West Des Moines. It suits travelers who want a basic room with free parking on the west side of the metro.', geo_key_facts=ARRAY['121 rooms','7655 Office Plaza Drive North, West Des Moines','About 13.9 km from Des Moines International Airport','About 8.8 km from Valley Junction','Free WiFi and free parking','Check-in after 3:00 PM, check-out before 11:00 AM']::text[], geo_faq='[{"question":"What time is check-in at Motel 6 West Des Moines?","answer":"Check-in is after 3:00 PM and check-out before 11:00 AM."},{"question":"Is parking free?","answer":"Yes, Kayak lists free parking and free WiFi."},{"question":"Are pets allowed?","answer":"Pets are allowed on request, and charges may apply."}]'::jsonb, updated_at=now() WHERE id='c03e7480-bb69-4230-a3a7-430f6f450dcc';
UPDATE hotels SET description='My Place Hotel-Altoona/Des Moines is a 64-room extended-stay hotel at 2315 Adventureland Dr, across the street from Adventureland Resort and 0.3 miles from Prairie Meadows Casino. The Outlets of Des Moines are 1.3 miles away and the Iowa State Capitol 7.5 miles. Every room has a kitchen with a full-size refrigerator/freezer, two-burner cooktop, microwave, toaster and coffee machine. WiFi and on-site parking are free, and laundry is open 24 hours. Up to two dogs are allowed per room for a fee.', short_description='64-room extended-stay hotel across from Adventureland in Altoona, with in-room kitchens and 24-hour laundry.', seo_title='My Place Hotel Altoona/Des Moines | Hotels in Altoona, IA', seo_description='My Place Hotel Altoona: extended-stay rooms with kitchens across from Adventureland, 0.3 mi from Prairie Meadows, free WiFi and parking, dog-friendly.', seo_h1='My Place Hotel-Altoona/Des Moines, IA', geo_summary='My Place Hotel-Altoona/Des Moines is a 64-room extended-stay hotel on Adventureland Drive in Altoona, across the street from Adventureland. It suits longer stays and families who want a kitchen in the room and a short walk to the park.', geo_key_facts=ARRAY['64 rooms, extended stay','Across the street from Adventureland Resort (0.3 mi)','0.3 miles from Prairie Meadows Casino','In-room kitchen with full-size fridge and two-burner cooktop','Up to two dogs per room, fee applies','Check-in 3:00 PM, check-out 11:00 AM']::text[], geo_faq='[{"question":"How far is My Place Altoona from Adventureland?","answer":"The hotel says Adventureland Resort is 0.3 miles away, across the street."},{"question":"Are dogs allowed?","answer":"Yes, up to two dogs per room. The hotel lists a fee of $25 per night, $100 per week or $200 per month, subject to change."},{"question":"Do rooms have kitchens?","answer":"Yes, with a full-size refrigerator/freezer, two-burner cooktop, microwave, toaster and coffee machine."}]'::jsonb, updated_at=now() WHERE id='4017f64a-4883-4824-8762-271b762bfe7e';
UPDATE hotels SET description='My Place Hotel-Ankeny/Des Moines is an extended-stay hotel at 2506 SE Tones Dr in Ankeny, 1.9 miles from the Iowa Culinary Institute and 7.6 miles from the Iowa State Fairgrounds. Each room has a kitchen with a full-size refrigerator/freezer, two-burner cooktop, microwave, toaster and coffee maker. WiFi and parking are free, including truck parking, laundry is open 24 hours, and a 24-hour My Store sells grab-and-go breakfast. The front desk is staffed around the clock. Up to two dogs are allowed per room for a fee.', short_description='Extended-stay hotel on SE Tones Dr in Ankeny with in-room kitchens, free truck parking and 24-hour laundry.', seo_title='My Place Hotel Ankeny/Des Moines | Hotels in Ankeny, IA', seo_description='My Place Hotel Ankeny on SE Tones Dr: extended-stay rooms with kitchens, free WiFi and truck parking, 24-hour laundry, dog-friendly, near the fairgrounds.', seo_h1='My Place Hotel-Ankeny/Des Moines, IA', geo_summary='My Place Hotel-Ankeny/Des Moines is an extended-stay hotel on SE Tones Drive in Ankeny, north of Des Moines. It suits long-stay workers and travelers with dogs who want a kitchen, free truck parking and laundry on site.', geo_key_facts=ARRAY['2506 SE Tones Dr, Ankeny','In-room kitchen with full-size fridge and two-burner cooktop','Free WiFi and free parking, including trucks','24-hour laundry and 24-hour front desk','7.6 miles from the Iowa State Fairgrounds','Check-in 3:00 PM, check-out 11:00 AM']::text[], geo_faq='[{"question":"Is there truck parking at My Place Ankeny?","answer":"Yes, the hotel lists free parking including truck parking."},{"question":"Are dogs allowed?","answer":"Yes, up to two dogs per room. The listed fee is $25 per night, $100 per week or $200 per month, subject to change."},{"question":"How far is it from the Iowa State Fairgrounds?","answer":"The hotel lists the fairgrounds 7.6 miles away."}]'::jsonb, updated_at=now() WHERE id='69226739-7fa9-4fea-a0c9-8e27c5d98139';
UPDATE hotels SET description='Prairie Meadows Casino, Racetrack & Hotel is a 168-room hotel at the casino and racetrack at I-80 exit 142 in Altoona. The casino opened in 1995 and the property also has a sportsbook, live racing and an event center. Dining on site includes AJ''s Steakhouse, The Paddock Grill, Cafe at the Meadows and Champions. Hotel guests get a saltwater pool, fitness center and hotel lounge, and rooms have an in-room safe, coffee maker, refrigerator and DirecTV. Tesla and universal EV chargers are on site. Check-in is 3:00 PM, check-out 11:00 AM.', short_description='168-room hotel at the Prairie Meadows casino and racetrack, I-80 exit 142 in Altoona, with a saltwater pool.', seo_title='Prairie Meadows Hotel | Casino Hotel in Altoona, IA', seo_description='Prairie Meadows Casino, Racetrack & Hotel at I-80 exit 142 in Altoona: 168 rooms, saltwater pool, AJ''s Steakhouse, sportsbook, live racing, EV charging.', seo_h1='Prairie Meadows Casino, Racetrack & Hotel, Altoona', geo_summary='Prairie Meadows Casino, Racetrack & Hotel is a 168-room hotel at the casino and racetrack off I-80 in Altoona. It is for guests who want to stay where they gamble, bet the races or eat at AJ''s Steakhouse.', geo_key_facts=ARRAY['168 rooms','I-80 at exit 142, Altoona','Casino opened April 1, 1995; sportsbook and live racing','Dining: AJ''s Steakhouse, The Paddock Grill, Cafe at the Meadows, Champions','Saltwater pool and fitness center','Tesla and universal EV charging']::text[], geo_faq='[{"question":"Where is the Prairie Meadows hotel?","answer":"At 1 Prairie Meadows Dr in Altoona, on Interstate 80 at exit 142."},{"question":"Is there a pool?","answer":"Yes, a saltwater pool, plus a fitness center."},{"question":"What are check-in and check-out times?","answer":"Check-in is 3:00 PM and check-out is 11:00 AM."}]'::jsonb, updated_at=now() WHERE id='14b8d555-9082-43af-a065-f06cc2f40d50';
UPDATE hotels SET description='Quality Inn & Suites Altoona is a smoke-free hotel at 2701 Adventureland Dr near I-80 exit 142B, close to Prairie Meadows and Adventureland. A free hot breakfast and free WiFi are included. The hotel has an indoor pool, fitness center, business center and guest laundry. Choice Hotels lists it as pet friendly. Check-in is 3:00 PM and check-out 11:00 AM.', short_description='Smoke-free hotel on Adventureland Dr near I-80 exit 142B, with free hot breakfast and an indoor pool.', seo_title='Quality Inn & Suites Altoona | Hotels in Altoona, IA', seo_description='Quality Inn & Suites Altoona on Adventureland Dr near I-80 exit 142B: free hot breakfast and WiFi, indoor pool, pet friendly, near Prairie Meadows.', seo_h1='Quality Inn & Suites Altoona', geo_summary='Quality Inn & Suites Altoona is a smoke-free Choice Hotels property on Adventureland Drive, near I-80 exit 142B. It suits families visiting Adventureland and guests at Prairie Meadows who want free hot breakfast and a pool.', geo_key_facts=ARRAY['2701 Adventureland Dr, Altoona','Near I-80 exit 142B','Near Prairie Meadows and Adventureland','Free hot breakfast and free WiFi','Indoor pool and fitness center','Check-in 3:00 PM, check-out 11:00 AM']::text[], geo_faq='[{"question":"Does Quality Inn Altoona serve breakfast?","answer":"Yes, a free hot breakfast."},{"question":"Is it pet friendly?","answer":"Choice Hotels lists it as pet friendly; Expedia lists a fee of USD 25 per pet."},{"question":"What are check-in and check-out times?","answer":"Check-in is 3:00 PM and check-out is 11:00 AM."}]'::jsonb, updated_at=now() WHERE id='61ef6888-f6b2-4994-86ed-3bde8bb8d5fb';
UPDATE hotels SET description='Quality Inn & Suites Ankeny-Des Moines is a 57-unit, three-story hotel at 201 SE Delaware Ave in Ankeny, near I-35 exit 92. Rooms open onto interior corridors. Breakfast is included, and the hotel has an indoor heated pool, exercise room, business center, coin laundry, wireless internet and on-site parking. Pets are not accepted in guest rooms. Check-in is 3:00 PM and check-out 11:00 AM.', short_description='57-unit Ankeny hotel near I-35 exit 92, with breakfast included, an indoor heated pool and coin laundry.', seo_title='Quality Inn & Suites Ankeny-Des Moines | Ankeny, IA', seo_description='Quality Inn & Suites Ankeny on SE Delaware Ave near I-35 exit 92: 57 units, breakfast included, indoor heated pool, exercise room and coin laundry.', seo_h1='Quality Inn & Suites Ankeny-Des Moines', geo_summary='Quality Inn & Suites Ankeny-Des Moines is a 57-unit Choice Hotels property on SE Delaware Avenue in Ankeny, near I-35 exit 92. It suits drivers on I-35 who want breakfast, a heated pool and laundry, but not guests traveling with pets.', geo_key_facts=ARRAY['57 units on three stories, interior corridors','201 SE Delaware Ave, near I-35 exit 92','Breakfast included','Indoor heated pool and exercise room','Pets not accepted in guest rooms','Check-in 3:00 PM, check-out 11:00 AM']::text[], geo_faq='[{"question":"Does Quality Inn Ankeny allow pets?","answer":"No. AAA lists pets as not accepted in guest rooms."},{"question":"Is breakfast included?","answer":"Yes, AAA lists breakfast as included."},{"question":"Is there a pool?","answer":"Yes, an indoor heated pool."}]'::jsonb, updated_at=now() WHERE id='13e4d2f3-b654-4612-83f0-92ef234ef005';
UPDATE hotels SET description='Surety Hotel is a 137-room boutique hotel at 206 6th Ave in downtown Des Moines, inside the restored 1913 Hippee Building, once the city''s tallest. It opened in November 2020 under Aparium Hotel Group and is now part of Marriott''s Autograph Collection. The original 12-story staircase and mail chute survive. Mulberry Street Tavern opens onto a 2,220 sq ft courtyard with an outdoor fireplace, and there is a lobby coffee bar, Sixth & Mulberry, a solarium and a fitness center. The Court Avenue district is steps away and DSM airport is about 4.8 miles.', short_description='137-room boutique hotel in the 1913 Hippee Building downtown, with Mulberry Street Tavern and a courtyard patio bar.', seo_title='Surety Hotel | Boutique Hotel in Downtown Des Moines, IA', seo_description='Surety Hotel fills the restored 1913 Hippee Building at 206 6th Ave in downtown Des Moines: 137 rooms, Mulberry Street Tavern and a courtyard bar.', seo_h1='Surety Hotel, Autograph Collection in Des Moines', geo_summary='Surety Hotel is a 137-room Autograph Collection boutique hotel in the restored 1913 Hippee Building in downtown Des Moines. It suits visitors who want to stay steps from the Court Avenue district in a historic building with its own tavern and courtyard bar.', geo_key_facts=ARRAY['137 rooms at 206 6th Ave, downtown Des Moines','In the 1913 Hippee Building, once the tallest building in Des Moines','Opened November 11, 2020; part of Marriott''s Autograph Collection','Check-in 3:00 PM, check-out 11:00 AM','About 4.8 miles from Des Moines International Airport','Dog-friendly through its ''Pack Your Pup'' program']::text[], geo_faq='[{"question":"What are check-in and check-out times at Surety Hotel?","answer":"Check-in is 3:00 PM and check-out is 11:00 AM."},{"question":"Does Surety Hotel allow dogs?","answer":"Yes. The hotel runs a ''Pack Your Pup'' program for guests bringing dogs. Fees are not listed in our sources, so ask the hotel."},{"question":"How far is Surety Hotel from the Des Moines airport?","answer":"About 4.8 miles from Des Moines International Airport, and steps from the Court Avenue entertainment district."}]'::jsonb, updated_at=now() WHERE id='9c086576-123e-4309-8b75-a5526ceb58bb';
UPDATE hotels SET description='The Rewind is a boutique hotel at 6075 Mills Civic Parkway in West Des Moines, part of Hilton''s Tapestry Collection brand. It is a west-metro address rather than a downtown Des Moines one. Reservations go through the hotel''s page on hilton.com, which is also where to confirm room types, check-in and check-out times, parking, dining and pet rules before you book; we could not verify those details for this listing, so we have left them out rather than guess.', short_description='Boutique Tapestry Collection by Hilton hotel at 6075 Mills Civic Parkway in West Des Moines.', seo_title='The Rewind West Des Moines | Hotels in West Des Moines, IA', seo_description='The Rewind is a Tapestry Collection by Hilton boutique hotel at 6075 Mills Civic Parkway in West Des Moines, Iowa. Book and check details at hilton.com.', seo_h1='The Rewind West Des Moines, Tapestry Collection by Hilton', geo_summary='The Rewind is a boutique hotel in Hilton''s Tapestry Collection at 6075 Mills Civic Parkway in West Des Moines. It is for visitors who want a Hilton-booked boutique stay in the west metro.', geo_key_facts=ARRAY['Address: 6075 Mills Civic Parkway, West Des Moines, IA','Part of Tapestry Collection by Hilton','Boutique hotel','Booked through hilton.com']::text[], geo_faq='[{"question":"Where is The Rewind hotel?","answer":"At 6075 Mills Civic Parkway in West Des Moines, Iowa."},{"question":"Which hotel brand is The Rewind part of?","answer":"Tapestry Collection by Hilton; it is booked through hilton.com."}]'::jsonb, updated_at=now() WHERE id='b689307c-18df-4c2c-a771-7077af2276a5';
UPDATE hotels SET description='TownePlace Suites Des Moines Urbandale is an all-suite extended-stay hotel at 8800 Northpark Dr. Despite the name, the address is in Johnston. It has 116 smoke-free suites over four stories, each with a cooktop, cookware and a full-size refrigerator. Breakfast is included, and there is an indoor heated pool, hot tub, fitness center, coin laundry, a BBQ and picnic area and on-site parking. From I-35/80, take exit 129 at 86th Street and head north to Northpark Drive. Check-in is 3:00 PM and check-out is noon.', short_description='116-suite extended-stay hotel in Johnston off I-35/80 exit 129, with kitchens, free breakfast and an indoor pool.', seo_title='TownePlace Suites Des Moines Urbandale | Johnston, IA', seo_description='TownePlace Suites Des Moines Urbandale in Johnston: 116 suites with kitchens, breakfast included, indoor pool and laundry, off I-35/80 at exit 129.', seo_h1='TownePlace Suites Des Moines Urbandale in Johnston', geo_summary='TownePlace Suites Des Moines Urbandale is a 116-suite Marriott extended-stay hotel at 8800 Northpark Dr in Johnston, off I-35/80 at 86th Street. It suits longer stays where a kitchen, laundry and included breakfast matter.', geo_key_facts=ARRAY['116 smoke-free suites over four stories','Address is in Johnston despite the Urbandale name','Suites have cooktops, cookware and full-size refrigerators','Breakfast included; indoor heated pool and hot tub','Off I-35/80 exit 129 (86th Street)','Check-in 3:00 PM, check-out 12:00 PM']::text[], geo_faq='[{"question":"Is breakfast included at TownePlace Suites Des Moines Urbandale?","answer":"Yes, breakfast is included."},{"question":"Does the hotel accept pets?","answer":"Yes, pets are accepted for an additional fee, according to AAA."},{"question":"How do I get to the hotel from the interstate?","answer":"Take I-35/80 exit 129 at 86th Street and go north to Northpark Drive; the hotel is at 8800 Northpark Dr in Johnston."}]'::jsonb, updated_at=now() WHERE id='ff9b0236-60e5-4362-9aaa-ba7a490d5827';
UPDATE hotels SET description='TownePlace Suites Des Moines West Jordan Creek is a 99-suite extended-stay hotel at 125 S 68th St in West Des Moines, next to Jordan Creek Town Center. It opened in 2015. Every suite has a full kitchen and in-room Wi-Fi, breakfast is free, and there is an indoor pool, a fitness room and outdoor fire pit seating. Des Moines International Airport is about 12.5 miles away. Check-in is 3:00 PM and check-out is noon. It is a practical base if you are working or shopping around Jordan Creek and want to cook during a longer stay.', short_description='99-suite extended-stay hotel next to Jordan Creek Town Center, with full kitchens, free breakfast and an indoor pool.', seo_title='TownePlace Suites Jordan Creek | West Des Moines, IA', seo_description='TownePlace Suites Des Moines West Jordan Creek: 99 suites with full kitchens next to Jordan Creek Town Center, free breakfast and an indoor pool.', seo_h1='TownePlace Suites Des Moines West Jordan Creek in West Des Moines', geo_summary='TownePlace Suites Des Moines West Jordan Creek is a 99-suite Marriott extended-stay hotel beside Jordan Creek Town Center in West Des Moines. It is for travellers who want a full kitchen and free breakfast in the west metro.', geo_key_facts=ARRAY['99 suites, opened 2015','Next to Jordan Creek Town Center','Full kitchens in every suite','Free breakfast, indoor pool, fitness room, outdoor fire pit','About 12.5 miles from Des Moines International Airport','Check-in 3:00 PM, check-out 12:00 PM']::text[], geo_faq='[{"question":"Is breakfast free at TownePlace Suites West Jordan Creek?","answer":"Yes, breakfast is free for guests."},{"question":"How far is the hotel from the Des Moines airport?","answer":"About 12.5 miles from Des Moines International Airport, according to Marriott."},{"question":"Do the suites have kitchens?","answer":"Yes, every suite has a full kitchen."}]'::jsonb, updated_at=now() WHERE id='983d3bff-8e3e-41dd-9d07-43f54a49914e';
UPDATE hotels SET description='Tru by Hilton Ankeny is a 71-room, four-story hotel at 1230 SW District Dr in Ankeny. Breakfast is included, and the hotel has a heated indoor pool, an exercise room, a lounge with a full bar and on-site parking. Pets are accepted for an added fee. From I-35, take exit 90 at Oralabor Road, go 1.3 miles west on SE Oralabor Rd, 0.6 miles north on S Ankeny Blvd, then 0.7 miles west on SW Prairie Trail Pkwy. Check-in is 3:00 PM and check-out is noon.', short_description='71-room Hilton hotel in Ankeny off I-35 exit 90, with breakfast included, a heated indoor pool and a full bar.', seo_title='Tru by Hilton Ankeny | Hotels in Ankeny, IA', seo_description='Tru by Hilton Ankeny at 1230 SW District Dr: 71 rooms, breakfast included, heated indoor pool, full-bar lounge, pets for a fee. Off I-35 exit 90.', seo_h1='Tru by Hilton Ankeny', geo_summary='Tru by Hilton Ankeny is a 71-room, four-story Hilton hotel at 1230 SW District Dr, reached from I-35 exit 90 via Oralabor Road and SW Prairie Trail Parkway. It suits Ankeny visitors who want included breakfast, an indoor pool and a bar on site.', geo_key_facts=ARRAY['71 rooms over four stories','Breakfast included','Heated indoor pool, exercise room, lounge with full bar','On-site parking; pets accepted for a fee','Check-in 3:00 PM, check-out 12:00 PM','From I-35 exit 90 (Oralabor Rd)']::text[], geo_faq='[{"question":"Is breakfast included at Tru by Hilton Ankeny?","answer":"Yes, breakfast is included, according to AAA."},{"question":"Does Tru by Hilton Ankeny allow pets?","answer":"Yes, pets are accepted for an additional fee."},{"question":"What are check-in and check-out times?","answer":"Check-in is 3:00 PM and check-out is 12:00 PM."}]'::jsonb, updated_at=now() WHERE id='175d12f1-757a-4850-8cd0-9c1a18873e6b';
UPDATE hotels SET description='Tru by Hilton Grimes Des Moines is a 116-room hotel at 701 NE Gateway Dr in Grimes, next to the Grimes Sports Complex. It opened in September 2025. Breakfast is free, and there is an indoor heated pool, a fitness center, a business center, Wi-Fi, in-room refrigerators and on-site parking. Pets are accepted for an added fee. From Highway 141, take exit 152 and follow E 1st St to NE Gateway Dr. Check-in is 3:00 PM and check-out is 11:00 AM.', short_description='116-room hotel in Grimes, opened September 2025, next to the Grimes Sports Complex with free breakfast and an indoor pool.', seo_title='Tru by Hilton Grimes Des Moines | Hotels in Grimes, IA', seo_description='Tru by Hilton Grimes Des Moines: 116 rooms next to the Grimes Sports Complex, opened 2025, free breakfast, indoor heated pool, off Highway 141.', seo_h1='Tru by Hilton Grimes Des Moines in Grimes', geo_summary='Tru by Hilton Grimes Des Moines is a 116-room hotel that opened in September 2025 beside the Grimes Sports Complex, off Highway 141. It suits families in town for games at the complex and anyone wanting a Hilton stay in Grimes.', geo_key_facts=ARRAY['116 rooms at 701 NE Gateway Dr, Grimes','Opened September 2025','Next to the Grimes Sports Complex','Free breakfast and an indoor heated pool','Highway 141 exit 152','Check-in 3:00 PM, check-out 11:00 AM']::text[], geo_faq='[{"question":"Is Tru by Hilton Grimes near the Grimes Sports Complex?","answer":"Yes, the hotel is next to the Grimes Sports Complex."},{"question":"Does Tru by Hilton Grimes include breakfast?","answer":"Yes, breakfast is free."},{"question":"Are pets allowed at Tru by Hilton Grimes?","answer":"Yes, pets are accepted for an additional fee, according to AAA."}]'::jsonb, updated_at=now() WHERE id='3f8d3499-3c48-4288-835e-a8251a0ffdb0';
UPDATE hotels SET description='Urbandale Extended Stay is a locally owned and operated hotel at 5900 Sutton Place in Urbandale, offering nightly, weekly and bi-weekly stays in newly remodeled rooms. Rooms come with a microwave, mini-refrigerator, cable TV and free Wi-Fi; the site does not mention full kitchens. Dogs and cats are welcome. The office is open noon to 10 PM Sunday through Thursday and noon to midnight Friday and Saturday, so plan your arrival around those hours or call (515) 270-1037 first.', short_description='Locally owned Urbandale hotel with nightly, weekly and bi-weekly stays, microwaves, mini-fridges and pets welcome.', seo_title='Urbandale Extended Stay | Hotels in Urbandale, IA', seo_description='Urbandale Extended Stay at 5900 Sutton Place: locally owned, nightly, weekly and bi-weekly stays, microwave and mini-fridge rooms, dogs and cats welcome.', seo_h1='Urbandale Extended Stay in Urbandale', geo_summary='Urbandale Extended Stay is a locally owned hotel at 5900 Sutton Place in Urbandale with nightly, weekly and bi-weekly stays. It is for longer stays on a simple setup, including guests travelling with a dog or cat.', geo_key_facts=ARRAY['Locally owned and operated, at 5900 Sutton Place, Urbandale','Nightly, weekly and bi-weekly stays','Rooms have microwaves, mini-refrigerators, cable TV and free Wi-Fi','Dogs and cats welcome','Office open 12-10 PM Sun-Thu, 12 PM-midnight Fri-Sat']::text[], geo_faq='[{"question":"Does Urbandale Extended Stay allow pets?","answer":"Yes, it welcomes dogs and cats. Fees are not listed, so call (515) 270-1037."},{"question":"Can I book by the week at Urbandale Extended Stay?","answer":"Yes, it offers nightly, weekly and bi-weekly stays."},{"question":"Do rooms have a kitchen?","answer":"The hotel lists microwaves and mini-refrigerators in rooms; it does not mention full kitchens."}]'::jsonb, updated_at=now() WHERE id='d373d043-7bc4-4df3-ba04-f6eebf152115';
UPDATE hotels SET description='West Des Moines Marriott is a 220-room, smoke-free hotel at 1250 Jordan Creek Pkwy in West Des Moines. It has two on-site restaurants, a club lounge, a gift shop, a swimming pool and a fitness center, plus about 8,600 sq ft of meeting space across five rooms, the largest 4,602 sq ft. Self parking is complimentary. Pets are welcome for a $75 non-refundable fee per stay, up to three per room. An airport shuttle is available and Des Moines International Airport is about 12 miles away.', short_description='220-room Marriott on Jordan Creek Pkwy with two restaurants, a pool, free self parking and pet-friendly rooms.', seo_title='West Des Moines Marriott | Hotels in West Des Moines, IA', seo_description='West Des Moines Marriott on Jordan Creek Pkwy: 220 rooms, two restaurants, club lounge, pool, free self parking and 8,600 sq ft of meeting space.', seo_h1='West Des Moines Marriott', geo_summary='West Des Moines Marriott is a 220-room full-service hotel at 1250 Jordan Creek Pkwy with two restaurants, a club lounge and about 8,600 sq ft of meeting space. It suits business travellers and groups who want free parking and an airport shuttle in the west metro.', geo_key_facts=ARRAY['220 rooms, smoke-free','Two restaurants and a club lounge','About 8,600 sq ft of meeting space in 5 rooms','Complimentary self parking','Pets: $75 per stay, up to 3 per room','About 12 miles from Des Moines International Airport; shuttle available']::text[], geo_faq='[{"question":"Is parking free at West Des Moines Marriott?","answer":"Yes, self parking is complimentary."},{"question":"Does West Des Moines Marriott allow pets?","answer":"Yes. There is a $75 non-refundable fee per stay, with up to three pets per room."},{"question":"Does the hotel have an airport shuttle?","answer":"Yes, an airport shuttle is available; Des Moines International Airport is about 12 miles away."}]'::jsonb, updated_at=now() WHERE id='84388d50-594e-470e-85b4-4dfb26884fa5';
UPDATE hotels SET description='Wildwood Lodge is a Northwoods-themed boutique hotel at 11431 Forest Avenue in Clive, with a sister property in Pewaukee, Wisconsin. The main lodge has a large indoor fireplace and complimentary board games, and outside there is a fire pit. Guests get an expanded hot breakfast and use of an indoor pool and spa. Room photos show king rooms and a king suite with a dining table. The hotel''s own site does not list check-in times, parking or a pet policy, so call 515-222-9876 before booking if those matter.', short_description='Northwoods-themed boutique hotel in Clive with an indoor fireplace, fire pit, indoor pool and spa, and hot breakfast.', seo_title='Wildwood Lodge Clive | Boutique Hotel in Clive, IA', seo_description='Wildwood Lodge at 11431 Forest Avenue in Clive: a Northwoods-style boutique hotel with an indoor pool and spa, fireplace, fire pit and hot breakfast.', seo_h1='Wildwood Lodge in Clive', geo_summary='Wildwood Lodge is a Northwoods-themed boutique hotel at 11431 Forest Avenue in Clive, Iowa. It suits families and couples who want a lodge feel with an indoor pool, a fireplace and a hot breakfast.', geo_key_facts=ARRAY['11431 Forest Avenue, Clive, IA; phone 515-222-9876','Northwoods-themed boutique hotel','Indoor pool and spa','Large indoor fireplace and outdoor fire pit','Expanded hot breakfast and free board games in the main lodge','Sister property in Pewaukee, Wisconsin']::text[], geo_faq='[{"question":"Does Wildwood Lodge serve breakfast?","answer":"Yes, the hotel offers an expanded hot breakfast."},{"question":"Does Wildwood Lodge have a pool?","answer":"Yes, it has an indoor pool and spa."}]'::jsonb, updated_at=now() WHERE id='d10b7a98-9ad0-4ed2-b6db-979cfaa49898';
UPDATE hotels SET description='WoodSpring Suites Ankeny Des Moines is an extended-stay hotel at 6703 SE Bellagio Dr in Ankeny, off Interstate 35 north of Des Moines. Every suite has a full kitchen with a full-size refrigerator, two-burner stovetop, microwave and prep sink. There is guest laundry, free Wi-Fi and free parking, and the front desk is staffed 24 hours. Long-stay guests get housekeeping every other week. DMACC''s Ankeny campus is 4 miles away, Ankeny Regional Airport 2 miles, Des Moines 8 miles and Des Moines International Airport 14 miles.', short_description='Extended-stay suites with full kitchens in Ankeny off I-35, 4 miles from DMACC Ankeny, with free parking and laundry.', seo_title='WoodSpring Suites Ankeny Des Moines | Ankeny, IA', seo_description='WoodSpring Suites Ankeny off I-35: extended-stay suites with full kitchens, guest laundry, free Wi-Fi and parking, 24-hour desk, dogs allowed for a fee.', seo_h1='WoodSpring Suites Ankeny Des Moines in Ankeny', geo_summary='WoodSpring Suites Ankeny Des Moines is an extended-stay hotel off I-35 in Ankeny with a full kitchen in every suite. It is for weekly and longer stays near DMACC Ankeny and the north side of the metro.', geo_key_facts=ARRAY['Full kitchen in every suite','Off Interstate 35, north of Des Moines','Free parking and free Wi-Fi; guest laundry on site','Front desk staffed 24/7','Up to 2 dogs under 80 lbs; no cats','DMACC Ankeny 4 mi, DSM airport 14 mi']::text[], geo_faq='[{"question":"Does WoodSpring Suites Ankeny allow pets?","answer":"Up to two dogs under 80 lbs per room; no cats. The non-refundable fee is $50 for 1-6 nights, $100 for 7-27 nights and $200 for 28 nights."},{"question":"Is parking free at WoodSpring Suites Ankeny?","answer":"Yes, parking is free, including accessible and van spaces."},{"question":"How far is WoodSpring Suites Ankeny from the Des Moines airport?","answer":"Des Moines International Airport is 14 miles away; Ankeny Regional Airport is 2 miles."}]'::jsonb, updated_at=now() WHERE id='e8c76520-56bf-470a-bc08-927843631c4a';
UPDATE hotels SET description='WoodSpring Suites Des Moines Pleasant Hill is an extended-stay hotel at 1525 Metro East Dr in Pleasant Hill, off U.S. Route 65. Each suite has a full kitchen with a full-size refrigerator, two-burner stovetop, microwave and prep sink. Guest laundry, free Wi-Fi and free parking are on site, and the front desk is staffed 24 hours. Weekly and monthly rates are available with no lease or credit check. Des Moines is 6 miles away, the Iowa State Fairgrounds 5-6 miles and Des Moines International Airport 16 miles.', short_description='Extended-stay suites with full kitchens in Pleasant Hill off U.S. 65, 5-6 miles from the Iowa State Fairgrounds.', seo_title='WoodSpring Suites Pleasant Hill | Pleasant Hill, IA', seo_description='WoodSpring Suites Des Moines Pleasant Hill off U.S. 65: full-kitchen suites, weekly and monthly rates, free parking, guest laundry, 24-hour front desk.', seo_h1='WoodSpring Suites Des Moines Pleasant Hill in Pleasant Hill', geo_summary='WoodSpring Suites Des Moines Pleasant Hill is an extended-stay hotel off U.S. 65 with a full kitchen in every suite and weekly or monthly rates. It suits long work assignments and Iowa State Fair visitors who want to cook for themselves.', geo_key_facts=ARRAY['Full kitchen in every suite','Off U.S. Route 65','Weekly and monthly rates; no lease or credit check','Free parking and Wi-Fi; guest laundry; 24/7 front desk','Iowa State Fairgrounds 5-6 mi; DSM airport 16 mi']::text[], geo_faq='[{"question":"How far is WoodSpring Suites Pleasant Hill from the Iowa State Fairgrounds?","answer":"About 5-6 miles, according to the hotel."},{"question":"Does WoodSpring Suites Pleasant Hill allow pets?","answer":"Dogs only, up to two per room. Fees per stay, per pet are $50 for 0-6 nights, $100 for 7-27 nights and $200 for 28+ nights."},{"question":"Can I stay by the week or month?","answer":"Yes, weekly and monthly rates are available, with no lease or credit check."}]'::jsonb, updated_at=now() WHERE id='c5e86c39-7562-4177-a52b-b3641d891ee7';
UPDATE hotels SET description='WoodSpring Suites West Des Moines is an extended-stay hotel at 7255 Lake Drive in West Des Moines. Every suite has a kitchen with a sink, cupboards, full-size refrigerator and freezer, microwave and two-burner cooktop, and layouts include one-bed, two-bed and ADA suites. Guest laundry, free Wi-Fi and free parking are on site. The Wells Fargo West Des Moines campus and Jordan Creek Town Center are each 3 miles away, downtown Des Moines 10 miles, Camp Dodge 13 miles and Des Moines International Airport 16 miles.', short_description='Extended-stay suites with kitchens in West Des Moines, 3 miles from Jordan Creek Town Center, with free parking and laundry.', seo_title='WoodSpring Suites West Des Moines | West Des Moines, IA', seo_description='WoodSpring Suites West Des Moines on Lake Drive: kitchen suites, guest laundry, free Wi-Fi and parking, 3 miles from Jordan Creek Town Center.', seo_h1='WoodSpring Suites West Des Moines', geo_summary='WoodSpring Suites West Des Moines is an extended-stay hotel at 7255 Lake Drive with an in-room kitchen in every suite. It suits longer work stays near the Wells Fargo West Des Moines campus and Jordan Creek Town Center.', geo_key_facts=ARRAY['In-room kitchen in every suite','One-bed, two-bed and ADA suites','Free parking and Wi-Fi; guest laundry','Jordan Creek Town Center and Wells Fargo WDM campus 3 mi','DSM airport 16 mi; Camp Dodge 13 mi','Dogs 30 lbs or under, max 2; no cats']::text[], geo_faq='[{"question":"How far is WoodSpring Suites West Des Moines from Jordan Creek Town Center?","answer":"About 3 miles, according to the hotel."},{"question":"Does WoodSpring Suites West Des Moines allow pets?","answer":"Yes, up to two dogs of 30 lbs or less; no cats. The fee is $50 for 1-6 nights, $100 for 7-27 nights and $200 for 28+ nights."},{"question":"Is parking free?","answer":"Yes, parking is free, including accessible and van spaces."}]'::jsonb, updated_at=now() WHERE id='96dd0887-af57-4ce5-bfac-ecbd0c18022e';
UPDATE hotels SET description='Hampton Inn Des Moines Airport is a 120-room Hilton-brand hotel at 5001 Fleur Drive, across the street from Des Moines International Airport. A free shuttle runs to and from the airport and to places within a two-mile radius, so it works for early flights without a rental car. Stays include free hot breakfast and free WiFi, and the hotel has a fitness center, a business center and a seasonal outdoor pool. Pet-friendly rooms are available. The building dates from 1987 and was renovated in 2017. Check-in is 3 PM and check-out is 11 AM.', short_description='120-room Hampton across Fleur Drive from Des Moines International Airport, with a free shuttle and hot breakfast.', seo_title='Hampton Inn Des Moines Airport | Hotels in Des Moines, IA', seo_description='Hampton Inn on Fleur Drive across from Des Moines International Airport: free airport shuttle, free hot breakfast, seasonal pool and pet-friendly rooms.', seo_h1='Hampton Inn Des Moines Airport', geo_summary='Hampton Inn Des Moines Airport is a 120-room hotel at 5001 Fleur Drive, across the street from Des Moines International Airport. It suits travellers with early or late flights who want a free airport shuttle and breakfast included.', geo_key_facts=ARRAY['120 rooms at 5001 Fleur Drive, Des Moines','Across the street from Des Moines International Airport','Free shuttle to the airport and within a two-mile radius','Free hot breakfast and free WiFi','Seasonal outdoor pool, fitness center, business center','Check-in 3 PM, check-out 11 AM']::text[], geo_faq='[{"question":"Does Hampton Inn Des Moines Airport have an airport shuttle?","answer":"Yes. The hotel runs a free shuttle to and from Des Moines International Airport and to places within a two-mile radius."},{"question":"Is breakfast included?","answer":"Yes, a free hot breakfast is included with the stay."},{"question":"Does the hotel allow pets?","answer":"Pet-friendly rooms are available. Fees and limits were not stated in the sources, so check with the hotel when booking."}]'::jsonb, updated_at=now() WHERE id='a5f06ec5-d793-4fd0-9706-6096cf72fbc0';
UPDATE hotels SET description='Hampton Inn West Des Moines Lake Drive is a four-floor, 135-room Hilton-brand hotel at 7060 Lake Drive in West Des Moines. Booking listings place it about a four-minute drive from Jordan Creek Town Center, which makes it a practical base for shopping trips and west-metro business visits. Free breakfast is served from 6 to 10 AM, and the hotel has free WiFi, an indoor pool, a fitness center and free on-site self parking. Check-in starts at 3 PM.', short_description='135-room Hampton on Lake Drive in West Des Moines, about four minutes by car from Jordan Creek Town Center.', seo_title='Hampton Inn West Des Moines Lake Drive | West Des Moines', seo_description='Hampton Inn at 7060 Lake Drive, West Des Moines: 135 rooms, free breakfast, indoor pool, free parking, about four minutes from Jordan Creek Town Center.', seo_h1='Hampton Inn Des Moines West (Lake Drive), West Des Moines', geo_summary='Hampton Inn West Des Moines Lake Drive is a 135-room hotel at 7060 Lake Drive in West Des Moines, a short drive from Jordan Creek Town Center. It suits shoppers and business travellers who want free breakfast and free parking on the west side of the metro.', geo_key_facts=ARRAY['7060 Lake Drive, West Des Moines','135 rooms on four floors (booking listings)','About a four-minute drive to Jordan Creek Town Center (booking listing)','Free breakfast 6-10 AM','Indoor pool, fitness center, free self parking']::text[], geo_faq='[{"question":"Is breakfast included at Hampton Inn West Des Moines Lake Drive?","answer":"Yes. Booking listings describe a free breakfast served 6 to 10 AM."},{"question":"Is parking free?","answer":"Yes, listings show free on-site self parking."},{"question":"How far is it from Jordan Creek Town Center?","answer":"A booking listing puts it about a four-minute drive from Jordan Creek Town Center."}]'::jsonb, updated_at=now() WHERE id='81c85319-1529-4196-8069-25b40feb7cf3';
UPDATE hotels SET description='Hilton Des Moines Downtown is a 330-room hotel at 435 Park Street that opened in 2018 and is the only hotel connected directly to the Iowa Events Center by the Des Moines skywalk. Park Street Kitchen & Bar on site serves breakfast, lunch and dinner and has an outdoor patio fireplace, and in-room dining is available. The hotel has an indoor pool, a tech lounge with complimentary computers and 14,000 sq ft of meeting space, including a 10,000 sq ft ballroom that opens onto a terrace. Art from the local Moberg Gallery rotates through the building. Check-in is 3 PM and check-out is noon. Pets are not allowed.', short_description='330-room downtown Hilton linked by skywalk to the Iowa Events Center, with Park Street Kitchen and an indoor pool.', seo_title='Hilton Des Moines Downtown | Hotels in Des Moines, IA', seo_description='Hilton Des Moines Downtown, 435 Park Street: 330 rooms, skywalk to the Iowa Events Center, Park Street Kitchen & Bar, indoor pool and meeting space.', seo_h1='Hilton Des Moines Downtown', geo_summary='Hilton Des Moines Downtown is a 330-room hotel at 435 Park Street, opened in 2018 and connected by skywalk to the Iowa Events Center. It suits convention, concert and conference visitors who want to reach the events center without going outside.', geo_key_facts=ARRAY['330 rooms at 435 Park Street, downtown Des Moines','Opened 2018','Only hotel directly connected to the Iowa Events Center by skywalk','Park Street Kitchen & Bar serves breakfast, lunch and dinner','14,000 sq ft of meeting space including a 10,000 sq ft ballroom','Check-in 3 PM, check-out noon; no pets']::text[], geo_faq='[{"question":"Is Hilton Des Moines Downtown connected to the Iowa Events Center?","answer":"Yes. It is the only hotel directly connected to the Iowa Events Center, through the Des Moines skywalk."},{"question":"Does the hotel allow pets?","answer":"No, pets are not allowed."},{"question":"What are check-in and check-out times?","answer":"Check-in is 3 PM and check-out is 12 PM."}]'::jsonb, updated_at=now() WHERE id='2a3da30c-c2a0-4f35-b039-9f24f6481fc8';
UPDATE hotels SET description='Hilton Garden Inn Des Moines Airport is a 100-room, four-story hotel at 6800 Fleur Drive, about one mile south of Des Moines International Airport. It operated as the DoubleTree by Hilton Des Moines Airport until a $3.3 million renovation, and it reopened under the Hilton Garden Inn name with a ribbon cutting on May 9, 2024. Johnny''s Italian Steakhouse is on site. A complimentary airport shuttle, free parking and free WiFi are included, and the hotel has a fitness center, connecting rooms, Digital Key and pet-friendly rooms. Check-in is 3 PM and check-out is noon.', short_description='100-room Hilton Garden Inn on Fleur Drive near Des Moines airport, with a free shuttle and Johnny''s Italian Steakhouse.', seo_title='Hilton Garden Inn Des Moines Airport | Des Moines, IA', seo_description='Hilton Garden Inn on Fleur Drive, about a mile south of Des Moines International Airport: free shuttle and parking, Johnny''s Italian Steakhouse on site.', seo_h1='Hilton Garden Inn Des Moines Airport', geo_summary='Hilton Garden Inn Des Moines Airport is a 100-room hotel at 6800 Fleur Drive, about one mile south of Des Moines International Airport, reopened in 2024 after converting from a DoubleTree. It suits air travellers who want a free shuttle, free parking and a steakhouse in the building.', geo_key_facts=ARRAY['100 rooms at 6800 Fleur Drive, Des Moines','About one mile south of Des Moines International Airport','Former DoubleTree; reopened after a $3.3 million renovation, ribbon cutting May 9, 2024','Johnny''s Italian Steakhouse on site','Free airport shuttle, free parking, pet-friendly rooms','Check-in 3 PM, check-out noon']::text[], geo_faq='[{"question":"How far is Hilton Garden Inn Des Moines Airport from the airport?","answer":"About one mile south of Des Moines International Airport on Fleur Drive, and the hotel runs a complimentary airport shuttle."},{"question":"Is parking free?","answer":"Yes, parking is free."},{"question":"Is there a restaurant at the hotel?","answer":"Yes, Johnny''s Italian Steakhouse is on site."}]'::jsonb, updated_at=now() WHERE id='b72a5386-60ff-465f-b5b4-104988e58baa';
UPDATE hotels SET description='Hilton Garden Inn Des Moines/Urbandale carries the Urbandale name but sits at 8600 Northpark Drive in Johnston, on the southeast corner of Northpark Drive and NW 86th Street, directly off I-35/80 at Exit 129. The hotel has 148 guest rooms and close to 11,000 sq ft of function space with catering. Guests get an indoor pool, a sauna, an on-site restaurant and bar, free WiFi in public areas and free on-site parking. Breakfast is cooked to order for a charge. Dogs and cats are allowed on request for a per-stay fee. Check-in is 3 PM and check-out is noon.', short_description='148-room Hilton Garden Inn in Johnston off I-35/80 Exit 129, with an indoor pool, sauna and 11,000 sq ft of event space.', seo_title='Hilton Garden Inn Des Moines/Urbandale | Johnston, IA', seo_description='Hilton Garden Inn at 8600 Northpark Drive, Johnston, off I-35/80 Exit 129: 148 rooms, indoor pool, sauna, restaurant and bar, free parking.', seo_h1='Hilton Garden Inn Des Moines/Urbandale, Johnston', geo_summary='Hilton Garden Inn Des Moines/Urbandale is a 148-room hotel at 8600 Northpark Drive in Johnston, just off I-35/80 at Exit 129. It suits interstate travellers and groups booking meetings or events on the northwest side of the metro.', geo_key_facts=ARRAY['148 guest rooms at 8600 Northpark Drive, Johnston','Directly off I-35/80 at Exit 129 (NW 86th Street)','Close to 11,000 sq ft of function space with catering','Indoor pool, sauna, restaurant and bar','Free on-site parking','Check-in 3 PM, check-out noon']::text[], geo_faq='[{"question":"How do I get to Hilton Garden Inn Des Moines/Urbandale from the interstate?","answer":"Take I-35/80 to Exit 129, go north on NW 86th Street, then west onto Northpark Drive. The hotel is on the southeast corner of Northpark Drive and NW 86th Street."},{"question":"Does the hotel allow pets?","answer":"A Trip.com listing says dogs and cats are allowed on request for a fee of $50 per room per stay."},{"question":"Is parking free?","answer":"Yes, the Trip.com listing shows free on-site parking."}]'::jsonb, updated_at=now() WHERE id='537d5c04-2e34-4199-a6d8-d5029827bb5d';
UPDATE hotels SET description='Hilton Garden Inn West Des Moines is a 176-room hotel at 205 South 64th Street, next to Jordan Creek Town Center and a Wells Fargo corporate office. Its on-site restaurant and bar serves made-to-order meals, and the hotel has an indoor pool, a fitness center, meeting rooms, connecting rooms and Digital Key. Parking and Wi-Fi are free, rooms are non-smoking and pet-friendly rooms are available. The hotel opened in 2005 and was renovated in 2013. Check-in is 3 PM and check-out is noon.', short_description='176-room Hilton Garden Inn next to Jordan Creek Town Center, with an indoor pool, restaurant and bar, and free parking.', seo_title='Hilton Garden Inn West Des Moines | West Des Moines, IA', seo_description='Hilton Garden Inn at 205 South 64th Street, next to Jordan Creek Town Center: 176 rooms, indoor pool, restaurant and bar, free parking and Wi-Fi.', seo_h1='Hilton Garden Inn West Des Moines', geo_summary='Hilton Garden Inn West Des Moines is a 176-room hotel at 205 South 64th Street, next to Jordan Creek Town Center and a Wells Fargo corporate office. It suits business travellers and shoppers who want a restaurant, pool and free parking in the Jordan Creek area.', geo_key_facts=ARRAY['176 rooms at 205 South 64th Street, West Des Moines','Next to Jordan Creek Town Center and a Wells Fargo corporate office','On-site restaurant and bar','Indoor pool, fitness center, meeting rooms','Free parking and Wi-Fi; pet-friendly rooms','Opened 2005, renovated 2013']::text[], geo_faq='[{"question":"Is Hilton Garden Inn West Des Moines near Jordan Creek Town Center?","answer":"Yes. Hilton describes it as next to Jordan Creek Town Center."},{"question":"Is parking free?","answer":"Yes, parking is free."},{"question":"What are check-in and check-out times?","answer":"Check-in is 3 PM and check-out is 12 PM."}]'::jsonb, updated_at=now() WHERE id='c39c72c2-bb3d-467e-95c0-dce646ff5f6c';
UPDATE hotels SET description='Holiday Inn & Suites Des Moines Northwest is a 198-room full-service hotel at 4800 Merle Hay Road in Urbandale, just south of I-35/80 at Exit 131 and minutes from Merle Hay Mall. A Bennigan''s restaurant and bar on site is open daily from 6:30 AM to 11 PM, and room service is available. The conference center has about 17,000 sq ft of meeting space and a ballroom for up to 375. Guests have an indoor heated pool, fitness center, business center and coin laundry, plus more than 350 free parking spaces and a shuttle within a three-mile radius. Check-in is 3 PM, check-out is noon and the minimum check-in age is 21.', short_description='198-room Holiday Inn on Merle Hay Road off I-35/80 Exit 131, with Bennigan''s on site and a 17,000 sq ft conference center.', seo_title='Holiday Inn & Suites Des Moines Northwest | Urbandale, IA', seo_description='Holiday Inn & Suites at 4800 Merle Hay Rd, Urbandale, off I-35/80 Exit 131: 198 rooms, Bennigan''s on site, indoor pool and 350+ free parking spaces.', seo_h1='Holiday Inn & Suites Des Moines Northwest, Urbandale', geo_summary='Holiday Inn & Suites Des Moines Northwest is a 198-room full-service hotel at 4800 Merle Hay Road in Urbandale, near Merle Hay Mall and I-35/80 Exit 131. It suits groups and event planners who need a ballroom and conference space, and drivers who want free parking right off the interstate.', geo_key_facts=ARRAY['198 rooms at 4800 Merle Hay Rd, Urbandale','Just south of I-35/80 at Exit 131, minutes from Merle Hay Mall','Bennigan''s on site, open 6:30 AM to 11 PM daily','About 17,000 sq ft of meeting space; ballroom for up to 375','Over 350 free parking spaces','Minimum check-in age 21']::text[], geo_faq='[{"question":"Does Holiday Inn & Suites Des Moines Northwest allow pets?","answer":"AAA says pets are accepted for an additional fee. Confirm the current amount with the hotel."},{"question":"Is there a restaurant on site?","answer":"Yes, a Bennigan''s restaurant and bar is open daily from 6:30 AM to 11 PM, and room service is offered."},{"question":"Is parking free?","answer":"Yes. The hotel has more than 350 free parking spaces."}]'::jsonb, updated_at=now() WHERE id='9ee15a44-807e-4c48-8b90-c2fbc55f337d';
UPDATE hotels SET description='Holiday Inn Des Moines - Airport is a 213-room hotel at 6111 Fleur Drive, about 0.25 miles from Des Moines International Airport, with a free 24-hour airport shuttle. Its 34,000 sq ft of meeting and event space includes Iowa Hall, which holds 1,500 guests, and catering is available. The indoor pool and whirlpool sit in a tropical courtyard, and the lobby bar hides a speakeasy with pool tables, darts and bowling. There is a fitness center, and pets are welcome for $35 per night. Check-in is 4 PM and check-out is 11 AM.', short_description='213-room Holiday Inn a quarter mile from Des Moines airport, with a 24-hour shuttle, Iowa Hall and a lobby speakeasy.', seo_title='Holiday Inn Des Moines - Airport | Hotels in Des Moines, IA', seo_description='Holiday Inn at 6111 Fleur Drive, 0.25 miles from Des Moines International Airport: free 24-hour shuttle, indoor pool, 34,000 sq ft of event space.', seo_h1='Holiday Inn Des Moines - Airport', geo_summary='Holiday Inn Des Moines - Airport is a 213-room hotel at 6111 Fleur Drive, about a quarter mile from Des Moines International Airport, with a free 24-hour shuttle. It suits air travellers and large events, since Iowa Hall holds up to 1,500 guests.', geo_key_facts=ARRAY['213 rooms at 6111 Fleur Drive, Des Moines','About 0.25 miles from Des Moines International Airport','Free 24-hour airport shuttle','34,000 sq ft of event space; Iowa Hall holds 1,500','Indoor pool and whirlpool in a tropical courtyard','Pets welcome for $35 per night; check-in 4 PM, check-out 11 AM']::text[], geo_faq='[{"question":"Does Holiday Inn Des Moines - Airport have a shuttle?","answer":"Yes, a free airport shuttle runs 24 hours a day. The hotel is about 0.25 miles from Des Moines International Airport."},{"question":"Are pets allowed?","answer":"Yes. IHG lists pets as welcome for $35 per night."},{"question":"What time is check-in?","answer":"Check-in is 4 PM and check-out is 11 AM."}]'::jsonb, updated_at=now() WHERE id='99adcca3-a10e-4992-a963-4fa4464a241d';
UPDATE hotels SET description='Holiday Inn Des Moines Downtown - Mercy Area is a full-service hotel of about 250 rooms at 1050 6th Avenue, on the north edge of downtown Des Moines near the Mercy hospital campus. AAA lists a restaurant and lounge bar, a heated indoor pool, on-site parking and an airport shuttle. Booking listings add a fitness center, a 24-hour business center, about 9,000 sq ft of conference space, and rooms with a refrigerator, microwave and coffee maker. Check-in is 3 PM and check-out is 11 AM. Pets are not accepted in guest rooms.', short_description='About 250-room full-service Holiday Inn on 6th Avenue near the Mercy campus, with a restaurant, indoor pool and airport shuttle.', seo_title='Holiday Inn Downtown - Mercy Area | Des Moines, IA', seo_description='Holiday Inn at 1050 6th Ave, Des Moines, near the Mercy campus: about 250 rooms, restaurant and lounge, heated indoor pool, on-site parking, airport shuttle.', seo_h1='Holiday Inn Des Moines Downtown - Mercy Area', geo_summary='Holiday Inn Des Moines Downtown - Mercy Area is a full-service hotel of about 250 rooms at 1050 6th Avenue, near the Mercy hospital campus and downtown Des Moines. It suits hospital visitors and downtown event-goers who want on-site parking, a restaurant and an airport shuttle.', geo_key_facts=ARRAY['About 250 rooms at 1050 6th Ave, Des Moines (AAA lists 250)','Near the Mercy hospital campus and downtown venues','Restaurant and lounge bar; heated indoor pool','On-site parking and airport shuttle','Check-in 3 PM, check-out 11 AM','Pets not accepted in guest rooms']::text[], geo_faq='[{"question":"Does Holiday Inn Des Moines Downtown - Mercy Area allow pets?","answer":"No. AAA says pets are not accepted in guest rooms."},{"question":"Is there an airport shuttle?","answer":"Yes, AAA lists an airport shuttle. Ask the hotel about the schedule."},{"question":"What are check-in and check-out times?","answer":"Check-in is 3 PM and check-out is 11 AM."}]'::jsonb, updated_at=now() WHERE id='134ecb9a-d035-45e9-9d4c-ab27a40029d8';
UPDATE hotels SET description='Holiday Inn Express & Suites Altoona is an 80-room, three-floor hotel at 165 Adventureland Drive NW in Altoona, near Adventureland Park and Bass Pro Shops on the east side of the Des Moines metro. Free breakfast runs 6 to 9:30 AM, kids eat free, and coffee is out in the lobby all day. The building is smoke-free, with an indoor pool, fitness center, self-service laundry, Wi-Fi and free parking. There is no airport shuttle and no semi-trailer parking. Check-in is 4 PM and check-out is noon.', short_description='80-room Holiday Inn Express on Adventureland Drive in Altoona, near Adventureland Park, with free breakfast and a pool.', seo_title='Holiday Inn Express & Suites Altoona | Altoona, IA', seo_description='Holiday Inn Express & Suites at 165 Adventureland Dr NW, Altoona: 80 rooms near Adventureland Park, free breakfast, kids eat free, indoor pool.', seo_h1='Holiday Inn Express & Suites Altoona', geo_summary='Holiday Inn Express & Suites Altoona is an 80-room hotel at 165 Adventureland Drive NW, near Adventureland Park and Bass Pro Shops. It suits families visiting the park who want free breakfast, a pool and free parking.', geo_key_facts=ARRAY['80 rooms over 3 floors at 165 Adventureland Dr NW, Altoona','Near Adventureland Park, Bass Pro Shops and Iowa Speedway (per IHG)','Free breakfast 6-9:30 AM; kids eat free','Indoor pool, fitness center, self-service laundry','Free parking; no semi-trailer parking; no airport shuttle','Check-in 4 PM, check-out noon']::text[], geo_faq='[{"question":"Is Holiday Inn Express & Suites Altoona near Adventureland?","answer":"Yes. IHG lists it near Adventureland Park, and the hotel sits on Adventureland Drive NW."},{"question":"What time is breakfast?","answer":"Free breakfast is served from 6:00 to 9:30 AM, and kids eat free."},{"question":"Does the hotel have an airport shuttle?","answer":"No, there is no airport shuttle."}]'::jsonb, updated_at=now() WHERE id='2f3ca5bc-327d-4f22-905c-b959bca3f755';
UPDATE hotels SET description='Holiday Inn Express & Suites Des Moines - Ankeny is at 2502 South Hulsizer Road in Ankeny, on the north side of the Des Moines metro. Kayak lists 74 air-conditioned rooms with complimentary bottled water and daily housekeeping. A free full breakfast is included, and the smoke-free hotel has an indoor pool, a fitness center, a 24-hour front desk, free Wi-Fi in public areas and free self parking. Woodland Hills Golf Course is listed at 1.9 miles and Des Moines airport at 12 miles. Check-in is after 3 PM and check-out is before 11 AM.', short_description='Holiday Inn Express on South Hulsizer Road in Ankeny with free full breakfast, an indoor pool and free self parking.', seo_title='Holiday Inn Express & Suites Ankeny | Hotels in Ankeny, IA', seo_description='Holiday Inn Express & Suites at 2502 S Hulsizer Rd, Ankeny: free full breakfast, indoor pool, fitness center, free self parking, 12 miles to DSM airport.', seo_h1='Holiday Inn Express & Suites Des Moines - Ankeny', geo_summary='Holiday Inn Express & Suites Des Moines - Ankeny is a hotel at 2502 South Hulsizer Road in Ankeny, north of Des Moines. It suits visitors to Ankeny who want free breakfast, a pool and free parking, about 12 miles from Des Moines airport.', geo_key_facts=ARRAY['2502 S Hulsizer Rd, Ankeny','74 rooms per Kayak','Free full breakfast; free Wi-Fi in public areas','Indoor pool, fitness center, 24-hour front desk','Free self parking','Check-in after 3 PM, check-out before 11 AM']::text[], geo_faq='[{"question":"Is breakfast included at Holiday Inn Express Ankeny?","answer":"Yes, a free full breakfast is included."},{"question":"How far is it from Des Moines airport?","answer":"Kayak lists Des Moines airport at 12 miles."},{"question":"Is there a pool?","answer":"Yes, the hotel has an indoor pool."}]'::jsonb, updated_at=now() WHERE id='a86f3881-6985-4237-a60c-b4c028dbc734';
UPDATE hotels SET description='Holiday Inn Express & Suites Des Moines Downtown is at 333 SW 11th Street, on the southwest side of downtown Des Moines. Booking listings put Principal Park, home of the Iowa Cubs, about a 13-minute walk (0.7 miles) away, and Booking.com lists Wells Fargo Arena at 1.2 miles. A free grab-and-go breakfast runs 6:30 to 9:30 AM. The hotel has a heated indoor pool, a hot tub, an exercise room and a business center, and listings show free on-site self parking, free Wi-Fi and an airport shuttle. Rooms have a refrigerator, microwave and coffee maker.', short_description='Holiday Inn Express on SW 11th Street downtown, about a 13-minute walk to Principal Park, with free breakfast and a pool.', seo_title='Holiday Inn Express Des Moines Downtown | Des Moines, IA', seo_description='Holiday Inn Express & Suites at 333 SW 11th St, downtown Des Moines: about a 13-minute walk to Principal Park, free breakfast, indoor pool, free parking.', seo_h1='Holiday Inn Express & Suites Des Moines Downtown', geo_summary='Holiday Inn Express & Suites Des Moines Downtown is a hotel at 333 SW 11th Street, about a 13-minute walk from Principal Park. It suits baseball fans and downtown visitors who want free breakfast, a pool and free parking.', geo_key_facts=ARRAY['333 SW 11th St, Des Moines','About a 13-minute walk (0.7 mi) to Principal Park (booking listing)','1.2 miles from Wells Fargo Arena (Booking.com)','Free breakfast 6:30-9:30 AM','Heated indoor pool, hot tub, exercise room','Free on-site self parking']::text[], geo_faq='[{"question":"How far is Holiday Inn Express Des Moines Downtown from Principal Park?","answer":"Booking listings put Principal Park about a 13-minute walk, or 0.7 miles."},{"question":"Is breakfast included?","answer":"Yes, a free grab-and-go breakfast is served daily from 6:30 to 9:30 AM."},{"question":"Is parking free?","answer":"Listings show free on-site self parking."}]'::jsonb, updated_at=now() WHERE id='920c6943-4f15-423d-b719-86d781902b18';
UPDATE hotels SET description='Holiday Inn Express & Suites Urbandale is a 93-room, four-floor hotel at 8789 Plum Drive in Urbandale, near I-35/I-80 at Exit 129 (86th Street). It was built in 2011 and renovated in 2022. Free breakfast and free self parking are included, and the hotel has an indoor heated pool, a hot tub, a fitness center, a business center and meeting space for up to 100 people. Des Moines International Airport is about a 32-minute drive. Check-in is 3 PM and check-out is 11 AM. Third-party listings say pets are not accepted.', short_description='93-room Holiday Inn Express on Plum Drive in Urbandale near I-35/80 Exit 129, with free breakfast and an indoor pool.', seo_title='Holiday Inn Express & Suites Urbandale | Urbandale, IA', seo_description='Holiday Inn Express & Suites at 8789 Plum Dr, Urbandale, near I-35/80 Exit 129: 93 rooms, free breakfast, indoor pool, hot tub, free self parking.', seo_h1='Holiday Inn Express & Suites Urbandale', geo_summary='Holiday Inn Express & Suites Urbandale is a 93-room hotel at 8789 Plum Drive, near I-35/I-80 Exit 129 on the northwest side of the metro. It suits interstate travellers and small groups who want free breakfast, a pool and meeting space for up to 100.', geo_key_facts=ARRAY['93 rooms on four floors at 8789 Plum Dr, Urbandale','Near I-35/I-80 Exit 129 (86th St)','Built 2011, renovated 2022','Free breakfast and free self parking','Indoor heated pool, hot tub, fitness center','Meeting space for up to 100']::text[], geo_faq='[{"question":"Does Holiday Inn Express & Suites Urbandale allow pets?","answer":"Third-party listings say pets are not accepted."},{"question":"How far is it from Des Moines International Airport?","answer":"About a 32-minute drive."},{"question":"What are check-in and check-out times?","answer":"Check-in is 3 PM and check-out is 11 AM."}]'::jsonb, updated_at=now() WHERE id='43d82446-d8ba-496e-9470-5698a031fd9e';
UPDATE hotels SET description='Holiday Inn Express & Suites West Des Moines Jordan Creek is a 99-room, four-floor hotel at 240 Jordan Creek Parkway, about a three-minute walk from Jordan Creek Town Center with easy access to I-35 and I-80. Built in 2018 and managed by Kinseth Hospitality, it serves a complimentary Express Start breakfast and has an indoor pool, fitness center, on-site laundry and market, free Wi-Fi, free self parking and EV chargers. A meeting room seats 20. There is no restaurant and no airport shuttle. Pets are welcome for $55 per night. Check-in is 3 PM and check-out is 11 AM.', short_description='99-room Holiday Inn Express on Jordan Creek Parkway, a short walk from Jordan Creek Town Center, with EV chargers.', seo_title='Holiday Inn Express Jordan Creek | West Des Moines, IA', seo_description='Holiday Inn Express & Suites at 240 Jordan Creek Pkwy: 99 rooms, about a 3-minute walk to Jordan Creek Town Center, free breakfast, pool, EV chargers.', seo_h1='Holiday Inn Express & Suites West Des Moines Jordan Creek', geo_summary='Holiday Inn Express & Suites West Des Moines Jordan Creek is a 99-room hotel at 240 Jordan Creek Parkway, about a three-minute walk from Jordan Creek Town Center. It suits shoppers and drivers on I-35/I-80 who want free breakfast, free parking and EV charging.', geo_key_facts=ARRAY['99 rooms on 4 floors at 240 Jordan Creek Pkwy, West Des Moines','About a 3-minute walk to Jordan Creek Town Center (Travelocity)','Built 2018; managed by Kinseth Hospitality','Free Express Start breakfast, free self parking, EV chargers','No on-site restaurant and no airport shuttle','Pets welcome, $55 per night']::text[], geo_faq='[{"question":"Can I walk to Jordan Creek Town Center from this hotel?","answer":"Yes. Travelocity puts Jordan Creek Town Center about a three-minute walk away."},{"question":"Are pets allowed?","answer":"Yes, pets are welcome for $55 per night according to IHG."},{"question":"Is there an airport shuttle?","answer":"No. IHG lists no airport shuttle and no on-site restaurant."}]'::jsonb, updated_at=now() WHERE id='1e392acd-f873-40b9-8253-cdd104d93202';
UPDATE hotels SET description='Sleep Inn & Suites Pleasant Hill - Des Moines sits on Morning Star Court in Pleasant Hill, close to Interstate 80 and Interstate 235. Choice Hotels names Adventureland, the Iowa State Fairgrounds and downtown Des Moines among the nearby attractions. The hotel is 100% smoke-free and has an indoor pool, an indoor hot tub, a fitness center, guest laundry and free hot breakfast. Dogs are accepted, up to two per room at 60 pounds each, for a nightly fee. Check-in is 3:00 PM and check-out is 11:00 AM.', short_description='Smoke-free Sleep Inn in Pleasant Hill near I-80 and I-235, with an indoor pool, hot tub and free hot breakfast.', seo_title='Sleep Inn & Suites Pleasant Hill | Hotels in Pleasant Hill', seo_description='Sleep Inn & Suites in Pleasant Hill, IA: indoor pool, hot tub, free hot breakfast and dog-friendly rooms near the Iowa State Fairgrounds and Adventureland.', seo_h1='Sleep Inn & Suites Pleasant Hill - Des Moines', geo_summary='Sleep Inn & Suites Pleasant Hill - Des Moines is a smoke-free Choice Hotels property in Pleasant Hill, close to I-80 and I-235. It suits visitors headed to the Iowa State Fairgrounds, Adventureland or downtown Des Moines who want a pool and free hot breakfast.', geo_key_facts=ARRAY['Address: 5850 Morning Star Court, Pleasant Hill, IA 50327','Check-in 3:00 PM, check-out 11:00 AM','Indoor pool, indoor hot tub and fitness center','Free hot breakfast and free Wi-Fi','Dogs only, max 2 per room, 60 lb each, nightly fee','100% smoke-free']::text[], geo_faq='[{"question":"Does Sleep Inn & Suites Pleasant Hill allow pets?","answer":"Dogs only, up to two per room and 60 pounds each, for a nightly fee. Service animals stay free."},{"question":"Is breakfast included?","answer":"Yes, Choice Hotels lists free hot breakfast."},{"question":"What are check-in and check-out times?","answer":"Check-in is 3:00 PM and check-out is 11:00 AM."}]'::jsonb, updated_at=now() WHERE id='63e2d54b-f0cf-419c-852f-7abc4f5633e4';
UPDATE hotels SET description='Sleep Inn & Suites West Des Moines is a three-floor, 65-room hotel on S 51st St in West Des Moines, near Jordan Creek Town Center and West Glen Town Center. It opened in 2017. Guests get free hot breakfast and an indoor pool, and the building is 100% smoke-free with vending machines on site. A meeting room holds up to 43 people, which works for a small team gathering or family event. Pets are welcome; a venue directory notes an extra fee. Check-in is 3:00 PM and check-out is 11:00 AM.', short_description='65-room Sleep Inn near Jordan Creek Town Center with an indoor pool, free hot breakfast and pet-friendly rooms.', seo_title='Sleep Inn & Suites West Des Moines | Hotels in WDM, IA', seo_description='Sleep Inn & Suites West Des Moines: 65 smoke-free rooms near Jordan Creek Town Center, with an indoor pool, free hot breakfast and pet-friendly rooms.', seo_h1='Sleep Inn & Suites West Des Moines', geo_summary='Sleep Inn & Suites West Des Moines is a 65-room, smoke-free hotel opened in 2017 near Jordan Creek Town Center and West Glen Town Center. It fits shoppers, families and small groups wanting an indoor pool and free hot breakfast in West Des Moines.', geo_key_facts=ARRAY['65 rooms over three floors, opened 2017','Near Jordan Creek Town Center and West Glen Town Center','Indoor pool and free hot breakfast','Meeting room for up to 43 people','Check-in 3:00 PM, check-out 11:00 AM','Pet friendly, extra fee']::text[], geo_faq='[{"question":"Is Sleep Inn & Suites West Des Moines near Jordan Creek Town Center?","answer":"Yes, Choice Hotels lists it near Jordan Creek Town Center and West Glen Town Center."},{"question":"Does the hotel allow pets?","answer":"Yes, it is pet friendly; a venue directory notes an additional fee."},{"question":"What time is check-in?","answer":"Check-in is 3:00 PM and check-out is 11:00 AM."}]'::jsonb, updated_at=now() WHERE id='24a7b935-285d-48f4-b68c-0ba5ff779fd0';
UPDATE hotels SET description='Sleep Inn Waukee-West Des Moines is on Grand Prairie Parkway in Waukee, which Choice Hotels places 15 minutes outside Des Moines. The 100% smoke-free hotel serves free hot breakfast with coffee and waffles, and has free Wi-Fi, free parking, a fitness center and guest laundry. Pets are allowed for a nightly fee, up to two per room at 50 pounds each, and service animals stay free. Guests 18 and under stay free with an adult. Check-in is 3:00 PM and check-out is 11:00 AM.', short_description='Smoke-free Sleep Inn in Waukee with free hot breakfast, free parking, a fitness center and pet-friendly rooms.', seo_title='Sleep Inn Waukee-West Des Moines | Hotels in Waukee, IA', seo_description='Sleep Inn Waukee-West Des Moines on Grand Prairie Parkway: free hot breakfast with waffles, free parking and Wi-Fi, fitness center and pet-friendly rooms.', seo_h1='Sleep Inn Waukee-West Des Moines', geo_summary='Sleep Inn Waukee-West Des Moines is a smoke-free Choice Hotels property on Grand Prairie Parkway in Waukee, about 15 minutes outside Des Moines. It suits travellers working or visiting family in Waukee and West Des Moines who want free breakfast and parking.', geo_key_facts=ARRAY['Address: 2885 Grand Prairie Parkway, Building A, Waukee, IA 50263','About 15 minutes outside Des Moines (hotel)','Free hot breakfast, Wi-Fi and parking','Check-in 3:00 PM, check-out 11:00 AM','Pets: max 2 per room, 50 lb each, nightly fee','100% smoke-free']::text[], geo_faq='[{"question":"Does Sleep Inn Waukee allow pets?","answer":"Yes, up to two pets per room, 50 pounds maximum, for a nightly fee. Service animals stay free."},{"question":"Is parking free?","answer":"Yes, the hotel lists free parking."},{"question":"Is breakfast included?","answer":"Yes, free hot breakfast with fresh coffee and waffles."}]'::jsonb, updated_at=now() WHERE id='90089685-9f6a-4a0f-b791-1866ffc97789';
UPDATE hotels SET description='Sonesta Essential Des Moines is a 140-room hotel on Merle Hay Rd in Des Moines, just off I-35. The hotel names Drake University, the Iowa State Fairgrounds, Wells Fargo Arena, the Iowa State Capitol and downtown as nearby. A free hot continental breakfast runs 6:00-9:00 AM on weekdays and 6:30-9:30 AM on weekends, and parking and Wi-Fi are free. Rooms have a microwave, refrigerator and coffee maker. Pets of any breed are allowed, two per room up to 50 pounds each, for a nightly fee. Check-in 3:00 PM, check-out 11:00 AM.', short_description='140-room Sonesta Essential on Merle Hay Rd off I-35, with free breakfast, free parking and pet-friendly rooms.', seo_title='Sonesta Essential Des Moines | Hotels in Des Moines, IA', seo_description='Sonesta Essential Des Moines on Merle Hay Rd: 140 rooms off I-35 with free hot continental breakfast, free parking and Wi-Fi, and pets up to 50 lb.', seo_h1='Sonesta Essential Des Moines', geo_summary='Sonesta Essential Des Moines is a 140-room hotel on Merle Hay Rd, just off I-35. It works for visitors to Drake University, the Iowa State Fairgrounds or downtown who want free breakfast and parking and may travel with a pet.', geo_key_facts=ARRAY['140 rooms at 4755 Merle Hay Rd','Just off I-35','Free hot continental breakfast, parking and Wi-Fi','Check-in 3:00 PM, check-out 11:00 AM','Pets: no breed limits, max 2 per room, 50 lb each, nightly fee']::text[], geo_faq='[{"question":"What time is breakfast at Sonesta Essential Des Moines?","answer":"6:00-9:00 AM Monday-Friday and 6:30-9:30 AM Saturday-Sunday."},{"question":"Is parking free?","answer":"Yes, on-site parking is free."},{"question":"Does the hotel allow pets?","answer":"Yes, with no breed restrictions, up to two pets per room at 50 pounds each, for a nightly fee per pet."}]'::jsonb, updated_at=now() WHERE id='1b6ea0c6-0c88-45d1-95ca-c4e50055c110';
UPDATE hotels SET description='Sonesta Simply Suites Des Moines West is an extended-stay hotel on Office Plaza Drive N in West Des Moines. Every suite has a full kitchen with a full-size refrigerator, stovetop, microwave and dishwasher, plus a work space. The property has on-site laundry, a 24-hour gym, a 24-hour store, a BBQ gazebo, free parking and free Wi-Fi. Pets are welcome with no breed or weight limits, up to two per suite, for a stay-length fee. The hotel lists Valley Stadium and the Des Moines Children''s Museum nearby. Check-in is 4:00 PM, check-out 11:00 AM.', short_description='Extended-stay suites in West Des Moines with full kitchens, free parking, a 24-hour gym and pets of any size.', seo_title='Sonesta Simply Suites Des Moines West | WDM Extended Stay', seo_description='Sonesta Simply Suites Des Moines West: extended-stay suites with full kitchens, on-site laundry, 24-hour gym, free parking and pet-friendly suites.', seo_h1='Sonesta Simply Suites Des Moines West, West Des Moines', geo_summary='Sonesta Simply Suites Des Moines West is an extended-stay hotel in West Des Moines where every suite has a full kitchen. It suits long work assignments, relocations and travellers with pets who want to cook and do laundry on site.', geo_key_facts=ARRAY['Address: 7625 Office Plaza Drive N, West Des Moines','Full kitchens with dishwasher in every suite','Free parking and Wi-Fi, 24-hour gym, on-site laundry','Check-in 4:00 PM, check-out 11:00 AM','Pets: no breed or weight limits, max 2 per suite, fee by stay length']::text[], geo_faq='[{"question":"Do suites have kitchens?","answer":"Yes, a full kitchen with full-size refrigerator, stovetop, microwave and dishwasher."},{"question":"What is the pet policy?","answer":"Pets are allowed with no breed or weight restrictions, up to two per suite; the fee depends on whether the stay is under or over seven nights."},{"question":"What time is check-in?","answer":"Check-in is 4:00 PM and check-out is 11:00 AM."}]'::jsonb, updated_at=now() WHERE id='b413b339-b591-434f-90e3-0400b4f1a104';
UPDATE hotels SET description='SpringHill Suites Des Moines West is a 97-suite Marriott hotel on Jordan Creek Pkwy in West Des Moines, off I-80 exit 121 and about 9 miles from Des Moines International Airport. Built in 2005 and renovated in 2012, it gives each suite separate sleeping and living areas with a sofa bed, microwave and mini fridge. Free breakfast, complimentary parking, Wi-Fi, an indoor pool, hot tub and fitness center are included. The Prairie Rose Room seats up to 50. Up to two pets are accepted for a per-stay fee. Check-in 3:00 PM, check-out noon.', short_description='97-suite Marriott off I-80 exit 121 in West Des Moines, with free breakfast, an indoor pool and free parking.', seo_title='SpringHill Suites Des Moines West | Hotels in WDM, IA', seo_description='SpringHill Suites Des Moines West on Jordan Creek Pkwy: 97 suites off I-80 exit 121 with free breakfast, indoor pool, hot tub and free parking.', seo_h1='SpringHill Suites Des Moines West, West Des Moines', geo_summary='SpringHill Suites Des Moines West is a 97-suite Marriott on Jordan Creek Pkwy in West Des Moines, off I-80 exit 121. It suits families and business travellers who want a separate living area, free breakfast and an indoor pool.', geo_key_facts=ARRAY['97 suites, built 2005, renovated 2012','Off I-80 exit 121, about 9 miles from Des Moines International Airport','Free breakfast and complimentary parking','Indoor pool, hot tub, fitness center','Check-in 3:00 PM, check-out 12:00 PM','Pets: max 2, non-refundable per-stay fee']::text[], geo_faq='[{"question":"How far is SpringHill Suites Des Moines West from the airport?","answer":"About 9 miles from Des Moines International Airport, per a venue directory."},{"question":"Does the hotel allow pets?","answer":"Yes, up to two pets with a non-refundable fee per stay."},{"question":"Is parking free?","answer":"Yes, parking is complimentary."}]'::jsonb, updated_at=now() WHERE id='e5a29247-0178-420e-abae-8dfc3f5f1502';
UPDATE hotels SET description='Staybridge Suites Des Moines Downtown is a 111-suite extended-stay hotel on E Locust St in the East Village, opened in 2016 across four floors. The Iowa State Capitol and the federal and state courthouses are within walking distance, and Wells Fargo Arena, the Iowa Events Center and the Des Moines Civic Center are minutes away. Suites have kitchens. Free hot breakfast, an evening reception Monday-Wednesday, an indoor heated pool, hot tub, fitness center and guest laundry are included; on-site parking costs extra. Check-in 3:00 PM (age 21+), check-out 11:00 AM.', short_description='111-suite East Village extended stay near the Iowa State Capitol, with kitchens, free hot breakfast and an indoor pool.', seo_title='Staybridge Suites Des Moines Downtown | East Village Hotel', seo_description='Staybridge Suites Des Moines Downtown in the East Village: 111 suites with kitchens, free hot breakfast, indoor pool, walkable to the Iowa State Capitol.', seo_h1='Staybridge Suites Des Moines Downtown', geo_summary='Staybridge Suites Des Moines Downtown is a 111-suite extended-stay hotel in the East Village, walking distance from the Iowa State Capitol and the courthouses. It suits legislative, legal and event travellers who want a kitchen and a downtown base.', geo_key_facts=ARRAY['111 suites over four floors, opened 2016','East Village, walking distance to the Iowa State Capitol','About 4.25 miles from Des Moines International Airport','Free hot breakfast; evening reception Mon-Wed','On-site parking for a fee','Check-in 3:00 PM (minimum age 21), check-out 11:00 AM']::text[], geo_faq='[{"question":"Is parking free at Staybridge Suites Des Moines Downtown?","answer":"No, on-site parking carries a fee."},{"question":"How far is the hotel from the airport?","answer":"About 4.25 miles from Des Moines International Airport."},{"question":"Are pets allowed?","answer":"Yes, for an additional fee; AAA advises calling the hotel about restrictions."}]'::jsonb, updated_at=now() WHERE id='1f57a142-3386-45e8-b4fd-c706eddcb1da';
UPDATE hotels SET description='Staybridge Suites Des Moines North - Ankeny is an IHG extended-stay hotel on S Hulsizer Rd in Ankeny, and the hotel bills itself as an extended stay near the High Trestle Trail. Hot breakfast is included daily, served 6:30-9:30 AM on weekdays and 6:00-10:00 AM on weekends. A social hour with free appetizers and drinks runs 5:30-7:00 PM Monday through Wednesday. The hotel lists parking, a pool, a fitness center, Wi-Fi and pet-friendly suites. Check-in is 3:00 PM with a minimum age of 21, and check-out is 11:00 AM.', short_description='Extended-stay suites in Ankeny near the High Trestle Trail, with daily hot breakfast, a pool and a Mon-Wed social hour.', seo_title='Staybridge Suites Des Moines North - Ankeny | Ankeny, IA', seo_description='Staybridge Suites Des Moines North in Ankeny: extended-stay suites near the High Trestle Trail with daily hot breakfast, a pool and pet-friendly suites.', seo_h1='Staybridge Suites Des Moines North - Ankeny', geo_summary='Staybridge Suites Des Moines North - Ankeny is an IHG extended-stay hotel on S Hulsizer Rd near the High Trestle Trail. It suits longer work stays and trail riders in Ankeny who want daily breakfast, a pool and room for a pet.', geo_key_facts=ARRAY['Address: 2602 S Hulsizer Rd, Ankeny, IA 50021','Check-in 3:00 PM (minimum age 21), check-out 11:00 AM','Hot breakfast daily, 6:30-9:30 AM weekdays','Social hour 5:30-7:00 PM, Monday-Wednesday','Pool, fitness center, Wi-Fi, pet friendly']::text[], geo_faq='[{"question":"What time is breakfast at Staybridge Suites Ankeny?","answer":"6:30-9:30 AM Monday-Friday and 6:00-10:00 AM Saturday-Sunday."},{"question":"What are check-in and check-out times?","answer":"Check-in is 3:00 PM (minimum age 21) and check-out is 11:00 AM."},{"question":"Is there an evening reception?","answer":"Yes, free appetizers and beverages 5:30-7:00 PM Monday, Tuesday and Wednesday."}]'::jsonb, updated_at=now() WHERE id='74bd0410-1c37-43ff-a699-04b1ca0f7439';
UPDATE hotels SET description='Staybridge Suites West Des Moines is a 90-suite extended-stay hotel on Lake Dr, directly off I-80 exit 121 and about 9 miles from Des Moines International Airport. Built in 2000 and renovated in 2018, it gives every suite a full kitchen. Free breakfast and free parking are included, and there is a pool, fitness center and business center. A free evening reception runs Monday through Wednesday. Pets are allowed; third-party listings note up to two, a weight limit and a fee. Check-in is 3:00 PM and check-out is noon.', short_description='90-suite extended stay off I-80 exit 121 in West Des Moines, with full kitchens, free breakfast and free parking.', seo_title='Staybridge Suites West Des Moines | Extended Stay in WDM', seo_description='Staybridge Suites West Des Moines on Lake Dr: 90 suites with full kitchens off I-80 exit 121, free breakfast and parking, pool and pet-friendly rooms.', seo_h1='Staybridge Suites West Des Moines', geo_summary='Staybridge Suites West Des Moines is a 90-suite extended-stay hotel on Lake Dr, directly off I-80 exit 121. It suits longer business stays and relocations that need a full kitchen, free parking and breakfast.', geo_key_facts=ARRAY['90 suites, each with a full kitchen','Built 2000, renovated 2018','Off I-80 exit 121, about 9 miles from Des Moines International Airport','Free breakfast and free parking','Free evening reception Mon-Wed','Check-in 3:00 PM, check-out 12:00 PM']::text[], geo_faq='[{"question":"Do suites have kitchens?","answer":"Yes, every suite has a full kitchen."},{"question":"How far is the hotel from the airport?","answer":"About 9 miles from Des Moines International Airport, per a venue directory."},{"question":"Is parking free?","answer":"Yes, parking is free."}]'::jsonb, updated_at=now() WHERE id='72168cf1-a877-4210-951a-ca39264647e3';
UPDATE hotels SET description='Stoney Creek Hotel Des Moines Johnston is a 164-room lodge-style hotel on Stoney Creek Ct in Johnston, off I-80 at the 86th Street exit and under 10 minutes'' drive from downtown Des Moines. It was one of the first Stoney Creek hotels. Guests get free hot breakfast at the Chuckwagon, a heated indoor/outdoor pool, a 24-hour fitness center and guest laundry. Pioneer''s Pour House in the lobby pours Iowa craft beers and cocktails. Extended-stay rooms have kitchens, some rooms are pet friendly, and the Northwoods Ballroom seats up to 400.', short_description='164-room lodge-style hotel in Johnston off I-80 at 86th Street, with an indoor/outdoor pool, free breakfast and a lobby bar.', seo_title='Stoney Creek Hotel Des Moines Johnston | Johnston, IA', seo_description='Stoney Creek Hotel in Johnston: 164 lodge-style rooms off I-80 at 86th Street, indoor/outdoor pool, free hot breakfast and the Pioneer''s Pour House bar.', seo_h1='Stoney Creek Hotel Des Moines Johnston', geo_summary='Stoney Creek Hotel Des Moines Johnston is a 164-room lodge-style hotel and conference center off I-80 at the 86th Street exit. It suits families, wedding parties and conference groups who want a pool, a lobby bar and ballroom space in Johnston.', geo_key_facts=ARRAY['164 rooms, rustic lodge-style decor','Off I-80 at the 86th Street exit, under 10 minutes to downtown','Free hot breakfast at the Chuckwagon','Heated indoor/outdoor pool, 24-hour fitness center','Northwoods Ballroom seats up to 400 theater-style','Check-in 3:00 PM, check-out 11:00 AM']::text[], geo_faq='[{"question":"How far is Stoney Creek Johnston from downtown Des Moines?","answer":"The hotel says it is under 10 minutes'' drive from downtown, off I-80 at the 86th Street exit."},{"question":"Is breakfast included?","answer":"Yes, a free hot breakfast is served at the Chuckwagon."},{"question":"Are pets allowed?","answer":"Pet-friendly rooms are offered; fees and restrictions are not stated, so call ahead."}]'::jsonb, updated_at=now() WHERE id='92c8f318-70bb-4556-beac-39dd46eab80b';
UPDATE hotels SET description='Super 8 by Wyndham Altoona is a motel on Adventureland Dr in Altoona, just off I-80 at the northeast edge of Des Moines. Wyndham places it next door to Adventureland and right across from Prairie Meadows Casino and racetrack, with Ankeny Regional Airport minutes away and Des Moines International Airport a short drive. The location makes it a practical base for a day at the amusement park or a night at the casino. Wyndham''s page shows a pool in its photo gallery but did not list other amenities, so confirm breakfast, parking and pet terms with the property.', short_description='Motel just off I-80 in Altoona, next door to Adventureland and across from Prairie Meadows Casino and racetrack.', seo_title='Super 8 by Wyndham Altoona | Hotels in Altoona, IA', seo_description='Super 8 by Wyndham Altoona on Adventureland Dr: just off I-80, next door to Adventureland and across from Prairie Meadows Casino and racetrack.', seo_h1='Super 8 by Wyndham Altoona', geo_summary='Super 8 by Wyndham Altoona is a motel on Adventureland Dr, just off I-80 at the northeast edge of Des Moines. It suits visitors to Adventureland and Prairie Meadows who want to stay right beside both.', geo_key_facts=ARRAY['Address: 2101 Adventureland Dr, Altoona, IA','Just off I-80','Next door to Adventureland','Across from Prairie Meadows Casino and racetrack','Minutes from Ankeny Regional Airport (hotel)']::text[], geo_faq='[{"question":"Is Super 8 Altoona close to Adventureland?","answer":"Yes, Wyndham describes Adventureland as next door."},{"question":"How close is it to Prairie Meadows?","answer":"Wyndham says the hotel is right across from Prairie Meadows Casino and racetrack."}]'::jsonb, updated_at=now() WHERE id='4583b264-8712-484c-839c-23cec62693b9';
UPDATE hotels SET description='Super 8 by Wyndham Ankeny/Des Moines Area is a motel on SE Delaware Ave in Ankeny, off I-35 and minutes from downtown Des Moines. Wyndham lists DMACC Ankeny, Saylorville Lake, the Iowa State Fairgrounds and Wells Fargo Arena among nearby places. Guests get a free hot breakfast with biscuits and gravy and waffles, free Wi-Fi, and an indoor pool open 9 a.m. to 11 p.m. Free parking includes space for trucks, buses and RVs. Rooms have a microwave, refrigerator and coffee maker, and the property is non-smoking with accessible rooms.', short_description='Non-smoking Super 8 off I-35 in Ankeny with free hot breakfast, an indoor pool and free truck and RV parking.', seo_title='Super 8 by Wyndham Ankeny/Des Moines Area | Ankeny, IA', seo_description='Super 8 by Wyndham in Ankeny off I-35: free hot breakfast, indoor pool, free Wi-Fi and free parking with room for trucks, buses and RVs.', seo_h1='Super 8 by Wyndham Ankeny/Des Moines Area', geo_summary='Super 8 by Wyndham Ankeny/Des Moines Area is a non-smoking motel off I-35 on SE Delaware Ave in Ankeny. It suits road trippers, truck drivers and families who want free breakfast, an indoor pool and parking for large vehicles.', geo_key_facts=ARRAY['Address: 206 SE Delaware Ave, Ankeny, IA','Off I-35','Free hot breakfast and free Wi-Fi','Indoor pool open 9 a.m.-11 p.m.','Free parking for trucks, buses and RVs','Non-smoking property']::text[], geo_faq='[{"question":"Can I park a truck or RV at Super 8 Ankeny?","answer":"Yes, free parking includes space for trucks, buses and RVs."},{"question":"Is breakfast included?","answer":"Yes, a free hot breakfast with biscuits and gravy, waffles and yogurt."},{"question":"What are the pool hours?","answer":"The indoor pool is open daily 9 a.m. to 11 p.m."}]'::jsonb, updated_at=now() WHERE id='60691c2c-1637-4eec-8b40-d2a0ea6830b2';
UPDATE hotels SET description='Super 8 by Wyndham Clive IA is a motel on Forest Avenue in Clive, near I-35, I-80 and I-235. Living History Farms is about a mile from the hotel, and Wyndham also lists the Clive Aquatic Center, Valley West Mall and Jordan Creek Town Center nearby. A free continental breakfast, free in-room Wi-Fi and guest laundry are included. Large-vehicle parking comes with plug-ins. A hot tub suite is available, and accessible and pet-friendly rooms can be requested. Wyndham''s page did not show check-in times or pet fees, so confirm those with the hotel.', short_description='Super 8 in Clive about a mile from Living History Farms, with free breakfast, Wi-Fi and large-vehicle parking with plug-ins.', seo_title='Super 8 by Wyndham Clive IA | Hotels in Clive, Iowa', seo_description='Super 8 by Wyndham Clive on Forest Ave: a mile from Living History Farms, near I-35/I-80, with free breakfast, Wi-Fi and large-vehicle parking.', seo_h1='Super 8 by Wyndham Clive IA', geo_summary='Super 8 by Wyndham Clive IA is a motel on Forest Avenue in Clive, about a mile from Living History Farms and close to I-35, I-80 and I-235. It suits budget-minded drivers and families who want free breakfast and easy interstate access.', geo_key_facts=ARRAY['Address: 11414 Forest Avenue, Clive, IA','About 1 mile from Living History Farms (hotel)','Near I-35, I-80 and I-235','Free continental breakfast and free Wi-Fi','Large-vehicle parking with plug-ins','Guest laundry; hot tub suite available']::text[], geo_faq='[{"question":"How far is Super 8 Clive from Living History Farms?","answer":"The hotel says Living History Farms is about a mile away."},{"question":"Is breakfast included?","answer":"Yes, a free continental breakfast with items like cereal, fruit and yogurt."},{"question":"Are pets allowed?","answer":"Pet-friendly rooms are available; fees were not stated, so ask the hotel."}]'::jsonb, updated_at=now() WHERE id='0301e877-4903-4400-9247-6f915653b14a';
UPDATE hotels SET description='Super 8 by Wyndham Des Moines is a motel at 4685 NE 14th St on Route 69 in Des Moines, off I-35 near the airport with quick access to I-235 and I-80. Wyndham lists Grand View University, Drake University, Des Moines University, Mercy Hospital, Wells Fargo Arena, the Civic Center and the Historic East Village among nearby places, along with Des Moines International Airport and Ankeny Regional Airport. The hotel''s photo gallery shows a family pool. Wyndham''s page did not list breakfast, parking or pet terms, so confirm those directly.', short_description='Motel on NE 14th St (Route 69) off I-35 in Des Moines, near Grand View University and with quick I-235 and I-80 access.', seo_title='Super 8 by Wyndham Des Moines | NE 14th St Motel', seo_description='Super 8 by Wyndham Des Moines on NE 14th St (Route 69): off I-35 with quick access to I-235 and I-80, near Grand View University and the East Village.', seo_h1='Super 8 by Wyndham Des Moines', geo_summary='Super 8 by Wyndham Des Moines is a motel on NE 14th St (Route 69), off I-35. It suits drivers who want interstate access and visitors to Grand View University or Mercy Hospital.', geo_key_facts=ARRAY['Address: 4685 A NE 14th St, Des Moines, IA 50313','On Route 69, off I-35','Quick access to I-235 and I-80','Near Grand View University and Mercy Hospital (hotel)']::text[], geo_faq='[{"question":"Which highways are near Super 8 Des Moines?","answer":"It sits on Route 69, off I-35, with quick access to I-235 and I-80."},{"question":"What universities are nearby?","answer":"Wyndham lists Grand View University, Drake University, Des Moines University and Iowa State University among nearby places."}]'::jsonb, updated_at=now() WHERE id='0861a457-0e60-4115-96da-105bf2f1d863';
